function renderPatients(){
  var db = getDB();
  console.log('[CDC] renderPatients: activeProviderId='+activeProviderId+' | total patients='+db.patients.length+' | matching='+db.patients.filter(function(p){return p.providerId===activeProviderId;}).length);
  var q = (v('pat-q')||'').toLowerCase();
  var list = db.patients.filter(function(p){ return p.providerId===activeProviderId; });
  if (q) list = list.filter(function(p){
    return ((p.last||'')+' '+(p.first||'')+' '+(p.acct||'')+' '+(p.subNum||'')+' '+(p.payerName||'')).toLowerCase().includes(q);
  });
  var el = document.getElementById('patients-tbl');
  if (!el) return;
  if (!list.length) {
    el.innerHTML = '<div class="empty"><h3>No patients found</h3><button class="btn btn-primary btn-sm" onclick="openPatientModal(-1)">+ New Patient</button></div>';
    return;
  }
  var pgSize  = window._patPgSize  || 20;
  var pgIndex = window._patPgIndex || 0;
  var total   = list.length;
  var pgCount = Math.ceil(total / pgSize);
  if (pgIndex >= pgCount) pgIndex = 0;
  window._patPgIndex = pgIndex;
  var pageList = list.slice(pgIndex * pgSize, (pgIndex+1) * pgSize);

  // Pre-index claim counts once — O(n) instead of O(n*m) per row
  var _claimCount = {};
  (db.claims||[]).forEach(function(c){
    if(c.providerId===activeProviderId) _claimCount[c.patId] = (_claimCount[c.patId]||0)+1;
  });
  var rows = pageList.map(function(p) {
    var cnt = _claimCount[p.id] || 0;
    var bg = p.sex==='F'?'#c96442':p.sex==='M'?'#2d6a4f':'#4d4c48';
    var ini = ((p.first||'?')[0]+(p.last||'?')[0]).toUpperCase();
    var isSA = (function(){ var s=getSession(); return s && s.role==='Super Admin'; })();
    var ins = _resolvePatientInsurance(p);
    var dispSub   = p.subNum    || ins.subNum   || '';
    var dispPayId = p.payerid   || ins.payerId  || '';
    var dispPayer = p.payerName || ins.name     || '';
    var dispPlan  = p.plan      || ins.plan     || '\u2014';
    var dispRel   = p.rel       || ins.rel      || '';
    return '<tr>'
      + '<td style="font-family:var(--mono);font-size:11px;color:#87867f">' + ptLinkAcct(p.id, p.acct) + '</td>'
      + '<td><div style="display:flex;align-items:center;gap:8px">'
      + '<div style="width:26px;height:26px;border-radius:50%;background:'+bg+';color:#fff;font-size:9px;font-weight:700;display:flex;align-items:center;justify-content:center;flex-shrink:0">'+ini+'</div>'
      + ptLinkName(p.id, p.last, p.first)
      + '</div></td>'
      + '<td>' + (p.dob||'') + '</td>'
      + '<td>' + dispSub + '</td>'
      + '<td>' + dispPayId + '</td>'
      + '<td>' + dispPayer + '</td>'
      + '<td>' + dispPlan + '</td>'
      + '<td>' + dispRel + '</td>'
      + '<td style="text-align:center"><span style="display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:20px;padding:0 6px;border-radius:20px;background:'+(cnt>0?'#fdf3ee':'#f8f6f0')+';color:'+(cnt>0?'#c96442':'#87867f')+';font-size:11px;font-weight:700">'+cnt+'</span></td>'
      + '<td><div style="display:flex;gap:4px;align-items:center">'
      + '<button class="btn btn-xs" onclick="openPatientChart(\'' + p.id + '\');setTimeout(function(){_renderChartTab(\'demographics\');},100)" title="Edit"><i data-lucide="pencil" class="lci" style="width:13px;height:13px"></i></button>'
      + (isSA ? '<button class="btn btn-xs btn-danger" onclick="deletePatientConfirm(\'' + p.id + '\')" title="Delete Patient" style="background:var(--red-bg);color:var(--red);border:1px solid var(--red-bdr)"><i data-lucide="trash-2" class="lci" style="width:13px;height:13px"></i></button>' : '')
      + '</div></td>'
      + '</tr>';
  }).join('');

  // Pagination buttons
  var lo = Math.max(0, pgIndex-3), hi = Math.min(pgCount-1, pgIndex+3);
  var pgBtns = '';
  if (lo > 0) { pgBtns += '<button class="pg-btn" onclick="_patGoPage(0)">1</button>' + (lo>1?'<span class="pg-ellipsis">&hellip;</span>':''); }
  for (var pi=lo; pi<=hi; pi++) {
    pgBtns += '<button class="pg-btn' + (pi===pgIndex?' pg-active':'') + '" onclick="_patGoPage(' + pi + ')">' + (pi+1) + '</button>';
  }
  if (hi < pgCount-1) { pgBtns += (hi<pgCount-2?'<span class="pg-ellipsis">&hellip;</span>':'') + '<button class="pg-btn" onclick="_patGoPage(' + (pgCount-1) + ')">' + pgCount + '</button>'; }

  var pgSizeOpts = [20,50,100].map(function(s){
    return '<option value="'+s+'"'+(s===pgSize?' selected':'')+'>'+s+' / page</option>';
  }).join('');

  var from = pgIndex*pgSize+1, to = Math.min((pgIndex+1)*pgSize, total);

  el.innerHTML =
    '<div class="tbl-wrap"><table>'
    + '<thead><tr><th>Acct#</th><th>Last, First</th><th>DOB</th><th>Subscriber ID</th><th>Payer ID</th><th>Payer</th><th>Plan</th><th>Rel</th><th>Claims</th><th></th></tr></thead>'
    + '<tbody>' + rows + '</tbody></table></div>'
    + '<div style="display:flex;align-items:center;justify-content:space-between;padding:9px 16px;border-top:1px solid var(--border);background:var(--bg2)">'
    + '<span style="font-size:11px;color:var(--text3)">'+from+'\u2013'+to+' of '+total+' patients</span>'
    + '<div style="display:flex;align-items:center;gap:8px">'
    + '<div class="pg-bar">'+pgBtns+'</div>'
    + '<select onchange="_patSetPgSize(this.value)" style="padding:3px 8px;border:1px solid var(--border2);border-radius:5px;font-size:11px;background:var(--bg2);color:var(--text);cursor:pointer">'+pgSizeOpts+'</select>'
    + '</div></div>';

  setTimeout(_renderLucideIcons, 20);
}
