function _clmSort(field) {
  if (window._clmSortField === field) {
    window._clmSortAsc = !window._clmSortAsc;
  } else {
    window._clmSortField = field;
    window._clmSortAsc = (field === 'dos' || field === 'total') ? false : true;
  }
  window._clmPgIndex = 0;
  renderClaims();
}
