// ── Date range helper for multi-date claims ───────────────────────
function claimDosRange(c) {
  if (!c) return '';
  // Collect all dates: header dos + per-line dos
  var dates = [];
  if (c.dos) dates.push(c.dos);
  if (Array.isArray(c.lines)) {
    c.lines.forEach(function(l) { if (l.dos) dates.push(l.dos); });
  }
  // Parse and sort
  var parsed = dates.map(function(d) {
    // Handle M/D/YYYY, YYYY-MM-DD, MM/DD/YYYY
    var s = String(d).trim();
    if (!s) return null;
    var dt;
    if (s.match(/^\d{4}-\d{2}-\d{2}$/)) {
      dt = new Date(s + 'T00:00:00');
    } else if (s.includes('/')) {
      var parts = s.split('/');
      if (parts[0].length === 4) {
        dt = new Date(s + 'T00:00:00');
      } else {
        dt = new Date(parseInt(parts[2]||new Date().getFullYear()), parseInt(parts[0])-1, parseInt(parts[1]));
      }
    } else {
      dt = new Date(s);
    }
    return isNaN(dt) ? null : dt;
  }).filter(Boolean).sort(function(a,b){return a-b;});

  if (!parsed.length) return c.dos || '';
  var fmt = function(dt) {
    return (dt.getMonth()+1) + '/' + dt.getDate() + '/' + dt.getFullYear();
  };
  if (parsed.length === 1) return fmt(parsed[0]);
  var first = parsed[0], last = parsed[parsed.length-1];
  if (fmt(first) === fmt(last)) return fmt(first);
  return fmt(first) + ' – ' + fmt(last);
}

function renderBills(){
  var el=document.getElementById('bills-tbl');
  if(!el)return;
  var db=getDB();
  var q=(v('bills-q')||'').toLowerCase();
  var statusF=document.getElementById('bills-status-filter')?.value||'';
  var claims=(db.claims||[]).filter(function(c){return c.providerId===activeProviderId;});
  if(statusF) claims=claims.filter(function(c){return c.status===statusF;});
  if(q) claims=claims.filter(function(c){
    var pat=db.patients.find(function(p){return p.id===c.patId;})||{};
    var searchStr=(pat.last+' '+pat.first+' '+c.pcn+' '+c.dos+' '+(c.lines||[]).map(function(l){return l.cpt;}).join(' ')).toLowerCase();
    return searchStr.includes(q);
  });
  // Sort by updatedAt desc
  claims.sort(function(a,b){return (b.updatedAt||b.createdAt||0)-(a.updatedAt||a.createdAt||0);});
  if(!claims.length){
    el.innerHTML='<div class="empty"><div class="empty-ico"><i data-lucide="file-text" class="lci" style="width:24px;height:24px"></i></div><h3>No bills found</h3><p style="font-size:12px;color:var(--text3)">Create a claim or check in a patient to get started.</p></div>';
    setTimeout(_renderLucideIcons,20);
    return;
  }
  var totalCharge=claims.reduce(function(s,c){return s+parseFloat(claimTotal(c)||0);},0);
  el.innerHTML=
    '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px 0;font-size:12px;color:var(--text3)">'+
      '<span>'+claims.length+' bill(s) · Total: <strong class="mono" style="color:var(--text)">$'+totalCharge.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',')+'</strong></span>'+
    '</div>'+
    '<div class="tbl-wrap"><table><thead><tr>'+
      '<th>PCN</th><th>Patient</th><th>DOS</th><th>CPT</th><th>Diagnoses</th><th>Total</th><th>Status</th><th></th>'+
    '</tr></thead><tbody>'+
    claims.map(function(c){
      var pat=db.patients.find(function(p){return p.id===c.patId;})||{};
      var cpts=(c.lines||[]).map(function(l){return l.cpt;}).filter(Boolean).join(', ');
      var dx=(c.dx||[]).filter(Boolean).join(', ');
      var total=claimTotal(c);
      return '<tr>'+
        '<td class="mono" style="font-size:11px">'+c.pcn+'</td>'+
        '<td style="font-weight:500">'+ptLinkName(pat.id,pat.last,pat.first)+'</td>'+
        '<td style="font-size:12px">'+c.dos+'</td>'+
        '<td style="font-size:11px;font-family:var(--mono)">'+cpts+'</td>'+
        '<td style="font-size:11px;font-family:var(--mono);max-width:160px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap" title="'+dx+'">'+dx+'</td>'+
        '<td class="mono" style="font-weight:700">$'+total.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',')+'</td>'+
        '<td>'+statusBadge(c.status)+'</td>'+
        '<td><button class="btn btn-xs" onclick="window.location.hash=\'#claim-editor?id='+c.id+'\';go(\'claim-editor\')" title="Open in editor"><i data-lucide="external-link" class="lci" style="width:13px;height:13px"></i></button></td>'+
      '</tr>';
    }).join('')+
    '</tbody></table></div>';
  setTimeout(_renderLucideIcons, 20);
}

function startNewClaim(patId, apptId, dos, apptData){
  var db=getDB();
  var pat=db.patients.find(function(p){return p.id===patId;})||{};
  var appt=apptData||{};
  var sgAsgn=(apptData||{}).sgAsgn||{};
  var claim={
    id:uid(), providerId:activeProviderId, patId:patId,
    acct:pat.acct||'', pcn:'CLM-'+Date.now(), billNum:_generateBillNum(),
    dos:dos||appt.date||'', pos:appt.pos||'11',
    multiDate:false, facilityId:appt.facilityId||'',
    renderingId:appt.renderingId||'', referringId:sgAsgn.referringId||'',
    auth:sgAsgn.auth||'', emp:'N', auto:'N',
    status:'draft', claimmdId:'', rejectReason:'',
    dx:['','','','','','','',''],
    lines:[], totalCharge:'0.00', apptId:apptId||'',
    createdAt:Date.now(), updatedAt:Date.now()
  };
  var sg=(db.serviceGroups||[]).find(function(g){return g.id===(appt.sgId||sgAsgn.sgId);});
  if(sg&&sgAsgn){
    var dxList=(sgAsgn.dx||'').split(',').map(function(d){return d.trim().toUpperCase();}).filter(Boolean);
    for(var di=0;di<8;di++) claim.dx[di]=dxList[di]||'';
    (sg.lines||[]).forEach(function(l){
      var ppu=parseFloat(l.pricePerUnit||0)||(parseFloat(l.charge||0)/Math.max(parseInt(l.units||1),1));
      var units=Math.max(parseInt(l.units||1),1);
      claim.lines.push({
        cpt:l.cpt, mod1:l.mod1||'', mod2:l.mod2||'', mod3:l.mod3||'', mod4:l.mod4||'',
        dxPtr:dxList.length?'A':'', units:String(units),
        charge:(ppu*units).toFixed(2), epsdt:'N', emg:'N'
      });
    });
  }
  claim.totalCharge=claim.lines.reduce(function(s,l){return s+parseFloat(l.charge||0);},0).toFixed(2);
  setDB(function(db2){db2.claims.push(claim);});
  return claim.id;
}


// ── Bill Number generator ─────────────────────────────────────────────────
// Format: YYMMDDHHmm + 4 random digits = 14-digit numeric, no letters
// Guaranteed unique per session; collision probability negligible in practice
function _generateBillNum() {
  var now = new Date();
  var yy  = String(now.getFullYear()).slice(-2);
  var mm  = String(now.getMonth()+1).padStart(2,'0');
  var dd  = String(now.getDate()).padStart(2,'0');
  var hh  = String(now.getHours()).padStart(2,'0');
  var mi  = String(now.getMinutes()).padStart(2,'0');
  var ss  = String(now.getSeconds()).padStart(2,'0');
  var rnd = String(Math.floor(Math.random()*9000)+1000); // 4 digits, never 0000
  return yy + mm + dd + hh + mi + ss + rnd; // 14 digits total
}

