function updateBadges(){
if(!activeProviderId) return;
const db=getDB();
const mine=db.claims.filter(c=>c.providerId===activeProviderId);
const el=document.getElementById('nc-claims'); if(el) el.textContent=mine.length;
const errs=mine.reduce((s,c)=>s+validateClaim(c).length,0);
const nb=document.getElementById('nc-errs');
if(nb){ if(errs){nb.classList.remove('hidden');nb.textContent=errs;}else nb.classList.add('hidden'); }
const total=mine.reduce((s,c)=>s+claimTotal(c),0);
const ts=document.getElementById('tb-stats');
if(ts) ts.textContent=`${mine.length} claims \u00b7 $${fmtMoney(total)}`;

}






function deletePatientConfirm(patId) {
  const db = getDB();
  const pat = db.patients.find(p => p.id === patId);
  if (!pat) return;
  const name = (pat.last||'') + ', ' + (pat.first||'');
  if (!confirm('DELETE patient: ' + name + '\n\nThis will also delete all claims for this patient. This action CANNOT be undone.\n\nAre you sure?')) return;
  setDB(db2 => {
    db2.patients = (db2.patients||[]).filter(p => p.id !== patId);
    db2.claims   = (db2.claims||[]).filter(c => c.patId !== patId);
  });
  toast('Patient deleted','ok');
  renderPatients();
}

function openPatientModal(idx) {
const db = getDB();
if (idx >= 0) {
// EDIT — open existing patient chart to Demographics tab
const pat = db.patients[idx];
if (!pat) { toast('Patient not found', 'err'); return; }
openPatientChart(pat.id);
setTimeout(() => _renderChartTab('summary'), 100);
} else {
// NEW PATIENT — create a blank record then open chart to Demographics
if (!activeProviderId) { toast('Select a billing provider first', 'warn'); return; }
const newPat = {
id: uid(),
providerId: activeProviderId,
acct: buildNextPCN('', activeProviderId, []).replace('PCN','PT') || ('PT' + Date.now().toString().slice(-5)),
last: '', first: '', mid: '', dob: '', sex: 'F',
addr1: '', addr2: '', city: '', state: '', zip: '',
phone: '', phone2: '', email: '',
payerName: '', payerid: '', subNum: '', groupNum: '',
insurances: [],
inactive: false,
createdAt: Date.now(),
};
// Generate proper account number — guaranteed unique within this provider
const existingAccts = db.patients.map(p => parseInt((p.acct||'0').replace(/\D/g,''))||0);
let maxAcct = existingAccts.length ? Math.max(...existingAccts) : 0;
let candidateAcct = String(maxAcct + 1);
while (db.patients.find(p => String(p.acct||'').trim().toLowerCase()===candidateAcct.toLowerCase() && p.providerId===activeProviderId)) {
  maxAcct++;
  candidateAcct = String(maxAcct + 1);
}
newPat.acct = candidateAcct;
setDB(db2 => { db2.patients.push(newPat); });
openPatientChart(newPat.id);
setTimeout(() => _renderChartTab('demographics'), 100);
}
}

