function updateTotal() {
const mcTot = document.getElementById('mc-total');
if (!mcTot) return;
const sum = tmpLines.reduce((s,l)=>s+(parseFloat(l.charge)||0),0);
mcTot.textContent = 'Total: $' + sum.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,',');
}

// Resolve active insurance — checks pat.insurances[] (Coverage tab) first, falls back to legacy fields
function _resolvePatientInsurance(pat) {
    var ins = (pat.insurances||[]).find(function(iv){
      return !iv.inactive && ((iv.insType||iv.type||'primary').toLowerCase().includes('primary'));
    }) || (pat.insurances||[]).find(function(iv){ return !iv.inactive; });
    if (ins) {
      return {
        payerId:  ins.payerId  || ins.payerid  || pat.payerid  || '',
        name:     ins.name     || ins.payerName || pat.payerName || '',
        subNum:   ins.policy   || ins.subNum    || pat.subNum   || '',
        subLast:  ins.subLast  || pat.subLast   || '',
        subFirst: ins.subFirst || pat.subFirst  || '',
        subDob:   ins.subDob   || pat.subDob    || '',
        group:    ins.group    || ins.groupNum   || pat.group   || '',
        plan:     ins.plan     || pat.plan       || '',
        rel:      ins.rel      || pat.rel        || '18',
      };
    }
    // Legacy fallback
    return {
      payerId:  pat.payerid   || '',
      name:     pat.payerName || '',
      subNum:   pat.subNum    || '',
      subLast:  pat.subLast   || '',
      subFirst: pat.subFirst  || '',
      subDob:   pat.subDob    || '',
      group:    pat.group     || '',
      plan:     pat.plan      || '',
      rel:      pat.rel       || '18',
    };
  }
function onPatientChange() {
const patId = document.getElementById('mc-pat')?.value;
if (!patId) return;
const db = getDB();
const pat = db.patients.find(p=>p.id===patId);
if (!pat) return;
sv('mc-acct', pat.acct||'');
window._mcActiveIns = _resolvePatientInsurance(pat);
}
function openClaimModal(idx){
  var db=getDB();
  var provId=activeProviderId||(db.providers&&db.providers[0]?db.providers[0].id:'');
  var claimId;

  if(idx>=0){
    var c=db.claims[idx];
    if(!c){toast('Claim not found','err');return;}
    claimId=c.id;
  } else {
    var newId=uid();
    var pcn=typeof buildNextPCN==='function'?buildNextPCN('',provId,db.claims):('PCN'+Date.now());
    var billNum=_generateBillNum();
    var rends=(db.rendering||[]).filter(function(r){return r.providerId===provId;});
    var newClaim={
      id:newId, providerId:provId,
      pcn:pcn, billNum:billNum, patId:'', acct:'',
      dos:today(), pos:'11',
      facilityId:'', renderingId:rends.length?rends[0].id:'',
      referringId:'', auth:'',
      dx:['','','','','','','',''],
      lines:[], status:'draft',
      emp:'N', auto:'N',
      createdAt:Date.now(), updatedAt:Date.now()
    };
    setDB(function(db2){ db2.claims.push(newClaim); });
    claimId=newId;
    // Store claim directly so renderClaimEditor finds it even if getDB() is stale
    window._ceCurrentClaim=newClaim;
  }

  window._ceActiveTab='services';
  window._ceClaimId=claimId;
  window._ceClaimIdStored=claimId;

  document.querySelectorAll('.section').forEach(function(e){
    e.style.display='none'; e.classList.remove('active');
  });
  var sec=document.getElementById('sec-claim-editor');
  if(sec){ sec.style.display='flex'; sec.classList.add('active'); }
  try{ setActiveTopNav('claim-editor'); }catch(_){}
  var tbt=document.getElementById('tb-title');
  if(tbt) tbt.textContent='Claim Editor';
  renderClaimEditor();
}
function saveFacility() {
const nameVal = v('mfac-name');
if (!nameVal || !nameVal.trim()) { toast('Facility name is required', 'err'); return; }

const db = getDB();
const fid = v('mfac-id') || '';
const isNew = !fid;
const exist = isNew ? null : db.facilities.find(x => x.id === fid);

const f = {
id: isNew ? uid() : fid,
providerId: activeProviderId,
name: v('mfac-name').trim(),
npi: (v('mfac-npi') || '').trim(),
pos: v('mfac-pos') || '11',
addr1: (v('mfac-addr1') || '').trim(),
addr2: (v('mfac-addr2') || '').trim(),
city: (v('mfac-city') || '').trim(),
state: (v('mfac-state') || '').trim().toUpperCase().slice(0,2),
zip: (v('mfac-zip') || '').trim(),
status: exist ? (exist.status || 'Active') : 'Active',
createdAt: exist ? (exist.createdAt || Date.now()) : Date.now(),
updatedAt: Date.now(),
};

setDB(db2 => {
const idx = db2.facilities.findIndex(x => x.id === f.id);
if (idx >= 0) db2.facilities[idx] = f;
else db2.facilities.push(f);
});

closeModal('modal-facility');
renderFacilities();
toast(isNew ? 'Facility added ?' : 'Facility updated ?');
}


function toggleFacilityStatus(fid) {
const db = getDB();
const f = db.facilities.find(x => x.id === fid);
if (!f) return;
const newStatus = f.status === 'Inactive' ? 'Active' : 'Inactive';
setDB(db2 => {
const idx = db2.facilities.findIndex(x => x.id === fid);
if (idx >= 0) { db2.facilities[idx].status = newStatus; db2.facilities[idx].updatedAt = Date.now(); }
});
renderFacilities();
toast(`Facility ${newStatus === 'Active' ? 'activated' : 'deactivated'}`);
}

function deleteFacility(fid) {
const db = getDB();
const f = db.facilities.find(x => x.id === fid);
if (!f) return;
if (!confirm(`Delete facility "${f.name}"?\nClaims using this facility will keep their reference.`)) return;
setDB(db2 => { db2.facilities = db2.facilities.filter(x => x.id !== fid); });
renderFacilities();
toast('Facility deleted');
}






function renderFacilities() {
const db = getDB();
const list = db.facilities.filter(f => f.providerId === activeProviderId);
const el = document.getElementById('facilities-tbl');
if (!el) return;

if (!list.length) {
el.innerHTML = `<div class="empty">
<div class="empty-ico"><i data-lucide="building-2" class="lci" style="width:40px;height:40px;color:var(--text3)"></i></div>
<h3>No facilities yet</h3>
<button class="btn btn-primary btn-sm" onclick="openFacilityModal('')">+ New Facility</button>
</div>`;
_renderLucideIcons(); return;
}

el.innerHTML = `<div class="tbl-wrap"><table>
<thead><tr>
<th>Name</th><th>NPI</th><th>POS</th><th>Address</th><th>Status</th><th style="width:120px">Actions</th>
</tr></thead><tbody>` +
list.map(f => {
const posLabel = (POS_CODES.find(([c]) => c === (f.pos||'11')) || [f.pos||'11',''])[1];
const active = f.status !== 'Inactive';
return `<tr style="opacity:${active?'1':'0.6'}">
<td style="font-weight:600;color:var(--text)">${f.name}</td>
<td class="mono" style="font-size:12px">${f.npi||''}</td>
<td><span class="badge b-gray" style="font-size:10px">${f.pos||'11'} — ${posLabel}</span></td>
<td style="font-size:12px;color:var(--text2)">${[f.addr1,f.city,f.state,f.zip].filter(Boolean).join(', ')||''}</td>
<td><span class="badge ${active?'b-green':'b-gray'}">${active?'Active':'Inactive'}</span></td>
<td>
<div class="btn-group" style="gap:4px">
<button class="btn-icon sm" onclick="openFacilityModal('${f.id}')" title="Edit">
<i data-lucide="pencil" class="lci" style="width:13px;height:13px"></i>
</button>
<button class="btn-icon sm" onclick="toggleFacilityStatus('${f.id}')"
title="${active?'Deactivate':'Activate'}"
style="color:${active?'var(--amber)':'var(--brand)'}">
<i data-lucide="${active?'pause-circle':'play-circle'}" class="lci" style="width:13px;height:13px"></i>
</button>
<button class="btn-icon sm danger" onclick="deleteFacility('${f.id}')" title="Delete">
<i data-lucide="trash-2" class="lci" style="width:13px;height:13px"></i>
</button>
</div>
</td>
</tr>`;
}).join('') +
`</tbody></table></div>`;
_renderLucideIcons();
}




function renderRendering(){ const db=getDB(); const list=db.rendering.filter(r=>r.providerId===activeProviderId); const el=document.getElementById('rendering-tbl'); if(!list.length){ el.innerHTML=`<div class="empty"><div class="empty-ico"><i data-lucide="user-round" class="lci" style="width:24px;height:24px"></i></div><h3>No rendering providers</h3><button class="btn btn-primary btn-sm" onclick="openRenderingModal(-1)">+ Add</button></div>`; return; } el.innerHTML=`<div class="tbl-wrap"><table><thead><tr><th>Last, First</th><th>NPI</th><th>Taxonomy</th><th>Tax ID</th><th></th></tr></thead><tbody>`+list.map(r=>{ const oi=db.rendering.findIndex(x=>x.id===r.id); return`<tr><td style="font-weight:600">${r.last}, ${r.first}</td><td class="mono">${r.npi}</td><td class="mono">${r.taxonomy||'\u2014'}</td><td class="mono">${r.taxid||'\u2014'}</td><td><button class="btn btn-xs" onclick="openRenderingModal(${oi})">Edit</button></td></tr>`;}).join('')+`</tbody></table></div>`; }




function renderValidation(){
const db=getDB(); const claims=db.claims.filter(c=>c.providerId===activeProviderId); const el=document.getElementById('val-content');
if(!claims.length){ el.innerHTML='<div class="alert al-warn">No claims to validate.</div>'; return; }
const all=claims.map(c=>({c,errs:validateClaim(c)})); const totalErrs=all.reduce((s,x)=>s+x.errs.length,0); const total=claims.reduce((s,c)=>s+claimTotal(c),0);
el.innerHTML=(totalErrs===0?`<div class="alert al-success"><i data-lucide="check-circle" class="lci" style="width:13px;height:13px;color:var(--green)"></i> <strong>${claims.length} claim(s) valid.</strong> Total: $${fmtMoney(total)}</div>`:`<div class="alert al-error"><i data-lucide="x-circle" class="lci" style="width:13px;height:13px;color:var(--red)"></i> <strong>${totalErrs} error(s)</strong> in ${all.filter(x=>x.errs.length).length} claim(s).</div>`)+`<div class="card"><div class="card-title" style="margin-bottom:12px">Detail</div>`+all.map(({c,errs})=>{ const p=db.patients.find(x=>x.id===c.patId)||{last:'?',first:'?'}; return`<div style="padding:9px 0;border-bottom:1px solid var(--border)"><div style="display:flex;justify-content:space-between;align-items:center"><div style="display:flex;align-items:center;gap:8px"><div style="width:8px;height:8px;border-radius:50%;background:${errs.length?'var(--red)':'var(--green)'};flex-shrink:0"></div><span style="font-weight:600">${c.pcn}</span><span style="color:var(--text3);font-size:12px">\u2014 ${ptLinkName(p.id,p.last,p.first)} \u2014 ${c.dos}</span></div><div style="display:flex;align-items:center;gap:8px"><span class="mono" style="font-size:12px;font-weight:700">$${fmtMoney(claimTotal(c))}</span>${errs.length?`<span class="badge b-red">${errs.length} err</span>`:'<span class="badge b-green"><i data-lucide="check" class="lci" style="width:13px;height:13px;color:var(--green)"></i> OK</span>'}</div></div>${errs.length?`<ul style="padding:4px 0 4px 20px;font-size:12px;color:var(--red);margin-top:4px">${errs.map(e=>`<li>${e}</li>`).join('')}</ul>`:''}</div>`;}).join('')+`</div>`;
}


function renderExportSummary(){
const db=getDB(); const claims=db.claims.filter(c=>c.providerId===activeProviderId);
const total=claims.reduce((s,c)=>s+claimTotal(c),0); const pending=claims.filter(c=>c.status==='pending').length; const errs=claims.reduce((s,c)=>s+validateClaim(c).length,0);
const sumEl=document.getElementById('exp-summary'); if(sumEl) sumEl.innerHTML=`<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px"><div style="background:var(--bg3);border-radius:var(--r);padding:10px;text-align:center"><div style="font-size:20px;font-weight:700;color:var(--brand)">${claims.length}</div><div style="font-size:11px;color:var(--text3)">Total claims</div></div><div style="background:var(--bg3);border-radius:var(--r);padding:10px;text-align:center"><div style="font-size:20px;font-weight:700;color:var(--green)">$${fmtMoney(total)}</div><div style="font-size:11px;color:var(--text3)">Total charges</div></div><div style="background:var(--amber-bg);border-radius:var(--r);padding:10px;text-align:center"><div style="font-size:20px;font-weight:700;color:var(--amber)">${pending}</div><div style="font-size:11px;color:var(--text3)">Pending</div></div><div style="background:${errs?'var(--red-bg)':'var(--green-bg)'};border-radius:var(--r);padding:10px;text-align:center"><div style="font-size:20px;font-weight:700;color:${errs?'var(--red)':'var(--green)'}">${errs||'<i data-lucide="check" class="lci" style="width:13px;height:13px;color:var(--green)"></i>'}</div><div style="font-size:11px;color:var(--text3)">${errs?'Errors':'No errors'}</div></div></div>`;
const ea=document.getElementById('exp-alert-top'); if(ea) ea.innerHTML=errs?`<div class="alert al-warn"><i data-lucide="alert-triangle" class="lci" style="width:13px;height:13px"></i> ${errs} error(s). <a href="#" onclick="go('validate');return false" style="font-weight:600">Review <i data-lucide="arrow-right" class="lci" style="width:11px;height:11px"></i></a></div>`:pending?`<div class="alert al-success"><i data-lucide="check-circle" class="lci" style="width:13px;height:13px;color:var(--green)"></i> ${pending} claim(s) ready to export.</div>`:`<div class="alert al-info"><i data-lucide="info" class="lci" style="width:13px;height:13px;color:var(--brand)"></i> No pending claims.</div>`;
}


