function renderPayerReport(el) {
  var db = getDB();
  var claims = db.claims.filter(function(c){ return c.providerId===activeProviderId; });
  var byPayer = {};
  claims.forEach(function(c) {
    var p2 = db.patients.find(function(x){ return x.id===c.patId; });
    var k = (p2&&(p2.payerName||p2.payerid)) || 'Unknown';
    if (!byPayer[k]) byPayer[k]={total:0,cnt:0,accepted:0,rejected:0};
    byPayer[k].total+=claimTotal(c); byPayer[k].cnt++;
    if (c.status==='accepted') byPayer[k].accepted+=claimTotal(c);
    if (c.status==='rejected') byPayer[k].rejected++;
  });
  var rows3 = Object.entries(byPayer).sort(function(a,b){ return b[1].total-a[1].total; });
  var grandTotal = claims.reduce(function(s,c){ return s+claimTotal(c); },0);
  var grandAccepted = claims.filter(function(c){ return c.status==='accepted'; }).reduce(function(s,c){ return s+claimTotal(c); },0);
  el.innerHTML =
    '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px">' +
      '<span style="font-size:12px;color:var(--text3)">' + rows3.length + ' payers · ' + claims.length + ' claims</span>' +
      '<div style="margin-left:auto;display:flex;gap:6px">' +
        '<button onclick="exportPayerReportPDF()" class="btn btn-ghost btn-sm"><i data-lucide="file-text" class="lci" style="width:13px;height:13px"></i> PDF</button>' +
        '<button onclick="exportPayerReportXLSX()" class="btn btn-ghost btn-sm"><i data-lucide="table" class="lci" style="width:13px;height:13px"></i> Excel</button>' +
      '</div>' +
    '</div>' +
    '<div class="tbl-wrap"><table><thead><tr><th>Payer</th><th>Claims</th><th>Total Billed</th><th>Accepted</th><th>Rejected</th><th>Collection Rate</th></tr></thead><tbody>' +
    rows3.map(function(r){
      var rate = r[1].total > 0 ? (r[1].accepted/r[1].total*100).toFixed(1) : '—';
      return '<tr><td style="font-weight:600">' + r[0] + '</td><td>' + r[1].cnt + '</td><td>' + money(r[1].total) + '</td><td style="color:var(--green)">' + money(r[1].accepted) + '</td><td style="color:var(--red)">' + r[1].rejected + '</td><td style="font-weight:600">' + rate + '%</td></tr>';
    }).join('') +
    '<tr style="background:var(--bg3);font-weight:700"><td>Total</td><td>' + claims.length + '</td><td>' + money(grandTotal) + '</td><td style="color:var(--green)">' + money(grandAccepted) + '</td><td style="color:var(--red)">' + claims.filter(function(c){ return c.status==='rejected'; }).length + '</td><td>' + (grandTotal>0?(grandAccepted/grandTotal*100).toFixed(1):'—') + '%</td></tr>' +
  '</tbody></table></div>';
}

function renderProviderReport(el) {
  var db = getDB();
  var claims = db.claims.filter(function(c){ return c.providerId===activeProviderId; });
  var provs = db.providers||[];
  var byProv = {};
  claims.forEach(function(c) {
    var pid = c.providerId||'unknown';
    if (!byProv[pid]) byProv[pid]={total:0,cnt:0,accepted:0,rejected:0};
    byProv[pid].total+=claimTotal(c); byProv[pid].cnt++;
    if (c.status==='accepted') byProv[pid].accepted+=claimTotal(c);
    if (c.status==='rejected') byProv[pid].rejected++;
  });
  var rows = Object.entries(byProv).sort(function(a,b){ return b[1].total-a[1].total; });
  var grandTotal = claims.reduce(function(s,c){ return s+claimTotal(c); },0);
  el.innerHTML =
    '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px">' +
      '<span style="font-size:12px;color:var(--text3)">' + rows.length + ' providers · ' + claims.length + ' claims</span>' +
      '<div style="margin-left:auto;display:flex;gap:6px">' +
        '<button onclick="exportProviderReportPDF()" class="btn btn-ghost btn-sm"><i data-lucide="file-text" class="lci" style="width:13px;height:13px"></i> PDF</button>' +
        '<button onclick="exportProviderReportXLSX()" class="btn btn-ghost btn-sm"><i data-lucide="table" class="lci" style="width:13px;height:13px"></i> Excel</button>' +
      '</div>' +
    '</div>' +
    '<div class="tbl-wrap"><table><thead><tr><th>Provider</th><th>NPI</th><th>Claims</th><th>Total Billed</th><th>Accepted</th><th>Rejected</th></tr></thead><tbody>' +
    rows.map(function(r){
      var prov = provs.find(function(p){ return p.id===r[0]; })||{};
      return '<tr><td style="font-weight:600">' + (prov.name||r[0]) + '</td><td class="mono">' + (prov.npi||'') + '</td><td>' + r[1].cnt + '</td><td>' + money(r[1].total) + '</td><td style="color:var(--green)">' + money(r[1].accepted) + '</td><td style="color:var(--red)">' + r[1].rejected + '</td></tr>';
    }).join('') +
    '<tr style="background:var(--bg3);font-weight:700"><td>Total</td><td></td><td>' + claims.length + '</td><td>' + money(grandTotal) + '</td><td style="color:var(--green)">' + money(claims.filter(function(c){ return c.status==='accepted'; }).reduce(function(s,c){ return s+claimTotal(c); },0)) + '</td><td style="color:var(--red)">' + claims.filter(function(c){ return c.status==='rejected'; }).length + '</td></tr>' +
  '</tbody></table></div>';
}

function renderProcedureReport(el) {
  var db = getDB();
  var claims = db.claims.filter(function(c){ return c.providerId===activeProviderId; });
  var byProc = {};
  claims.forEach(function(c) {
    (c.lines||[]).forEach(function(l){
      var cpt = l.cpt||'Unknown';
      if (!byProc[cpt]) byProc[cpt]={cnt:0,total:0,units:0};
      byProc[cpt].cnt++;
      byProc[cpt].total += (parseFloat(l.charge)||0);
      byProc[cpt].units += parseInt(l.units)||1;
    });
  });
  var rows = Object.entries(byProc).sort(function(a,b){ return b[1].cnt-a[1].cnt; });
  var grandTotal = rows.reduce(function(s,r){ return s+r[1].total; },0);
  var grandUnits = rows.reduce(function(s,r){ return s+r[1].units; },0);
  el.innerHTML =
    '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px">' +
      '<span style="font-size:12px;color:var(--text3)">' + rows.length + ' procedure codes</span>' +
      '<div style="margin-left:auto;display:flex;gap:6px">' +
        '<button onclick="exportProcedureReportPDF()" class="btn btn-ghost btn-sm"><i data-lucide="file-text" class="lci" style="width:13px;height:13px"></i> PDF</button>' +
        '<button onclick="exportProcedureReportXLSX()" class="btn btn-ghost btn-sm"><i data-lucide="table" class="lci" style="width:13px;height:13px"></i> Excel</button>' +
      '</div>' +
    '</div>' +
    '<div class="tbl-wrap"><table><thead><tr><th>CPT Code</th><th>Times Billed</th><th>Total Units</th><th>Total Charges</th><th>Avg per Unit</th></tr></thead><tbody>' +
    rows.map(function(r){
      var avg = r[1].units > 0 ? money(r[1].total/r[1].units) : '$0.00';
      return '<tr><td class="mono" style="font-weight:600;color:var(--brand)">' + r[0] + '</td><td>' + r[1].cnt + '</td><td>' + r[1].units + '</td><td>' + money(r[1].total) + '</td><td>' + avg + '</td></tr>';
    }).join('') +
    '<tr style="background:var(--bg3);font-weight:700"><td>Total</td><td>' + rows.reduce(function(s,r){ return s+r[1].cnt; },0) + '</td><td>' + grandUnits + '</td><td>' + money(grandTotal) + '</td><td>' + (grandUnits>0?money(grandTotal/grandUnits):'$0.00') + '</td></tr>' +
  '</tbody></table></div>';
}

function renderMonthReport(el) {
  var db = getDB();
  var claims = db.claims.filter(function(c){ return c.providerId===activeProviderId; });
  var byMonth2 = {};
  claims.forEach(function(c) {
    var k = (c.dos||'').slice(0,7);
    if (k) { if (!byMonth2[k]) byMonth2[k]={total:0,cnt:0,accepted:0}; byMonth2[k].total+=claimTotal(c); byMonth2[k].cnt++; if (c.status==='accepted') byMonth2[k].accepted+=claimTotal(c); }
  });
  var rows4 = Object.entries(byMonth2).sort(function(a,b){ return b[0].localeCompare(a[0]); });
  var grandTotal = claims.reduce(function(s,c){ return s+claimTotal(c); },0);
  var grandAccepted = claims.filter(function(c){ return c.status==='accepted'; }).reduce(function(s,c){ return s+claimTotal(c); },0);
  el.innerHTML =
    '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:14px">' +
      '<span style="font-size:12px;color:var(--text3)">' + rows4.length + ' months · ' + claims.length + ' claims</span>' +
      '<div style="margin-left:auto;display:flex;gap:6px">' +
        '<button onclick="exportMonthReportPDF()" class="btn btn-ghost btn-sm"><i data-lucide="file-text" class="lci" style="width:13px;height:13px"></i> PDF</button>' +
        '<button onclick="exportMonthReportXLSX()" class="btn btn-ghost btn-sm"><i data-lucide="table" class="lci" style="width:13px;height:13px"></i> Excel</button>' +
      '</div>' +
    '</div>' +
    '<div class="tbl-wrap"><table><thead><tr><th>Month</th><th>Claims</th><th>Total Billed</th><th>Accepted</th><th>Avg per Claim</th></tr></thead><tbody>' +
    rows4.map(function(r){
      var avg = r[1].cnt > 0 ? money(r[1].total/r[1].cnt) : '$0.00';
      return '<tr><td style="font-weight:600">' + r[0] + '</td><td>' + r[1].cnt + '</td><td>' + money(r[1].total) + '</td><td style="color:var(--green)">' + money(r[1].accepted) + '</td><td>' + avg + '</td></tr>';
    }).join('') +
    '<tr style="background:var(--bg3);font-weight:700"><td>Total</td><td>' + claims.length + '</td><td>' + money(grandTotal) + '</td><td style="color:var(--green)">' + money(grandAccepted) + '</td><td>' + (claims.length>0?money(grandTotal/claims.length):'$0.00') + '</td></tr>' +
  '</tbody></table></div>';
}

