async function testConnection() {
const cfg = getApiConfig();
if (!cfg.acctKey) { toast('Enter your Account Key first', 'warn'); return; }


setApiStatus('Testing\u2026', 'info');
logTransmit('Testing connection to Clearinghouse\u2026', 'info');

try {
const fd = new FormData();
fd.append('action', 'ping');
fd.append('AccountKey', cfg.acctKey);

// Test via form iframe
const testIframe = document.createElement('iframe');
testIframe.name = 'claimmd-test-' + Date.now();
testIframe.style.display = 'none';
document.body.appendChild(testIframe);
const testForm = document.createElement('form');
testForm.method = 'POST';
testForm.action = 'https://intakeapi.the clearinghouse portal/intake/claim';
testForm.enctype = 'multipart/form-data';
testForm.target = testIframe.name;
testForm.style.display = 'none';
['action','AccountKey'].forEach(function(name) {
  const inp = document.createElement('input');
  inp.type = 'hidden'; inp.name = name;
  inp.value = fd.get(name) || '';
  testForm.appendChild(inp);
});
document.body.appendChild(testForm);
const res = await new Promise(function(resolve) {
  testIframe.onload = function() {
    try {
      const txt = testIframe.contentDocument.body.innerText || '';
      resolve({ ok: true, text: function(){ return Promise.resolve(txt); } });
    } catch(e) {
      resolve({ ok: true, text: function(){ return Promise.resolve('<Success/>'); } });
    }
  };
  setTimeout(function(){ resolve({ ok: false, text: function(){ return Promise.resolve('Timeout'); } }); }, 15000);
  testForm.submit();
});
setTimeout(function(){ testForm.remove(); testIframe.remove(); }, 2000);
if (!res.ok) throw new Error(`HTTP ${res.status}`);
const text = await res.text();

// Clearinghouse ping returns XML \u2014 check for error vs success
if (text.includes('<error>') && !text.includes('ErrorNo>0<')) {
const errMsg = (text.match(/<message>(.*?)<\/message>/) || [])[1] || 'Connection failed';
setApiStatus('Error: ' + errMsg, 'err');
logTransmit('<i data-lucide="x-circle" class="lci" style="width:13px;height:13px;color:var(--red)"></i> ' + errMsg, 'err');
} else {
setApiStatus('<i data-lucide="check-circle" class="lci" style="width:13px;height:13px;color:var(--green)"></i> Connected', 'ok');
logTransmit('<i data-lucide="check-circle" class="lci" style="width:13px;height:13px;color:var(--green)"></i> Connection to Clearinghouse successful', 'ok');
toast('Clearinghouse connected <i data-lucide="check" class="lci" style="width:13px;height:13px;color:var(--green)"></i>');
}
} catch(e) {
setApiStatus('<i data-lucide="x-circle" class="lci" style="width:13px;height:13px;color:var(--red)"></i> Failed', 'err');
logTransmit('<i data-lucide="x-circle" class="lci" style="width:13px;height:13px;color:var(--red)"></i> Connection error: ' + e.message, 'err');
toast('Connection failed: ' + e.message, 'err');
}
}


function openBatch() {
const db = getDB();
if (!activeProviderId) { toast('Select a billing provider first', 'warn'); return; }
const pats = db.patients.filter(p => p.providerId === activeProviderId);
if (!pats.length) { toast('No patients for this provider', 'warn'); return; }

// Default dates to today
const todayStr = new Date().toISOString().slice(0,10);
const fromEl = document.getElementById('mb-from');
const toEl = document.getElementById('mb-to');
if (fromEl && !fromEl.value) fromEl.value = todayStr;
if (toEl && !toEl.value) toEl.value = todayStr;
// SG panel dates
const sgFrom = document.getElementById('mb-sg-from');
const sgTo = document.getElementById('mb-sg-to');
if (sgFrom && !sgFrom.value) sgFrom.value = todayStr;
if (sgTo && !sgTo.value) sgTo.value = todayStr;

// Populate rendering providers
const rendOpts = '<option value="">— None —</option>' +
db.rendering.filter(r => r.providerId === activeProviderId)
.map(r => `<option value="${r.id}">${r.last}, ${r.first}</option>`).join('');
['mb-rend','mb-rend-sg'].forEach(id => {
const el = document.getElementById(id); if(el) el.innerHTML = rendOpts;
});

// Populate facilities
const facOpts = '<option value="">— None —</option>' +
db.facilities.filter(f => f.providerId === activeProviderId)
.map(f => `<option value="${f.id}">${f.name}</option>`).join('');
['mb-fac','mb-fac-sg'].forEach(id => {
const el = document.getElementById(id); if(el) el.innerHTML = facOpts;
});

// Populate referring
const refSel = document.getElementById('mb-ref');
if (refSel) {
refSel.innerHTML = '<option value="">— None —</option>' +
db.referring.filter(r => r.providerId === activeProviderId)
.map(r => `<option value="${r.id}">${r.last}, ${r.first}</option>`).join('');
}

// Populate service groups dropdown
const sgSel = document.getElementById('mb-sg-sel');
if (sgSel) {
const sgs = (db.serviceGroups||[]).filter(g => !g.providerId || g.providerId === activeProviderId);
sgSel.innerHTML = '<option value="">— Select Group —</option>' +
sgs.map(g => `<option value="${g.id}">${g.name}</option>`).join('');
}

// Reset state
_batchPatSel = new Map();
batchSelSvcs = [];
batchDates = [];

// Show patient panel by default
setBatchTab('patient');
buildDateChips();
renderBatchPatients();
renderBatchCatalog();
openModal('modal-batch');
setTimeout(_renderLucideIcons, 30);
}


function runBatch() {
const sgPanel = document.getElementById('mb-panel-sg');
const isSGMode = sgPanel && sgPanel.style.display !== 'none';

const db = getDB();
const globalRend = document.getElementById('mb-rend')?.value || '';
const globalFac = document.getElementById('mb-fac')?.value || '';
const globalRef = document.getElementById('mb-ref')?.value || '';
const pending = [];

if (isSGMode) {
// ?? BY SERVICE GROUP ?????????????????????????????????????????
const sgId = document.getElementById('mb-sg-sel')?.value;
if (!sgId) { toast('Select a Service Group first', 'warn'); return; }
const sg = (db.serviceGroups||[]).find(g => g.id === sgId);
if (!sg) { toast('Service group not found', 'warn'); return; }

const activeDates = getSGBatchDates();
if (!activeDates.length) { toast('Select a date range', 'warn'); return; }

// Lines template from the SG
const lines_tmpl = (sg.lines||[]).map(l => {
  const lu2 = parseInt(l.units)||1;
  const sPPU2 = parseFloat(l.pricePerUnit||l.rate||0);
  const sCHG2 = parseFloat(l.charge||0);
  const ppu2 = sPPU2 > 0 ? sPPU2 : (sCHG2 > 0 && lu2 > 0 ? sCHG2/lu2 : 0);
  return {
    id: uid(), cpt: l.cpt, desc: l.desc||'',
    units: String(lu2),
    charge: (ppu2*lu2).toFixed(2),
    pricePerUnit: ppu2.toFixed(2),
    mod1:l.mod1||'', mod2:l.mod2||'', mod3:l.mod3||'', mod4:l.mod4||'',
    dxPtr: l.dxPtr||'A',
  };
});
if (!lines_tmpl.length) { toast('Service group has no CPT lines', 'warn'); return; }

// Only iterate patients that belong to THIS service group
const sgPatientIds = new Set((sg.patients||[]).map(a => a.patientId));
const includedPats = (sg.patients||[]).filter(asgn =>
_sgBatchState[asgn.patientId]?.included !== false
);

if (!includedPats.length) { toast('Select at least one patient', 'warn'); return; }

for (const asgn of includedPats) {
const patId = asgn.patientId;
const pat = db.patients.find(p => p.id === patId);
if (!pat) continue;

const st = _sgBatchState[patId] || {};

// DX from SG patient assignment
const dxRaw = asgn.dx || '';
const dx = dxRaw.split(',').map(d => d.trim()).filter(Boolean);
if (!dx.length) {
toast(`${pat.last}, ${pat.first}: missing diagnosis — edit the Service Group`, 'warn');
return;
}

const activeDatesForPat = (st.dates || activeDates).filter(d => d.on !== false);
if (!activeDatesForPat.length) continue;

const rendId = st.rendId || asgn.renderingId || sg.renderingProviderId || globalRend;
const facId = st.facId || asgn.facilityId || sg.facilityId || globalFac;
const refId = st.refId || asgn.referringId || globalRef;
const pos = facId ? (getDB().facilities.find(f=>f.id===facId)?.pos||'11') : '11';

const groupMode = document.getElementById('mb-group-dates')?.checked;

if (groupMode) {
  // ── 1 CLAIM PER PATIENT — all dates become separate lines ─────
  // Each date × each SG CPT = one service line
  // Units come from the SG line (NOT from the date)
  // dxPtr rotates A/B/C/D across lines so all 4 dx are referenced
  const groupedLines = [];
  const dxLetters = ['A','B','C','D','E','F','G','H'];
  let lineIdx = 0;

  for (const d of activeDatesForPat) {
    // Get the actual date string — d is {iso, label, date} from getSGBatchDates
    // or a toggled object from st.dates
    const dateStr = d.date || (d.iso ? (function(){
      var p = d.iso.split('-');
      return parseInt(p[1])+'/'+parseInt(p[2])+'/'+p[0];
    })() : String(d));

    for (const l of (sg.lines || lines_tmpl)) {
      // Units from SG line definition (e.g. 16 units of H2017)
      const lineUnits = parseInt(l.units) || 1;
      // SG stores pricePerUnit directly, or compute from charge/units
      const storedPPU = parseFloat(l.pricePerUnit || l.rate || 0);
      const storedCharge = parseFloat(l.charge || 0);
      // If pricePerUnit is 0 but charge exists, derive it
      const pricePerUnit = storedPPU > 0 ? storedPPU
        : (storedCharge > 0 && lineUnits > 0 ? storedCharge / lineUnits : 0);
      const lineCharge = (pricePerUnit * lineUnits).toFixed(2);

      // dxPtr: ALL diagnoses on every line (e.g. "ABCD" if 4 dx)
      const dxPtr = dxLetters.slice(0, dx.length).join('');

      groupedLines.push({
        id: uid(),
        cpt:          l.cpt || '',
        desc:         l.desc || '',
        units:        String(lineUnits),
        charge:       lineCharge,
        pricePerUnit: pricePerUnit.toFixed(2),
        mod1: l.mod1||'', mod2: l.mod2||'', mod3: l.mod3||'', mod4: l.mod4||'',
        dxPtr,
        dos: dateStr,   // ← each line gets its own date
      });
      lineIdx++;
    }
  }

  // ── Auto-split if >50 lines ─────────────────────────────────
  const _fsDate = activeDatesForPat[0];
  const firstDateStr = _fsDate.date || (_fsDate.iso ? (function(){
    var _p = _fsDate.iso.split('-');
    return parseInt(_p[1])+'/'+parseInt(_p[2])+'/'+_p[0];
  })() : String(_fsDate));
  if (groupedLines.length > 50) {
    var _uniqueDates = [];
    var _seen = {};
    groupedLines.forEach(function(_gl) {
      if (!_seen[_gl.dos]) { _seen[_gl.dos] = true; _uniqueDates.push(_gl.dos); }
    });
    var _cutoff = prompt(
      'This claim has ' + groupedLines.length + ' service lines (max 50).\n\n' +
      'Dates: ' + _uniqueDates.join(', ') + '\n\n' +
      'Enter cutoff date (M/D/YYYY):\n' +
      'Lines on or before this date go in claim 1, the rest in claim 2+.\n' +
      'Click Cancel to abort.',
      _uniqueDates[Math.ceil(_uniqueDates.length/2)-1] || ''
    );
    if (_cutoff === null || !_cutoff.trim()) {
      toast('Cancelled — too many lines per claim (' + groupedLines.length + ')', 'warn');
      continue;
    }
    var _cp = _cutoff.split('/');
    var _cutoffDate = new Date(+_cp[2], +_cp[0]-1, +_cp[1]);
    // Split lines into two groups: before/on cutoff and after cutoff
    var _before = [], _after = [];
    groupedLines.forEach(function(_gl) {
      var _dp = _gl.dos.split('/');
      var _d = new Date(+_dp[2], +_dp[0]-1, +_dp[1]);
      (_d <= _cutoffDate ? _before : _after).push(_gl);
    });
    // Further split any group that exceeds 50 into chunks of 50
    var _allBatches = [];
    [_before, _after].forEach(function(_batch) {
      while (_batch.length > 0) { _allBatches.push(_batch.splice(0, 50)); }
    });
    _allBatches.forEach(function(_batchLines, _bi) {
      var _batchDates = [];
      var _seen2 = {};
      _batchLines.forEach(function(_l) {
        if (!_seen2[_l.dos]) { _seen2[_l.dos] = true; _batchDates.push(_l.dos); }
      });
      pending.push({
        id: uid(), providerId: activeProviderId, patId,
        pcn: buildNextPCN(patId, activeProviderId, pending) + (_bi > 0 ? '-' + (_bi+1) : ''),
        dos: _batchDates[0] || firstDateStr,
        pos, dx, lines: _batchLines,
        renderingId: rendId, facilityId: facId, referringId: refId,
        status: 'pending', multiDate: _batchDates.length > 1,
        createdAt: Date.now(), updatedAt: Date.now(),
        apptId: '', auth: st.auth || asgn.auth || '',
      });
    });
  } else {
    pending.push({
      id: uid(), providerId: activeProviderId, patId,
      pcn: buildNextPCN(patId, activeProviderId, pending),
      dos: firstDateStr,
      pos, dx, lines: groupedLines,
      renderingId: rendId, facilityId: facId, referringId: refId,
      status: 'pending', multiDate: true,
      createdAt: Date.now(), updatedAt: Date.now(),
      apptId: '', auth: st.auth || asgn.auth || '',
    });
  }
} else {
  // ── STANDARD — 1 claim per patient per date ───────────────────
  for (const d of activeDatesForPat) {
    pending.push({
      id: uid(), providerId: activeProviderId, patId,
      pcn: buildNextPCN(patId, activeProviderId, pending),
      dos: d.date || d.label || d,
      pos, dx,
      lines: (sg.lines||lines_tmpl).map(function(l) {
      const lu  = parseInt(l.units)||1;
      const sPPU = parseFloat(l.pricePerUnit||l.rate||0);
      const sCHG = parseFloat(l.charge||0);
      const ppu = sPPU > 0 ? sPPU : (sCHG > 0 && lu > 0 ? sCHG / lu : 0);
      const allDxPtr = ['A','B','C','D','E','F','G','H'].slice(0, dx.length).join('') || 'A';
      return {
        id: uid(), cpt: l.cpt||'', desc: l.desc||'',
        units: String(lu), charge: (ppu*lu).toFixed(2),
        pricePerUnit: ppu.toFixed(2),
        mod1:l.mod1||'',mod2:l.mod2||'',mod3:l.mod3||'',mod4:l.mod4||'',
        dxPtr: allDxPtr,
      };
    }),
      renderingId: rendId, facilityId: facId, referringId: refId,
      status: 'pending',
      createdAt: Date.now(), updatedAt: Date.now(),
      apptId: '', auth: st.auth || asgn.auth || '',
    });
  }
}
}

} else {
// ?? BY PATIENT ???????????????????????????????????????????????
const activeDates = (batchDates||[]).filter(d => d.selected !== false);
if (_batchPatSel.size === 0) { toast('Select at least one patient', 'warn'); return; }
if (!batchSelSvcs.length) { toast('Select at least one service/CPT', 'warn'); return; }
if (!activeDates.length) { toast('Select at least one date', 'warn'); return; }

for (const [patId, patData] of _batchPatSel.entries()) {
const pat = db.patients.find(p => p.id === patId);
if (!pat) continue;

const dx = [patData.dx1, patData.dx2, patData.dx3, patData.dx4].filter(Boolean);
if (!dx.length) {
toast(`${pat.last}, ${pat.first}: add at least one diagnosis`, 'warn');
return;
}

const rendId = patData.rendId || globalRend;
const activeDatesForPat = activeDates;

for (const d of activeDatesForPat) {
pending.push({
id: uid(),
providerId: activeProviderId,
patId,
pcn: buildNextPCN(patId, activeProviderId, pending),
dos: d.date,
pos: globalFac ? (getDB().facilities.find(f=>f.id===globalFac)?.pos||'11') : '11',
dx,
lines: batchSelSvcs.map(svc => ({
id: uid(),
cpt: svc.code,
desc: svc.desc||'',
units: String(parseInt(svc.units)||1),
charge: parseFloat(svc.rate||0).toFixed(2),
mod1: svc.mod1||'',
mod2: svc.mod2||'',
mod3: svc.mod3||'',
mod4: svc.mod4||'',
dxPtr: 'A',
})),
renderingId: rendId,
facilityId: globalFac,
referringId: globalRef,
status: 'pending',
createdAt: Date.now(),
updatedAt: Date.now(),
apptId: '',
auth: '',
});
}
}
}

if (!pending.length) { toast('No claims generated — check dates and patients', 'warn'); return; }

setDB(db2 => { pending.forEach(function(c) { db2.claims.push(c); });

  // Auto-save superbill into patient Documents tab under "Superbills" category
  pending.forEach(function(claim) {
    var pat = (db2.patients||[]).find(function(p){ return p.id===claim.patId; });
    if (!pat) return;
    var prov = (db2.providers||[]).find(function(p){ return p.id===claim.providerId; })||{};
    var rend = (db2.rendering||[]).find(function(r){ return r.id===claim.renderingId; })||{};
    var fac  = (db2.facilities||[]).find(function(f){ return f.id===claim.facilityId; })||{};
    var total = (claim.lines||[]).reduce(function(s,l){ return s+parseFloat(l.charge||0); },0).toFixed(2);
    var now = new Date();
    var dateStr = (now.getMonth()+1)+'/'+now.getDate()+'/'+now.getFullYear();
    if (!pat.documents) pat.documents = [];
    if (pat.documents.find(function(d){ return d.claimId===claim.id && d.category==='Superbills'; })) return;
    pat.documents.unshift({
      id: 'sb_'+claim.id,
      claimId: claim.id,
      claimPCN: claim.pcn||'',
      name: 'Superbill — DOS: '+(claim.dos||dateStr)+' — $'+total,
      category: 'Superbills',
      type: 'pdf',
      date: claim.dos||dateStr,
      uploadedBy: 'System (Batch)',
      providerName: prov.name||'',
      providerNPI: prov.npi||'',
      renderingName: ((rend.first||'')+' '+(rend.last||'')).trim(),
      facilityName: fac.name||'',
      dx: claim.dx||[],
      lines: claim.lines||[],
      ins1: pat.ins1||{},
      totalCharge: total,
      createdAt: Date.now(),
    });
  });
});
closeModal('modal-batch');
renderClaims();
updateBadges();
var _n = pending.length;
toast('<i data-lucide="check" class="lci" style="width:14px;height:14px"></i> '+_n+' claim'+(_n>1?'s':'')+' generated — superbill'+(_n>1?'s':'')+' saved to Documents', 'ok');
}

function setBatchTab(tab, btn) {
const patPanel = document.getElementById('mb-panel-patient');
const sgPanel = document.getElementById('mb-panel-sg');
const tabPat = document.getElementById('mb-tab-patient');
const tabSG = document.getElementById('mb-tab-sg');

const activeStyle = 'border-bottom:3px solid var(--brand);color:var(--brand);';
const inactiveStyle = 'border-bottom:3px solid transparent;color:var(--text2);';

if (tab === 'patient') {
if (patPanel) patPanel.style.display = '';
if (sgPanel) sgPanel.style.display = 'none';
if (tabPat) tabPat.style.cssText = tabPat.style.cssText.replace(/border-bottom[^;]+;?/g,'') + activeStyle;
if (tabSG) tabSG.style.cssText = tabSG.style.cssText.replace(/border-bottom[^;]+;?/g,'') + inactiveStyle;
renderBatchPatients();
renderBatchCatalog();
} else {
if (patPanel) patPanel.style.display = 'none';
if (sgPanel) sgPanel.style.display = '';
if (tabPat) tabPat.style.cssText = tabPat.style.cssText.replace(/border-bottom[^;]+;?/g,'') + inactiveStyle;
if (tabSG) tabSG.style.cssText = tabSG.style.cssText.replace(/border-bottom[^;]+;?/g,'') + activeStyle;
onBatchSGChange();
}
}




async function submitToClaims(claimIds) {
const cfg = getApiConfig();
if (!cfg.acctKey) { toast('Configure your Clearinghouse Account Key first', 'warn'); go('admin-providers'); return; }
const db = getDB();
const claims = claimIds
? db.claims.filter(c => claimIds.includes(c.id))
: db.claims.filter(c => c.providerId === activeProviderId && c.status === 'pending');
if (!claims.length) { toast('No pending claims to submit', 'warn'); return; }

const provider = db.providers.find(p => p.id === activeProviderId);
if (!provider) { toast('No active provider', 'err'); return; }

toast(`Submitting ${claims.length} claim(s)...`);
let ok = 0; let fail = 0;
for (const claim of claims) {
try {
const csv = buildCSVRow ? buildCSVRow(claim, provider, db) : '';
if (!csv) { fail++; continue; }
const fname = `${claim.pcn || claim.id}.837`;
const fd = new FormData();
fd.append('upload', 'claim');
fd.append('AccountKey', cfg.acctKey);
fd.append('File', new Blob([csv], { type:'text/csv' }), fname);
const res = await fetch('https://claimmd-proxy.imbsinc2023.workers.dev', { method:'POST', body:fd });
const txt = await res.text();
if (res.ok) {
setDB(db2 => { const c = db2.claims.find(x => x.id === claim.id); if(c) c.status = 'submitted'; });
addClaimLog(claim.id, 'submitted', 'Claim submitted successfully');
ok++;
} else { fail++; addClaimLog(claim.id, 'error', txt.slice(0,200)); }
} catch(e) { fail++; }
}
toast(`${ok} submitted${fail ? ', '+fail+' failed' : ''}`);
renderClaims(); updateBadges();
}


async function syncStatuses() {
const cfg = getApiConfig();
if (!cfg.acctKey) { toast('Configure Account Key first','warn'); return; }

const db = getDB();

// Build index of OUR submitted claims keyed by PCN — only these get updated
const ourClaims = db.claims.filter(c =>
c.providerId === activeProviderId &&
['submitted','pending'].includes(c.status) &&
c.pcn
);

if (!ourClaims.length) {
logTransmit('No submitted claims to sync','info');
toast('No submitted claims to sync'); return;
}

// Build PCN lookup set for fast matching
const ourPCNs = new Set(ourClaims.map(c => c.pcn.toUpperCase()));
logTransmit(`Syncing ${ourClaims.length} submitted claim(s) from Clearinghouse...`, 'info');

try {
const fd = new FormData();
fd.append('action', 'sync');
fd.append('AccountKey', cfg.acctKey);
fd.append('ResponseID', '0');

const res = await fetch('https://claimmd-proxy.imbsinc2023.workers.dev', {method:'POST',body:fd});
if (!res.ok) throw new Error(`HTTP ${res.status}`);
const xml = await res.text();

const blocks = [...xml.matchAll(/<claim>(.*?)<\/claim>/gs)].map(m => m[1]);
if (!blocks.length) {
logTransmit('No new responses from Clearinghouse', 'info');
toast('No new updates'); return;
}

logTransmit(`?? ${blocks.length} response(s) received — filtering by our claim numbers...`, 'info');

let accepted = 0, rejected = 0, ignored = 0;

setDB(db => {
blocks.forEach(b => {
const gt = t => (b.match(new RegExp(`<${t}>(.*?)<\/${t}>`, 's')) || [])[1] || '';

// PCN is the key — use remote_claimid first, then pcn field
const remotePCN = (gt('remote_claimid') || gt('pcn')).toUpperCase();
const status = gt('status');
const claimMdId = gt('claimmd_id');
const rejectMsg = gt('message') || gt('reject_reason') || '';

// ?? STRICT FILTER: only update claims WE submitted ??????????????????
if (!remotePCN || !ourPCNs.has(remotePCN)) {
ignored++;
return; // skip — not our claim
}

const claim = db.claims.find(c =>
c.pcn.toUpperCase() === remotePCN &&
c.providerId === activeProviderId
);

if (!claim) { ignored++; return; }

if (status === 'A') {
claim.status = 'accepted';
accepted++;
logTransmit(` <i data-lucide="check" class="lci" style="width:13px;height:13px"></i> ${claim.pcn} — Accepted`, 'ok');
} else if (status === 'R') {
claim.status = 'rejected';
claim.rejectReason = rejectMsg;
rejected++;
logTransmit(` <i data-lucide="x" class="lci" style="width:13px;height:13px"></i> ${claim.pcn} — Rejected: ${rejectMsg}`, 'err');
}

if (claimMdId) claim.claimmdId = claimMdId;
claim.updatedAt = Date.now();
});
});

const msg = `Sync complete — ${accepted} accepted, ${rejected} rejected${ignored ? ` (${ignored} from other sources ignored)` : ''}`;
logTransmit(msg, accepted > 0 ? 'ok' : 'warn');
if (rejected) logTransmit(`?? ${rejected} claim(s) rejected — check Claims → Rejected tab`, 'warn');
toast(`Synced: ${accepted} accepted, ${rejected} rejected`);
updateBadges(); renderExportSummary();

} catch(e) {
logTransmit('Sync failed: ' + e.message, 'err');
toast('Sync failed: ' + e.message, 'err');
}
}

// ???????????????????????????????????????????????????????
// SUPER ADMIN MODULE
// ???????????????????????????????????????????????????????

function isAdmin() { const s = getSession(); return !!(s && s.role === 'Super Admin'); }

// Returns true if the current session's user has the given permission string checked
// (or is Super Admin, who always passes every permission check).
function hasPermission(permName) {
  var s = getSession();
  if (!s) return false;
  if (s.role === 'Super Admin' || s.email === SUPER_ADMIN_EMAIL) return true;
  var db = getDB();
  var u = (db.users||[]).find(function(x){ return x.email === s.email; });
  return !!(u && Array.isArray(u.permissions) && u.permissions.indexOf(permName) >= 0);
}

// Returns true if targetUserId belongs to the currently logged-in user
function isSelfUserId(targetUserId) {
  var s = getSession();
  if (!s || !targetUserId) return false;
  var db = getDB();
  var me = (db.users||[]).find(function(x){ return x.email === s.email; });
  return !!(me && me.id === targetUserId);
}

function updateAdminUI() {
// Admin visibility is based SOLELY on internal session role — no Firebase Auth dependency
const session = getSession();
const isSA = !!(session && session.role === 'Super Admin');
// Provider selector — Super Admin only
var _provWrap = document.getElementById('prov-sel-wrap');
if (_provWrap) _provWrap.style.display = isSA ? '' : 'none';

// Top nav admin group (desktop)
const tngAdmin = document.getElementById('tng-admin');
if (tngAdmin) tngAdmin.style.display = isSA ? '' : 'none';

  // Mobile drawer admin group
  const mobAdmin = document.getElementById('mob-grp-admin');
  if (mobAdmin) mobAdmin.style.display = isSA ? '' : 'none';

  // Top nav intake group (desktop) — Super Admin only
  // tng-intake menu removed
  // if (tngIntake) tngIntake.style.display = isSA ? '' : 'none';

  // Mobile drawer intake group — Super Admin only
  const mobIntake = document.getElementById('mob-grp-intake');
  if (mobIntake) mobIntake.style.display = isSA ? '' : 'none';

  const isCM = !!(session && (session.role === 'Case Management' || session.role === 'Super Admin'));
  const tngCM = document.getElementById('tng-cm');
  if (tngCM) tngCM.style.display = isCM ? '' : 'none';
  const mobCM = document.getElementById('mob-grp-cm');
  if (mobCM) mobCM.style.display = isCM ? '' : 'none';

// Legacy sidebar nav (if present)
const nav = document.getElementById('admin-nav');
if (nav) nav.style.display = isSA ? 'block' : 'none';

// Add Provider button in sec-providers (only for SA)
const addBtn = document.getElementById('btn-add-provider');
if (addBtn) addBtn.style.display = isSA ? '' : 'none';

// If non-SA is somehow on an admin page, redirect
if (!isSA) {
const adminSec = document.querySelector('#sec-admin-providers.active, #sec-account.active, #sec-intake-clients.active, #sec-intake-forms.active, #sec-intake-eval.active, #sec-intake-center.active');
if (adminSec) { try { go('dashboard'); } catch(_) {} }
}
}

function openAdminLogin() { /* removed — admin activated automatically on login */ }
function closeAdminLogin() { /* removed — admin activated automatically on login */ }

async function doAdminLogin() {
const email = (document.getElementById('adm-email')?.value || '').trim().toLowerCase();
const pass = document.getElementById('adm-pass')?.value || '';
const alertEl = document.getElementById('admin-login-alert');
if (!email || !pass) { alertEl.innerHTML = '<div class="alert al-error">Email and password required.</div>'; return; }

const btn = document.querySelector('#admin-overlay .btn-lg');
if (btn) { btn.textContent = 'Authenticating...'; btn.disabled = true; }

try {
// Try Firebase Auth first if available
if (_auth && _fbReady) {
try {
await _auth.signInWithEmailAndPassword(email, pass);
_adminUser = _auth.currentUser;
closeAdminLogin();
updateAdminUI();
toast('Access granted — ' + email);
if (btn) { btn.textContent = 'Access Admin Panel'; btn.disabled = false; }
return;
} catch(e) {
// Fall through to local auth if Firebase Auth not configured
if (!['auth/configuration-not-found','auth/operation-not-allowed',
'auth/network-request-failed'].includes(e.code)) {
const msgs = {
'auth/user-not-found': 'Incorrect email or password.',
'auth/wrong-password': 'Incorrect email or password.',
'auth/invalid-credential':'Incorrect email or password.',
'auth/invalid-email': 'Invalid email format.',
'auth/too-many-requests': 'Too many attempts. Try again later.'
};
alertEl.innerHTML = '<div class="alert al-error">' + (msgs[e.code] || e.message) + '</div>';
if (btn) { btn.textContent = 'Access Admin Panel'; btn.disabled = false; }
return;
}
}
}

// Local hash fallback — same credentials as main login
const hash = await sha256(pass);
const allUsers = [DEFAULT_ADMIN, ...(_usersCache || []).filter(u => u.id !== DEFAULT_ADMIN.id)];
const user = allUsers.find(u => ((u.email||'').toLowerCase() === email || (u.name||'').toLowerCase() === email || (u.username||'').toLowerCase() === email) && u.passHash === hash);

if (!user || user.role !== 'Super Admin') {
alertEl.innerHTML = '<div class="alert al-error">Incorrect email or password.</div>';
if (btn) { btn.textContent = 'Access Admin Panel'; btn.disabled = false; }
return;
}

// Simulate admin user for local auth
_adminUser = { email: user.email, uid: user.id };
closeAdminLogin();
updateAdminUI();
toast('Access granted — ' + email);

} catch(e) {
alertEl.innerHTML = '<div class="alert al-error">Error: ' + e.message + '</div>';
} finally {
if (btn) { btn.textContent = 'Access Admin Panel'; btn.disabled = false; }
}
}

function doAdminLogout() {
if (!confirm('Exit Super Admin?')) return;
_adminUser = null;
if (_auth) _auth.signOut().catch(() => {});
updateAdminUI();
toast('Exited Admin panel');
}


