// AUTO ACCOUNT NUMBER (e.g. IM0001 for "IMBS Inc")
// ???????????????????????????????????????????????????????
function deriveAccountPrefix(providerName) {
const words = (providerName||'').toUpperCase().replace(/[^A-Z\s]/g,' ').split(/\s+/).filter(Boolean);
if (words.length >= 2) return words[0][0] + words[1][0];
if (words.length === 1) return words[0].slice(0,2).padEnd(2,'X');
return 'AC';
}

function buildNextAccountNumber(providerId) {
const db = getDB();
const prov = db.providers.find(p => p.id === providerId) || {};
const prefix = deriveAccountPrefix(prov.name || '');
const pattern = new RegExp('^' + prefix + '(\\d{4})$', 'i');
const highest = db.patients
.filter(p => p.providerId === providerId)
.reduce((max, p) => {
const m = (p.acct || '').toUpperCase().match(pattern);
return m ? Math.max(max, parseInt(m[1], 10)) : max;
}, 0);
return prefix + String(highest + 1).padStart(4, '0');
}

