function sha256(str) {
// Simple but sufficient for local auth — uses SubtleCrypto
const buf = new TextEncoder().encode(str);
return crypto.subtle.digest('SHA-256', buf).then(hash =>
Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2,'0')).join('')
);
}

function getUsers() {
// Users are cached in _usersCache after Firestore load
if (_usersCache && _usersCache.length) return JSON.parse(JSON.stringify(_usersCache));
// Fallback: check localStorage (offline)
try {
const r = localStorage.getItem(USERS_KEY);
if (r) { _usersCache = JSON.parse(r); return JSON.parse(JSON.stringify(_usersCache)); }
} catch(e) {}
// First boot — seed default admin
_usersCache = [DEFAULT_ADMIN];
return JSON.parse(JSON.stringify(_usersCache));
}

function saveUsers(users) {
_usersCache = users;
try { localStorage.setItem(USERS_KEY, JSON.stringify(users)); } catch(e) {}
if (_fbReady && _db) {
return _db.collection('meta').doc('users').set({ list: users })
.catch(e => console.warn('Firestore users write failed:', e));
}
}

function getSession() {
  try {
    var ss = sessionStorage.getItem(SESSION_KEY);
    if (ss) return JSON.parse(ss);
    var ls = localStorage.getItem(SESSION_KEY);
    if (ls) { try { sessionStorage.setItem(SESSION_KEY, ls); } catch(e) {} return JSON.parse(ls); }
    return null;
  } catch(e) { return null; }
}

function setSession(user) {
  var data = JSON.stringify({
    id: user.id, email: user.email, role: user.role,
    name: user.name, providerId: user.providerId || null,
    activeBillingProviderId: user.activeBillingProviderId || null
  });
  try { sessionStorage.setItem(SESSION_KEY, data); } catch(e) {}
  try { localStorage.setItem(SESSION_KEY, data); } catch(e) {}
}

function clearSession() {
  sessionStorage.removeItem(SESSION_KEY);
  sessionStorage.removeItem('cdc_verified');
  try { localStorage.removeItem(SESSION_KEY); } catch(e) {}
}

