// ── Reusable In-App PDF/Image Previewer ──
// options: { title, downloadUrl, downloadName }
function _openPDFPreview(dataUri, options) {
  options = options || {};
  // Remove existing overlay if any
  var old = document.querySelector('.pdf-viewer-overlay');
  if (old) { old.remove(); }

  var isImage = dataUri.startsWith('data:image/');
  var overlay = document.createElement('div');
  overlay.className = 'pdf-viewer-overlay';
  overlay.onclick = function(e) { if (e.target === overlay) overlay.remove(); };

  var src = dataUri;
  var viewerContent;

  if (isImage) {
    viewerContent = '<img src="' + src + '" alt="' + (options.title||'Preview') + '">';
  } else {
    // Convert data URI to blob URL for iframe CSP bypass
    try {
      var b64 = dataUri.split(',')[1];
      var bytes = atob(b64);
      var arr = new Uint8Array(bytes.length);
      for (var i = 0; i < bytes.length; i++) arr[i] = bytes.charCodeAt(i);
      var blob = new Blob([arr], { type: 'application/pdf' });
      src = URL.createObjectURL(blob);
      overlay._blobUrl = src;
    } catch (e) {
      // fallback to direct data URI
    }
    viewerContent = '<iframe src="' + src + '" title="' + (options.title||'PDF Viewer') + '"></iframe>';
  }

  var downloadHref = options.downloadUrl || dataUri;
  var downloadName = options.downloadName || 'document.pdf';

  overlay.innerHTML =
    '<div class="pdf-viewer-modal">' +
      '<div class="pdf-viewer-toolbar">' +
        '<span class="pdf-viewer-title">' + (options.title||'Preview') + '</span>' +
        '<button class="pdf-viewer-btn pdf-viewer-btn-primary" onclick="var a=document.createElement(\'a\');a.href=\'' + downloadHref.replace(/'/g,"\\'") + '\';a.download=\'' + downloadName.replace(/'/g,"\\'") + '\';document.body.appendChild(a);a.click();a.remove()"><i data-lucide="download" class="lci" style="width:13px;height:13px"></i> Download</button>' +
        '<button class="pdf-viewer-btn" onclick="window.print()"><i data-lucide="printer" class="lci" style="width:13px;height:13px"></i> Print</button>' +
        '<button class="pdf-viewer-btn-icon" onclick="this.closest(\'.pdf-viewer-overlay\').remove()" title="Close"><i data-lucide="x" class="lci" style="width:18px;height:18px"></i></button>' +
      '</div>' +
      '<div class="pdf-viewer-body">' + viewerContent + '</div>' +
    '</div>';

  document.body.appendChild(overlay);
  setTimeout(_renderLucideIcons, 20);
}

function previewInvoicePDF(invId) {
  // If called from modal, use the current modal state
  var targetId = invId === 'preview' ? _currentInvId : invId;
  if (!targetId) {
    // Auto-save then preview
    saveInvoice();
    targetId = _currentInvId;
  }
  const doc = _buildInvoicePDF(targetId);
  if (!doc) { toast('Save the invoice first, then preview','warn'); return; }
  const inv = getInvDB().invoices.find(x => x.id === targetId);
  try {
    const pdfData = doc.output('datauristring');
    _openPDFPreview(pdfData, {
      title: 'Invoice ' + (inv ? inv.number || '' : ''),
      downloadName: 'invoice_' + (inv ? inv.number||'draft' : 'draft') + '.pdf'
    });
  } catch(e) {
    toast('Preview failed: ' + e.message,'err');
    console.error('Preview error:', e);
  }
}


