function onBatchSGChange() {
updateBatchPOS();
const db = getDB();
const sgId = document.getElementById('mb-sg-sel').value;
const sg = (db.serviceGroups || []).find(g => g.id === sgId);

const cptRow = document.getElementById('mb-sg-cpt-row');
const patWrap = document.getElementById('mb-sg-patients-wrap');

if (!sg) {
if (cptRow) cptRow.style.display = 'none';
if (patWrap) patWrap.style.display = 'none';
updateBatchPreview(); return;
}

// CPT summary
if (cptRow) {
cptRow.style.display = '';
document.getElementById('mb-sg-lines').innerHTML =
sg.lines.map(l => `<span class="badge b-blue mono">${l.cpt}</span>`).join('');
}

// Initialize _sgBatchState for each patient (respect global batchDates selection)
const weekDates = getSGBatchDates();
sg.patients.forEach(asgn => {
const existing = _sgBatchState[asgn.patientId];
if (!existing) {
// New patient — inherit global date selection
_sgBatchState[asgn.patientId] = {
included: true,
dates: weekDates.map(d => ({
...d,
on: batchDates.find(bd => bd.iso === d.iso)?.selected !== false
})),
rendId: sg.renderingProviderId || '',
refId: asgn.referringId || '',
facId: asgn.facilityId || sg.facilityId || ''
};
} else if (existing.dates.length !== weekDates.length) {
// Date range changed — re-sync preserving global selection
existing.dates = weekDates.map(d => ({
...d,
on: batchDates.find(bd => bd.iso === d.iso)?.selected !== false
}));
}
// If date range same but global dates changed, propagate global off-dates
// (already handled by toggleGlobalDate in real-time)
});

if (patWrap) patWrap.style.display = '';
renderSGBatchPatients(sg);
updateBatchPreview();
}

function getSGBatchDates() {
// Read from whichever panel is currently visible
const sgVisible = document.getElementById('mb-panel-sg')?.style.display !== 'none';
const fromId = sgVisible ? 'mb-sg-from' : 'mb-from';
const toId = sgVisible ? 'mb-sg-to' : 'mb-to';
const from = document.getElementById(fromId)?.value;
const to = document.getElementById(toId)?.value;
if (!from || !to) return [];
const days = [];
const cur = new Date(from + 'T12:00:00');
const end = new Date(to + 'T12:00:00');
while (cur <= end && days.length < 60) {
const m = cur.getMonth()+1, d = cur.getDate(), y = cur.getFullYear();
const dow = ['Su','Mo','Tu','We','Th','Fr','Sa'][cur.getDay()];
days.push({ iso: cur.toISOString().split('T')[0], label: `${dow} ${m}/${d}`, date: `${m}/${d}/${y}` });
cur.setDate(cur.getDate()+1);
}
return days;
}


