function buildNextPCN(patientId, providerId, pendingClaims) {
const db = getDB();
const allClaims = [...db.claims, ...(pendingClaims || [])];
const pat = db.patients.find(p => p.id === patientId);
const acct = (pat?.acct || 'PT').toUpperCase();
const existingPCNs = new Set(allClaims.map(c => c.pcn).filter(Boolean));
// Generate: acct# + random 8 digits — retry until unique (virtually never collides)
let pcn, attempts = 0;
do {
// Mix timestamp bits + random to get up to 10M+ combinations
const ts = Date.now() % 100000; // 5 digits from timestamp
const rnd = Math.floor(Math.random() * 99999); // 5 random digits
const combined = String(ts * 100000 + rnd).padStart(10, '0').slice(-8); // 8 digits
pcn = acct + combined;
attempts++;
} while (existingPCNs.has(pcn) && attempts < 100);
return pcn;
}

