function autoFillCPT(idx) {
// Optional auto-fill from catalog — only fills empty fields, never blocks
const db = getDB();
const cpt = tmpLines[idx]?.cpt;
if (!cpt || cpt.length < 5) return;
const svc = db.services.find(s => s.code === cpt);
if (!svc) return; // Not in catalog — that's fine, user typed it manually
const wrap = document.getElementById('mc-lines-wrap');
const lineEl = wrap?.querySelectorAll('.line-item')[idx];
if (!lineEl) return;
// Fill charge if empty
const chargeInput = lineEl.querySelectorAll('input')[1];
if (chargeInput && (!chargeInput.value || chargeInput.value === '0.00' || chargeInput.value === '')) {
chargeInput.value = svc.rate;
tmpLines[idx].charge = svc.rate;
}
// Fill units if still 1
const unitsInput = lineEl.querySelectorAll('input')[2];
if (unitsInput && unitsInput.value === '1' && svc.units && svc.units !== '1') {
unitsInput.value = svc.units;
tmpLines[idx].units = svc.units;
}
}

