let _provLogoB64 = '';

function loadProviderLogo(event) {
  const file = event.target.files[0];
  if (!file) return;
  const MAX_BYTES = 700000;
  const reader = new FileReader();
  reader.onload = function(e) {
    const original = e.target.result;
    const originalSize = Math.round(original.length * 0.75);

    function applyAndShow(b64) {
      _provLogoB64 = b64;
      const finalKB = Math.round(b64.length * 0.75 / 1024);
      const prev = document.getElementById('mprov-logo-preview');
      if (prev) prev.innerHTML = '<img src="'+b64+'" style="width:100%;height:100%;object-fit:contain">'
        + '<div style="font-size:10px;color:var(--text3);text-align:center;margin-top:4px">'
        + finalKB + 'KB' + (originalSize > MAX_BYTES ? ' (comprimido)' : '') + '</div>';
    }

    if (originalSize <= MAX_BYTES) { applyAndShow(original); return; }

    const img = new Image();
    img.onload = function() {
      const canvas = document.createElement('canvas');
      let w = img.width, h = img.height;
      const maxDim = 600;
      if (w > maxDim || h > maxDim) {
        const ratio = Math.min(maxDim/w, maxDim/h);
        w = Math.round(w * ratio); h = Math.round(h * ratio);
      }
      canvas.width = w; canvas.height = h;
      const ctx = canvas.getContext('2d');

      // Check if image has transparency
      ctx.drawImage(img, 0, 0, w, h);
      const hasAlpha = (function() {
        try {
          const px = ctx.getImageData(0, 0, w, h).data;
          for (let i = 3; i < px.length; i += 4) {
            if (px[i] < 255) return true;
          }
          return false;
        } catch(e) { return false; }
      })();

      let result;
      if (hasAlpha) {
        // Preserve transparency — use PNG, scale down more aggressively
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        result = canvas.toDataURL('image/png');
        // If still too big, scale down further
        let scale = 0.8;
        while (result.length * 0.75 > MAX_BYTES && scale >= 0.3) {
          const c2 = document.createElement('canvas');
          c2.width  = Math.round(w * scale);
          c2.height = Math.round(h * scale);
          c2.getContext('2d').drawImage(img, 0, 0, c2.width, c2.height);
          result = c2.toDataURL('image/png');
          scale -= 0.1;
        }
      } else {
        // No transparency — use JPEG with quality reduction
        ctx.drawImage(img, 0, 0, w, h);
        result = original;
        for (let q = 0.85; q >= 0.3; q -= 0.1) {
          result = canvas.toDataURL('image/jpeg', q);
          if (result.length * 0.75 <= MAX_BYTES) break;
        }
      }

      const origKB = Math.round(originalSize / 1024);
      const newKB  = Math.round(result.length * 0.75 / 1024);
      toast('Logo ' + (hasAlpha ? 'PNG (transparente)' : 'JPEG') + ': ' + origKB + 'KB → ' + newKB + 'KB', 'ok');
      applyAndShow(result);
    };
    img.src = original;
  };
  reader.readAsDataURL(file);
}

