function toggleBatchSvc(code, desc, rate) {
const idx = batchSelSvcs.findIndex(s => s.code === code);
if (idx >= 0) {
batchSelSvcs.splice(idx, 1);
} else {
const db = getDB();
const svc = db.services.find(s => s.code === code) || {};
batchSelSvcs.push({ code, desc, rate: rate||svc.rate||0, units: '1' });
}
renderBatchCatalog();
renderBatchCatalogSelected();
updateBatchPreview();
}

