// ?? Anti-Repetition Engine ??????????????????????????????????????????????
function assignNoteTemplate(cpt, providerId, dos, patientId) {
const engine = CPT_ENGINE[cpt] || CPT_ENGINE['DEFAULT'];
const templates = engine.templates;
const notes = getNotes();
const usedIds = notes
.filter(n => n.providerId===providerId && n.dos===dos && n.cpt===cpt)
.map(n => n.templateId);
const available = templates.map(t=>t.id).filter(id => !usedIds.includes(id));
if (!available.length) {
const hash = [...(patientId||'x')].reduce((h,c)=>((h<<5)-h)+c.charCodeAt(0),0);
return templates[Math.abs(hash) % templates.length].id;
}
const hash = [...(patientId||'x')].reduce((h,c)=>((h<<5)-h)+c.charCodeAt(0),0);
return available[Math.abs(hash) % available.length];
}

// ?? Full Note Builder ???????????????????????????????????????????????????
function buildNoteBody(cpt, templateId, pat, rend, prov, claim, db, encType) {
const engine = CPT_ENGINE[cpt] || CPT_ENGINE['DEFAULT'];
const template = engine.templates.find(t=>t.id===templateId) || engine.templates[0];
const dx = (claim.dx||[]).filter(Boolean);
const dxPhrase = dx.length ? dx.join(', ') : 'documented diagnosis';
const cpts = (claim.lines||[]).map(l=>l.cpt).filter(Boolean);
const allSvcs = cpts.map(c=>{const s=db.services?.find(x=>x.code===c); return c+(s?' ('+s.desc+')':'');}).join('; ');
const units = claim.lines?.reduce((s,l)=>s+parseInt(l.units||1),0)||1;
const rendName = rend?.last ? `${rend.last}, ${rend.first||''}, ${rend.cred||''}`.trim().replace(/,\s*$/, '') : (prov?.name||'');
const facName = db.facilities?.find(f=>f.id===claim.facilityId)?.name || 'clinical setting';

const meta = {
patient_name: `${pat.last||'?'}, ${pat.first||''}`,
dob: pat.dob||'',
dos: claim.dos,
provider: rendName,
provider_npi: rend?.npi||prov?.npi||'',
provider_cred: rend?.cred||'',
location: `${facName} (POS ${claim.pos||''})`,
cpt_all: cpts.join(', '),
cpt_label: engine.label,
dx_codes: dxPhrase,
units: String(units),
acct: pat.acct||'',
insurance: `${pat.payerName||''} · ID: ${pat.subNum||''}`,
};

if (encType === 'tcm') {
return {
presenting_needs: template.presenting_needs || template.chief_complaint || '',
care_coordination: template.care_coordination || '',
interventions: template.interventions || '',
service_linkage: template.service_linkage || '',
barriers: template.barriers || '',
resources: template.resources || '',
progress: template.progress || '',
member_response: template.member_response || '',
collateral: template.collateral || '',
follow_up: template.follow_up || template.plan || '',
mn_statement: template.mn_statement || '',
narrative: template.narrative || '',
meta,
};
}

return {
chief_complaint: template.chief_complaint,
history: template.history,
subjective: template.subjective,
objective: template.objective,
interventions: template.interventions,
assessment: template.assessment,
mn_statement: template.mn_statement,
plan: template.plan,
meta,
};
}

// ?? Auto-Generate Note for Claim ????????????????????????????????????????
function autoGenerateNoteForClaim(claim) {
if (!claim?.id) return;
const db = getDB();
const notes = getNotes();
if (notes.find(n=>n.claimId===claim.id)) return; // already exists
const pat = db.patients.find(p=>p.id===claim.patId)||{};
const prov = db.providers.find(p=>p.id===claim.providerId)||{};
const rend = db.rendering.find(r=>r.id===claim.renderingId)||{};
const cpt = claim.lines?.[0]?.cpt||'DEFAULT';
const tmplId= assignNoteTemplate(cpt, claim.providerId, claim.dos, claim.patId);
const body = buildNoteBody(cpt, tmplId, pat, rend, prov, claim, db);
const note = {
id: uid(),
claimId: claim.id,
patId: claim.patId,
providerId: claim.providerId,
renderingId: claim.renderingId||'',
dos: claim.dos,
cpt,
cptAll: (claim.lines||[]).map(l=>l.cpt).filter(Boolean),
dx: (claim.dx||[]).filter(Boolean),
pos: claim.pos||'11',
templateId: tmplId,
status: 'draft',
body,
createdAt: Date.now(),
updatedAt: Date.now(),
finalizedAt: null,
editedAt: null,
version: 1,
};
setNotes(arr=>arr.push(note));
}

