// saveAINote (old API version removed)



function _aiToggleOpt(qKey, val) {
if (!window._aiSelections) window._aiSelections={};
if (!window._aiSelections[qKey]) window._aiSelections[qKey]=[];
const q = AI_NOTE_QUESTIONS[qKey];
if (q.type==='single') {
window._aiSelections[qKey] = window._aiSelections[qKey][0]===val?[]:[val];
} else {
const idx=window._aiSelections[qKey].indexOf(val);
if(idx>=0) window._aiSelections[qKey].splice(idx,1);
else window._aiSelections[qKey].push(val);
}
// Update button styles
const modal=document.getElementById('ai-note-modal');
if(!modal) return;
modal.querySelectorAll(`[data-q="${qKey}"][data-v]`).forEach(btn=>{
const v=btn.getAttribute('data-v');
const sel=window._aiSelections[qKey]?.includes(v);
btn.style.background=sel?'var(--brand)':'var(--bg3)';
btn.style.color=sel?'#fff':'var(--text2)';
btn.style.borderColor=sel?'var(--brand)':'var(--border2)';
btn.style.fontWeight=sel?'700':'400';
});
}

function _toggleNoteEdit() {
const out=document.getElementById('ai-note-output');
if(!out) return;
if(out.tagName==='TEXTAREA'){
const d=document.createElement('div');
d.id=out.id; d.style.cssText=out.style.cssText;
d.style.whiteSpace='pre-wrap'; d.style.overflowY='auto';
d.textContent=out.value; out.parentNode.replaceChild(d,out);
} else {
const ta=document.createElement('textarea');
ta.id=out.id; ta.style.cssText=out.style.cssText;
ta.style.resize='vertical'; ta.style.fontFamily='var(--font)';
ta.style.fontSize='13px'; ta.style.lineHeight='1.7';
ta.value=out.textContent||''; out.parentNode.replaceChild(ta,out); ta.focus();
}
}

