// ?? Core NLP Engine ???????????????????????????????????????????
const CdcNLPEngine = {

// Normalize spoken text to clinical language
normalize(text) {
let t = text.toLowerCase();
Object.entries(CDC_NLP.normalize).forEach(([spoken, clinical]) => {
t = t.replace(new RegExp('\\b'+spoken+'\\b','gi'), clinical);
});
return t;
},

// Detect which SOAP section a sentence belongs to
detectSection(sentence) {
const lower = sentence.toLowerCase().trim();
for (const [sec, triggers] of Object.entries(CDC_NLP.sections)) {
for (const trigger of triggers) {
if (lower.startsWith(trigger) || lower.includes(trigger+':') ||
lower.includes(trigger+',') || (trigger.endsWith(':') && lower.includes(trigger))) {
return sec;
}
}
}
return null;
},

// Parse raw transcript ? structured sections
parseTranscript(rawText) {
const normalized = this.normalize(rawText);
const sentences = normalized.split(/[.!?\n;]+/).map(s=>s.trim()).filter(s=>s.length>4);
const sections = { S:[], O:[], A:[], P:[], MN:[] };
let current = 'S';

sentences.forEach(sent => {
const detected = this.detectSection(sent);
if (detected) current = detected;
// Clean up section keywords from the sentence
let clean = sent;
CDC_NLP.sections[current]?.forEach(t => {
clean = clean.replace(new RegExp('^'+t+'[:\\-,\\s]*','i'),'').trim();
});
if (clean.length > 3) sections[current].push(
clean.charAt(0).toUpperCase() + clean.slice(1)
);
});

return sections;
},

// Auto-distribute if no section markers detected
autoDistribute(sections, rawText) {
const total = Object.values(sections).flat().length;
const inS = sections.S.length;
if (total > 4 && inS === total) {
// No section keywords — split by quarters
const all = sections.S.splice(0);
const q = Math.ceil(all.length / 4);
sections.S = all.slice(0, q);
sections.O = all.slice(q, q*2);
sections.A = all.slice(q*2, q*3);
sections.P = all.slice(q*3);
}
return sections;
},

// Build full formatted SOAP note
buildNote(sections, pat, cpts, dxCodes) {
const fmt = arr => arr.length ? arr.join('. ') + '.' : '';
const tpl = cpts.length ? (CDC_NLP.cptTemplates[cpts[0]] || CDC_NLP.cptTemplates['DEFAULT']) : CDC_NLP.cptTemplates['DEFAULT'];
const age = pat.dob ? _calcAge(pat.dob) : '?';
const sex = pat.sex==='M'?'male':pat.sex==='F'?'female':'patient';
const dxFull = dxCodes.map(c => CDC_NLP.icd10[c] ? `${c} (${CDC_NLP.icd10[c]})` : c).join(', ') || 'per chart';

// Medical necessity auto-generate if missing
const mnText = sections.MN.length
? fmt(sections.MN)
: `Services rendered are medically necessary for the management of ${dxFull}. `+
`Clinical findings support continued ${tpl.level.toLowerCase()} level evaluation and management. `+
`Without treatment, patient s condition would be expected to deteriorate.`;

return `SUBJECTIVE
${fmt(sections.S) !== '' ? fmt(sections.S) : `${age}-year-old ${sex} presents for evaluation.`}

OBJECTIVE
${tpl.exam}
${fmt(sections.O) !== '' ? fmt(sections.O) : 'Vital signs and physical findings documented in chart.'}
CPT: ${cpts.join(', ') || 'N/A'} — ${tpl.level}

ASSESSMENT
${fmt(sections.A) !== '' ? fmt(sections.A) : `Patient evaluated for ${dxFull}.`}
Diagnoses: ${dxFull}

PLAN
${fmt(sections.P) !== '' ? fmt(sections.P) : 'Treatment plan discussed with patient. Follow-up as scheduled.'}

MEDICAL NECESSITY
${mnText}`;
}
};

