function getInsurances() { return (getDB().insurances||[]).filter(i=>i.providerId===activeProviderId); }

function renderInsurances() {
const el = document.getElementById('insurances-tbl');
if (!el) return;
const q = (document.getElementById('ins-q')?.value||'').toLowerCase();
const typeF = document.getElementById('ins-type-filter')?.value||'';
const statF = document.getElementById('ins-status-filter')?.value||'';

let list = getInsurances();
if (q) list = list.filter(i=>(i.name+' '+(i.payerId||'')).toLowerCase().includes(q));
if (typeF) list = list.filter(i=>(i.type||'electronic')===typeF);
if (statF) list = list.filter(i=>(i.status||'Active')===statF);

if (!list.length) {
el.innerHTML = `<div class="empty">
<div class="empty-ico"><i data-lucide="shield" class="lci" style="width:40px;height:40px;color:var(--text3)"></i></div>
<h3>No payers configured</h3>
<div class="btn-group" style="justify-content:center;margin-top:10px">
<button class="btn btn-primary btn-sm" onclick="openInsuranceModal('')"><i data-lucide="plus" class="lci"></i> Add Payer</button>
<button class="btn btn-sm" onclick="searchClearinghousePayers()"><i data-lucide="search" class="lci"></i> Clearinghouse Directory</button>
</div>
</div>`;
_renderLucideIcons(); return;
}

el.innerHTML = `<div class="tbl-wrap"><table>
<thead><tr>
<th>Payer Name</th><th>Payer ID</th><th>Type</th><th>State</th>
<th>Phone</th><th>Address</th><th>Status</th><th>Actions</th>
</tr></thead><tbody>` +
list.map(i => {
const isElec = (i.type||'electronic')==='electronic';
const active = (i.status||'Active')==='Active';
return `<tr style="opacity:${active?'1':'0.55'}">
<td style="font-weight:600">${i.name}</td>
<td class="mono" style="font-size:12px;color:var(--brand)">${i.payerId||''}</td>
<td><span class="badge ${isElec?'b-green':'b-gray'}" style="font-size:10px">
<i data-lucide="${isElec?'zap':'file-text'}" class="lci" style="width:10px;height:10px"></i>
${isElec?'Electronic':'Manual'}
</span></td>
<td style="font-size:12px">${i.state||''}</td>
<td style="font-size:12px">${i.phone||''}</td>
<td style="font-size:11px;color:var(--text2)">${[i.addr,i.city,i.state].filter(Boolean).join(', ')||''}</td>
<td><span class="badge ${active?'b-green':'b-gray'}">${active?'Active':'Inactive'}</span></td>
<td><div class="btn-group" style="gap:4px">
<button class="btn-icon sm" onclick="openInsuranceModal('${i.id}')" title="Edit">
<i data-lucide="pencil" class="lci" style="width:13px;height:13px"></i>
</button>
<button class="btn-icon sm" onclick="toggleInsuranceStatus('${i.id}')"
title="${active?'Deactivate':'Activate'}" style="color:${active?'var(--amber)':'var(--brand)'}">
<i data-lucide="${active?'pause-circle':'play-circle'}" class="lci" style="width:13px;height:13px"></i>
</button>
<button class="btn-icon sm danger" onclick="deleteInsurance('${i.id}')" title="Delete">
<i data-lucide="trash-2" class="lci" style="width:13px;height:13px"></i>
</button>
</div></td>
</tr>`;
}).join('') + '</tbody></table></div>';
_renderLucideIcons();
}

function openInsuranceModal(iid) {
const db = getDB();
const isNew= !iid;
const ins = isNew ? {} : (db.insurances||[]).find(x=>x.id===iid)||{};
document.getElementById('mins-title').textContent = isNew ? 'Add Payer' : 'Edit Payer';
sv('mins-id', iid||'');
sv('mins-name', ins.name||'');
sv('mins-payerid',ins.payerId||'');
sv('mins-phone', ins.phone||'');
sv('mins-addr', ins.addr||'');
sv('mins-city', ins.city||'');
sv('mins-state', ins.state||'');
sv('mins-zip', ins.zip||'');
sv('mins-notes', ins.notes||'');
const typeEl = document.getElementById('mins-type');
if (typeEl) typeEl.value = ins.type||'electronic';
const statEl = document.getElementById('mins-status');
if (statEl) statEl.value = ins.status||'Active';
const badge = document.getElementById('mins-claimmd-badge');
if (badge) badge.style.display = ins.claimmdVerified ? '' : 'none';
// Hide suggestions
['mins-name-suggestions','mins-payerid-suggestions'].forEach(id=>{
const el = document.getElementById(id); if(el) el.style.display='none';
});
openModal('modal-insurance');
setTimeout(_renderLucideIcons,20);
}

function saveInsurance() {
const name = v('mins-name');
const payerId = v('mins-payerid');
if (!name) { toast('Payer name is required','warn'); return; }
if (!payerId) { toast('Payer ID is required','warn'); return; }
const iid = (document.getElementById('mins-id')?.value||'').trim();
const isNew = !iid;
const db = getDB();
const exist = isNew ? null : (db.insurances||[]).find(x=>x.id===iid);

const ins = {
id: isNew ? uid() : iid,
providerId: activeProviderId,
name: name.trim(),
payerId: payerId.trim(),
type: document.getElementById('mins-type')?.value||'electronic',
status: document.getElementById('mins-status')?.value||'Active',
phone: v('mins-phone'),
addr: v('mins-addr'),
city: v('mins-city'),
state: v('mins-state').toUpperCase().slice(0,2),
zip: v('mins-zip'),
notes: v('mins-notes'),
claimmdVerified:exist?.claimmdVerified||false,
createdAt: exist?.createdAt||Date.now(),
updatedAt: Date.now(),
};

setDB(db2 => {
if (!db2.insurances) db2.insurances = [];
const idx = db2.insurances.findIndex(x=>x.id===ins.id);
if (idx>=0) db2.insurances[idx]=ins; else db2.insurances.push(ins);
});
closeModal('modal-insurance');
renderInsurances();
toast(isNew?'Payer added ?':'Payer updated ?');
}

function toggleInsuranceStatus(iid) {
const db = getDB();
const ins = (db.insurances||[]).find(x=>x.id===iid);
if (!ins) return;
const newStatus = ins.status==='Inactive'?'Active':'Inactive';
setDB(db2=>{ const i=(db2.insurances||[]).find(x=>x.id===iid); if(i){i.status=newStatus;i.updatedAt=Date.now();} });
renderInsurances();
toast(`Payer ${newStatus}`);
}

function deleteInsurance(iid) {
const db = getDB();
const ins = (db.insurances||[]).find(x=>x.id===iid);
if (!ins) return;
// Check if used in any claim via patient payerid
const usedInClaim = (db.claims||[]).some(c => {
  const pat = db.patients.find(p=>p.id===c.patId);
  return pat && (pat.payerid===ins.payerId || pat.payerid===ins.id ||
    (pat.insurances||[]).some(pi=>pi.payerId===ins.payerId||pi.payerId===iid));
});
if (usedInClaim) {
  toast('Cannot delete — payer is used in claims. Mark Inactive instead.','err');
  return;
}
if (!confirm(`Delete payer "${ins.name}"?`)) return;
setDB(db2=>{ db2.insurances=(db2.insurances||[]).filter(x=>x.id!==iid); });
renderInsurances();
toast('Payer deleted');
}

