function recreateClaimFromUnmatched(unmatchedId) {
const db = getDB();
const u = (db.eobUnmatched||[]).find(x=>x.id===unmatchedId);
if (!u) { toast('Unmatched record not found','err'); return; }

const patId = document.getElementById('rc-pat')?.value;
const dos = document.getElementById('rc-dos')?.value;
const cpt = (document.getElementById('rc-cpt')?.value||'').trim();
const charge = parseFloat(document.getElementById('rc-charge')?.value||0);
const units = parseInt(document.getElementById('rc-units')?.value||1);
const dxRaw = (document.getElementById('rc-dx')?.value||'').trim();
const rendId = document.getElementById('rc-rend')?.value||'';
const facId = document.getElementById('rc-fac')?.value||'';
const pcnIn = (document.getElementById('rc-pcn')?.value||'').trim();
const paid = parseFloat(document.getElementById('rc-paid')?.value||0);

if (!patId) { toast('Select a patient','warn'); return; }
if (!dos) { toast('Date of Service is required','warn'); return; }

const dx = dxRaw ? dxRaw.split(',').map(d=>d.trim()).filter(Boolean) : [];
const pcn = pcnIn || buildNextPCN(patId, activeProviderId, db.claims);

// Build the claim
const claim = {
id: uid(),
providerId: activeProviderId,
patId,
pcn,
dos,
pos: facId ? (db.facilities.find(f=>f.id===facId)?.pos||'11') : '11',
dx,
lines: cpt ? [{
id: uid(), cpt, desc:'', units:String(units),
charge: charge.toFixed(2), mod1:'', mod2:'', mod3:'', mod4:'', dxPtr:'A',
}] : [],
renderingId: rendId,
facilityId: facId,
referringId: '',
status: 'accepted', // already paid
primaryPaid: paid,
primaryPosted: true,
recreatedFromPayment: true,
recreatedFromUnmatched: unmatchedId,
auth: '',
createdAt: Date.now(),
updatedAt: Date.now(),
};

// Post the payment to this new claim
setDB(db2 => {
db2.claims.push(claim);

// Post EOB entry
if (!db2.claimEOB) db2.claimEOB = {};
db2.claimEOB[claim.id] = [{
batchId: u.batchId||'unmatched',
payerName: u.payerName||'Unknown',
checkNum: u.checkNum||'',
checkDate: u.checkDate||dos,
paid,
adj: parseFloat(u.adj||0),
adjCode: u.adjCode||'',
patResp: parseFloat(u.patResp||0),
postedAt: Date.now(),
}];

// Remove from unmatched
db2.eobUnmatched = (db2.eobUnmatched||[]).filter(x=>x.id!==unmatchedId);
});

document.getElementById('modal-recreate-claim')?.remove();

// Update unmatched count badge
const eu = document.getElementById('eob-cnt-unmatched');
if (eu) eu.textContent = Math.max(0,parseInt(eu.textContent||0)-1);

renderEOBPage();
renderClaims();
updateBadges();
toast(`Claim ${pcn} created and payment posted ?`);
}
function renderEOBUnmatched() {
const db = getDB();
const unmatched = (db.eobUnmatched||[]).filter(u=>u.providerId===activeProviderId);
if (!unmatched.length) return `<div class="empty"><h3 style="color:var(--brand)">No unmatched payments</h3></div>`;

return `<div style="margin-bottom:10px;padding:10px 14px;background:var(--amber-bg);border:1px solid var(--amber-bdr);border-radius:var(--r);font-size:12px;color:var(--amber)">
<strong>${unmatched.length} unmatched payment(s)</strong> — Match to an existing claim, recreate the claim from payment data, or dismiss.
</div>
<div class="tbl-wrap"><table>
<thead><tr>
<th>PCN / Ref</th><th>Patient</th><th>DOS</th><th>CPT</th>
<th>Payer</th><th>Amount</th><th>Source</th><th style="width:220px">Actions</th>
</tr></thead><tbody>` +
unmatched.map(u => `<tr>
<td class="mono" style="font-size:11px">${u.pcn||u.ref||''}</td>
<td style="font-size:12px">${u.patName||u.patLast?(u.patLast||'')+(u.patFirst?', '+u.patFirst:''):''}</td>
<td style="font-size:12px">${u.dos||''}</td>
<td class="mono" style="font-size:11px">${u.cpt||''}</td>
<td style="font-size:11px">${u.payerName||''}</td>
<td class="mono" style="font-weight:700;color:var(--brand)">$${fmtMoney(u.amt)}</td>
<td><span class="badge b-amber" style="font-size:10px">${u.source||'ERA'}</span></td>
<td>
<div class="btn-group" style="gap:4px;flex-wrap:wrap">
<button class="btn btn-xs" onclick="matchUnmatched('${u.id}')" title="Match to existing claim">
<i data-lucide="link" class="lci" style="width:11px;height:11px"></i> Match
</button>
<button class="btn btn-xs btn-primary" onclick="openRecreateClaimModal('${u.id}')" title="Create new claim from this payment">
<i data-lucide="plus-circle" class="lci" style="width:11px;height:11px"></i> Recreate Claim
</button>
<button class="btn btn-xs" onclick="dismissUnmatched('${u.id}')" title="Dismiss"
style="background:var(--bg3);color:var(--text2);border:1px solid var(--border)">
<i data-lucide="x" class="lci" style="width:11px;height:11px"></i>
</button>
</div>
</td>
</tr>`).join('') + '</tbody></table></div>';
}


function renderEOBSecondary() {
const db = getDB();
const ready = db.claims.filter(c=>c.providerId===activeProviderId && c.readyForSecondary);
if (!ready.length) return `<div class="empty"><h3>No claims ready for secondary billing</h3><p style="font-size:13px;color:var(--text3)">When primary pays and a secondary insurance exists, claims appear here</p></div>`;
return `<div style="margin-bottom:10px;display:flex;gap:8px">
<button class="btn btn-primary btn-sm" onclick="exportSecondaryCSV()"><i data-lucide="send" class="lci"></i> Export Secondary Claims</button>
</div>
<div class="tbl-wrap"><table>
<thead><tr><th>PCN</th><th>Patient</th><th>DOS</th><th>Primary Paid</th><th>Balance</th><th>Secondary Ins</th><th>Actions</th></tr></thead><tbody>` +
ready.map(c => {
const pat = db.patients.find(p=>p.id===c.patId)||{};
const eob = (db.claimEOB||{})[c.id]||[];
const paid = eob.reduce((s,e)=>s+parseFloat(e.paid||0),0);
const bal = parseFloat(c.totalCharge||claimTotal(c)) - paid;
const ins2 = (pat.insurances||[]).find(i=>!i.inactive&&(i.insType||i.type||'').toLowerCase().includes('secondary'));
return `<tr>
<td class="mono" style="font-size:11px">${c.pcn||''}</td>
<td style="font-weight:600">${pat.last||'?'}, ${pat.first||''}</td>
<td style="font-size:12px">${c.dos||''}</td>
<td class="mono" style="color:var(--brand)">$${fmtMoney(paid)}</td>
<td class="mono" style="font-weight:700">$${fmtMoney(bal)}</td>
<td style="font-size:11px">${ins2?ins2.name||ins2.insuranceName||'Secondary':''}</td>
<td><button class="btn btn-xs btn-primary" onclick="submitSecondary('${c.id}')"><i data-lucide="send" class="lci"></i> Bill Secondary</button></td>
</tr>`;
}).join('') + '</tbody></table></div>';
}

// ?? Manual EOB posting modal ?????????????????????????????????????
function openEOBPostingModal(prefillBatch) {
_eobBatchLines = prefillBatch ? JSON.parse(JSON.stringify(prefillBatch.lines||[])) : [];
const today = new Date().toISOString().split('T')[0];
if (document.getElementById('eob-check-date'))
document.getElementById('eob-check-date').value = today;
if (prefillBatch) {
sv('eob-payer-name', prefillBatch.payerName||'');
sv('eob-payer-id', prefillBatch.payerId||'');
sv('eob-check-num', prefillBatch.checkNum||'');
sv('eob-check-date', prefillBatch.checkDate||today);
sv('eob-check-amt', prefillBatch.checkAmt||'');
sv('eob-notes', prefillBatch.notes||'');
}
renderEOBClaimLines();
updateEOBRunning();
openModal('modal-eob-post');
setTimeout(_renderLucideIcons, 20);
}

function renderEOBClaimLines() {
const el = document.getElementById('eob-claim-lines');
if (!el) return;
if (!_eobBatchLines.length) {
el.innerHTML = '<div style="text-align:center;padding:20px;font-size:12px;color:var(--text3)">Click "Find & Add Claim" to search and add claims to this payment</div>';
return;
}
const db = getDB();
el.innerHTML = `<table style="width:100%;font-size:12px;border-collapse:collapse">
<thead><tr style="background:var(--bg2)">
<th style="padding:6px 8px;text-align:left">PCN</th>
<th style="padding:6px 8px;text-align:left">Patient</th>
<th style="padding:6px 8px;text-align:left">DOS</th>
<th style="padding:6px 8px;text-align:left">CPT(s)</th>
<th style="padding:6px 8px;text-align:right">Billed</th>
<th style="padding:6px 8px;text-align:right">Adj</th>
<th style="padding:6px 8px;text-align:right">Adj Code</th>
<th style="padding:6px 8px;text-align:right">Paid</th>
<th style="padding:6px 8px;text-align:right">Pat Resp</th>
<th style="padding:6px 8px;text-align:center">Action</th>
</tr></thead><tbody>` +
_eobBatchLines.map((l,i) => {
const c = db.claims.find(x=>x.id===l.claimId)||{};
const pat = db.patients.find(x=>x.id===c.patId)||{};
const cpts= (c.lines||[]).map(x=>x.cpt).filter(Boolean).join(', ');
const billed = claimTotal(c);
return `<tr style="border-bottom:1px solid var(--border)">
<td style="padding:5px 8px" class="mono">${c.pcn||l.pcn||''}</td>
<td style="padding:5px 8px;font-weight:600">${pat.last||'?'}, ${pat.first||''}</td>
<td style="padding:5px 8px;font-size:11px">${c.dos||''}</td>
<td style="padding:5px 8px;font-size:11px" class="mono">${cpts}</td>
<td style="padding:5px 8px;text-align:right">$${fmtMoney(billed)}</td>
<td style="padding:5px 8px;text-align:right">
<input type="number" step="0.01" value="${l.amtAdj||''}" placeholder="0.00"
style="width:70px;padding:3px 5px;border:1px solid var(--border2);border-radius:4px;font-size:11px;text-align:right;background:var(--bg2);color:var(--text)"
oninput="_eobBatchLines[${i}].amtAdj=this.value;updateEOBRunning()">
</td>
<td style="padding:5px 8px;text-align:right">
<input value="${l.adjCode||''}" placeholder="CO-45"
style="width:60px;padding:3px 5px;border:1px solid var(--border2);border-radius:4px;font-size:11px;text-align:right;background:var(--bg2);color:var(--text)"
oninput="_eobBatchLines[${i}].adjCode=this.value">
</td>
<td style="padding:5px 8px;text-align:right">
<input type="number" step="0.01" value="${l.amtPaid||''}" placeholder="0.00"
style="width:70px;padding:3px 5px;border:1px solid var(--border2);border-radius:4px;font-size:11px;text-align:right;font-weight:700;background:var(--brand-bg);color:var(--brand);border-color:var(--brand-bdr)"
oninput="_eobBatchLines[${i}].amtPaid=this.value;updateEOBRunning()">
</td>
<td style="padding:5px 8px;text-align:right">
<input type="number" step="0.01" value="${l.patResp||''}" placeholder="0.00"
style="width:70px;padding:3px 5px;border:1px solid var(--border2);border-radius:4px;font-size:11px;text-align:right;background:var(--bg2);color:var(--text)"
oninput="_eobBatchLines[${i}].patResp=this.value">
</td>
<td style="padding:5px 8px;text-align:center">
<button class="btn-icon sm danger" onclick="_eobBatchLines.splice(${i},1);renderEOBClaimLines();updateEOBRunning()" title="Remove">
<i data-lucide="x" class="lci" style="width:12px;height:12px"></i>
</button>
</td>
</tr>`;
}).join('') + '</tbody></table>';
setTimeout(_renderLucideIcons, 10);
}

function updateEOBRunning() {
const total = parseFloat(document.getElementById('eob-check-amt')?.value||0);
const posted = _eobBatchLines.reduce((s,l)=>s+parseFloat(l.amtPaid||0),0);
const balance = total - posted;
const el_rt = document.getElementById('eob-running-total');
const el_cd = document.getElementById('eob-check-display');
const el_bal = document.getElementById('eob-balance-badge');
if (el_rt) el_rt.textContent = '$'+fmtMoney(posted);
if (el_cd) el_cd.textContent = '$'+fmtMoney(total);
if (el_bal) {
el_bal.textContent = 'Balance: $'+Math.abs(balance).toFixed(2);
el_bal.className = 'badge '+(Math.abs(balance)<0.01?'b-green':balance<0?'b-red':'b-amber');
}
}

// ?? Claim search for EOB matching ????????????????????????????????
function openEOBClaimSearch() {
document.getElementById('eob-search-val').value = '';
document.getElementById('eob-search-dos').value = '';
document.getElementById('eob-search-results').innerHTML =
'<div style="padding:16px;text-align:center;font-size:12px;color:var(--text3)">Enter search criteria above</div>';
openModal('modal-eob-search');
}

function searchEOBClaims() {
const field = document.getElementById('eob-search-field')?.value || 'pcn';
const val = (document.getElementById('eob-search-val')?.value||'').trim().toLowerCase();
const dos = (document.getElementById('eob-search-dos')?.value||'').trim();
const status = document.getElementById('eob-search-status')?.value||'';
const el = document.getElementById('eob-search-results');
if (!el) return;
if (!val && !dos) {
el.innerHTML = '<div style="padding:16px;text-align:center;font-size:12px;color:var(--text3)">Enter search criteria above</div>';
return;
}
const db = getDB();
let claims = db.claims.filter(c => c.providerId === activeProviderId);
if (status) claims = claims.filter(c => (c.status||'draft') === status);

claims = claims.filter(c => {
const pat = db.patients.find(p=>p.id===c.patId)||{};
const allIns = pat.insurances||[];
const ins1 = allIns.find(i=>(i.insType||i.type||'').toLowerCase().includes('primary'));
let haystack = '';
if (field==='pcn') haystack = (c.pcn||'').toLowerCase();
if (field==='last') haystack = (pat.last||'').toLowerCase();
if (field==='first') haystack = (pat.first||'').toLowerCase();
if (field==='member') haystack = (ins1?.memberId||ins1?.policy||pat.subNum||'').toLowerCase();
if (field==='acct') haystack = (pat.acct||'').toLowerCase();
if (field==='dob') haystack = (pat.dob||'').toLowerCase();
const matchField = !val || haystack.includes(val);
const matchDOS = !dos || (c.dos||'').includes(dos) || dos.includes(c.dos||'');
return matchField && matchDOS;
});

if (!claims.length) {
el.innerHTML = '<div style="padding:16px;text-align:center;font-size:12px;color:var(--text3)">No matching claims found</div>';
return;
}

el.innerHTML = claims.slice(0,20).map(c => {
const pat = db.patients.find(p=>p.id===c.patId)||{};
const cpts = (c.lines||[]).map(l=>l.cpt).filter(Boolean).join(', ');
const billed = claimTotal(c);
const already = _eobBatchLines.some(l=>l.claimId===c.id);
const addBtn = already
? '<button class="btn btn-xs" disabled>Added</button>'
: '<button class="btn btn-xs btn-primary" onclick="addClaimToEOBBatch(this.dataset.id)" data-id="'+c.id+'">+ Add</button>';
return '<div style="padding:10px 12px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px'+(already?';opacity:.5':'')+'">'+
'<div style="flex:1">'+
'<div style="font-weight:700;font-size:12px">'+pat.last+', '+pat.first+'</div>'+
'<div style="font-size:11px;color:var(--text3)">'+
'PCN: <span class="mono">'+c.pcn+'</span> &nbsp;·&nbsp; '+
'DOS: '+c.dos+' &nbsp;·&nbsp; '+
'CPT: <span class="mono">'+cpts+'</span> &nbsp;·&nbsp; '+
'Billed: <strong>$'+fmtMoney(billed)+'</strong>'+
'</div>'+
'</div>'+
addBtn+
'</div>';
}).join('');
}


function addClaimToEOBBatch(claimId) {
if (_eobBatchLines.some(l=>l.claimId===claimId)) { toast('Already added','warn'); return; }
const db = getDB();
const claim = db.claims.find(c=>c.id===claimId);
if (!claim) return;
_eobBatchLines.push({
claimId, pcn: claim.pcn||'', dos: claim.dos||'',
amtPaid:'', amtAdj:'', adjCode:'CO-45', patResp:'',
});
closeModal('modal-eob-search');
renderEOBClaimLines();
updateEOBRunning();
toast('Claim added to batch');
}

// ?? Save EOB batch ????????????????????????????????????????????????
function saveEOBBatch() {
const payerName = v('eob-payer-name');
const checkAmt = v('eob-check-amt');
const checkDate = document.getElementById('eob-check-date')?.value;
if (!payerName) { toast('Payer name is required','warn'); return; }
if (!checkDate) { toast('Check date is required','warn'); return; }
if (!_eobBatchLines.length) { toast('Add at least one claim','warn'); return; }

const batch = {
id: uid(),
providerId: activeProviderId,
payerName, payerId: v('eob-payer-id'),
checkNum: v('eob-check-num'),
checkDate, checkAmt: parseFloat(checkAmt||0),
notes: v('eob-notes'),
source: 'manual',
lines: JSON.parse(JSON.stringify(_eobBatchLines)),
createdAt: Date.now(), updatedAt: Date.now(),
};

// Post payments to claims
_postEOBToClaims(batch);

setEOBBatches(arr => arr.push(batch));
closeModal('modal-eob-post');
_eobBatchLines = [];
renderEOBPage();
toast(`Payment batch posted — ${batch.lines.length} claim(s)`);
}


