// ── ERA Worker URL ─────────────────────────────────────────────────────────
var ERA_WORKER_URL = 'https://claimmd-era.imbsinc2023.workers.dev';

async function _eraWorkerPost(endpoint, params) {
  var body = Object.entries(params).map(function(kv){
    return encodeURIComponent(kv[0])+'='+encodeURIComponent(kv[1]);
  }).join('&');
  var res = await fetch(ERA_WORKER_URL + endpoint, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: body
  });
  if (!res.ok) throw new Error('ERA worker HTTP '+res.status);
  return await res.json();
}

function _parseERADataClaims(eraData, eraInfo, db) {
  var posted = [], unmatched = [];
  var claims = eraData.claim || [];
  if (!Array.isArray(claims)) claims = claims ? [claims] : [];

  claims.forEach(function(c) {
    var pcn        = (c.pcn || c.remote_claimid || '').trim().toUpperCase();
    var totalPaid  = parseFloat(c.total_paid || 0);
    var statusCode = c.status_code || '';
    var payerICN   = c.payer_icn  || '';
    var dos        = c.from_dos   || c.thru_dos || '';

    var charges = c.charge || [];
    if (!Array.isArray(charges)) charges = charges ? [charges] : [];
    var chargeLines = charges.map(function(ch) {
      var adjs = ch.adjustment || [];
      if (!Array.isArray(adjs)) adjs = adjs ? [adjs] : [];
      return {
        cpt: ch.proc_code || '',
        charge: parseFloat(ch.charge || 0),
        allowed: parseFloat(ch.allowed || 0),
        paid: parseFloat(ch.paid || 0),
        adjustments: adjs.map(function(a){ return {group:a.group,code:a.code,amount:parseFloat(a.amount||0)}; })
      };
    });

    var patResp = chargeLines.reduce(function(s,cl){
      return s+cl.adjustments.filter(function(a){return a.group==='PR';}).reduce(function(ss,a){return ss+a.amount;},0);
    },0);
    var adjAmt = chargeLines.reduce(function(s,cl){
      return s+cl.adjustments.filter(function(a){return a.group==='CO';}).reduce(function(ss,a){return ss+a.amount;},0);
    },0);

    var claim = db.claims.find(function(lc) {
      if (lc.providerId !== activeProviderId) return false;
      var lp = (lc.pcn||'').trim().toUpperCase();
      return lp===pcn||lp==='PCN-'+pcn||lp==='CLM-'+pcn||pcn==='PCN-'+lp||pcn==='CLM-'+lp;
    });

    if (claim) {
      // Layer 1: skip if same ERA already posted
      if ((claim.payments||[]).some(function(p){return p.eraId===eraInfo.eraid;})) return;
      // Layer 2: skip if same check number already posted to this claim
      var chkNum = (eraInfo.check_number||'').trim().toUpperCase();
      if (chkNum) {
        var _db2 = getDB();
        var _existingEOBs = (_db2.claimEOB && _db2.claimEOB[claim.id]) || [];
        if (_existingEOBs.some(function(e){ return (e.checkNum||'').trim().toUpperCase()===chkNum; })) {
          console.warn('[ERA] Skipping duplicate — check#', eraInfo.check_number, 'already posted to claim PCN:', claim.pcn);
          return;
        }
      }
      posted.push({
        claimId:claim.id, pcn:pcn, dos:dos||claim.dos||'',
        amtPaid:totalPaid.toFixed(2), amtAdj:adjAmt.toFixed(2),
        adjCode:'ERA', patResp:patResp.toFixed(2),
        eraId:eraInfo.eraid, eraCheck:eraInfo.check_number||'',
        payerName:eraInfo.payer_name||'', payerId:eraInfo.payerid||'',
        paidDate:eraInfo.paid_date||'', payerICN:payerICN,
        statusCode:statusCode, chargeLines:chargeLines
      });
    } else if (totalPaid > 0 || statusCode === '1') {
      unmatched.push({
        id:uid(), providerId:activeProviderId, pcn:pcn, dos:dos,
        amt:totalPaid, payerName:eraInfo.payer_name||'',
        payerId:eraInfo.payerid||'',
        eraId:eraInfo.eraid, source:'ERA', createdAt:Date.now(),
        matched:false,
        claimData:{
          pcn:pcn, dos:dos,
          payerName:eraInfo.payer_name||'', payerId:eraInfo.payerid||'',
          memberId:c.member_id||'', statusCode:statusCode,
          totalPaid:totalPaid, chargeLines:chargeLines,
          eraId:eraInfo.eraid, checkNumber:eraInfo.check_number||'',
          paidDate:eraInfo.paid_date||''
        }
      });
    }
  });
  return {posted:posted, unmatched:unmatched};
}


// ── ERA Import Progress Modal ─────────────────────────────────────────────
function _eraProgressOpen(total) {
  var existing = document.getElementById('era-progress-modal');
  if (existing) existing.remove();

  var panel = document.createElement('div');
  panel.id = 'era-progress-modal';
  panel.style.cssText = 'position:fixed;inset:0;z-index:9500;display:flex;align-items:center;justify-content:center;background:rgba(20,20,19,.55);padding:16px';
  panel.innerHTML =
    '<div style="background:#faf9f5;border-radius:14px;width:100%;max-width:440px;padding:28px 28px 24px;box-shadow:0 24px 60px rgba(0,0,0,.25);position:relative">'
    + '<div style="display:flex;align-items:center;gap:12px;margin-bottom:20px">'
      + '<div style="width:40px;height:40px;background:#f0eee6;border-radius:10px;display:flex;align-items:center;justify-content:center;flex-shrink:0">'
        + '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#c96442" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M8 17l4 4 4-4"/><path d="M12 12v9"/><path d="M20.88 18.09A5 5 0 0 0 18 9h-1.26A8 8 0 1 0 3 16.29"/></svg>'
      + '</div>'
      + '<div>'
        + '<div style="font-size:15px;font-weight:700;color:#141413">Importing Payments</div>'
        + '<div id="era-prog-subtitle" style="font-size:12px;color:#87867f;margin-top:2px">Connecting to ClaimMD…</div>'
      + '</div>'
    + '</div>'
    // Progress bar track
    + '<div style="background:#f0eee6;border-radius:100px;height:8px;margin-bottom:10px;overflow:hidden">'
      + '<div id="era-prog-bar" style="height:100%;background:#c96442;border-radius:100px;width:0%;transition:width .4s ease"></div>'
    + '</div>'
    // Stats row
    + '<div style="display:flex;justify-content:space-between;margin-bottom:18px">'
      + '<span id="era-prog-label" style="font-size:11px;color:#87867f">0 of ' + total + ' ERAs</span>'
      + '<span id="era-prog-pct" style="font-size:11px;font-weight:700;color:#c96442">0%</span>'
    + '</div>'
    // Log
    + '<div id="era-prog-log" style="background:#f5f4ed;border-radius:8px;padding:10px 12px;max-height:140px;overflow-y:auto;font-size:11px;font-family:monospace;color:#5e5d59;line-height:1.6"></div>'
  + '</div>';

  document.body.appendChild(panel);
}

function _eraProgressUpdate(current, total, msg) {
  var bar  = document.getElementById('era-prog-bar');
  var lbl  = document.getElementById('era-prog-label');
  var pct  = document.getElementById('era-prog-pct');
  var sub  = document.getElementById('era-prog-subtitle');
  var log  = document.getElementById('era-prog-log');
  if (!bar) return;
  var p = total > 0 ? Math.round((current/total)*100) : 0;
  bar.style.width = p + '%';
  if (lbl) lbl.textContent = current + ' of ' + total + ' ERAs';
  if (pct) pct.textContent = p + '%';
  if (sub) sub.textContent = msg || 'Processing…';
  if (log && msg) {
    var line = document.createElement('div');
    line.textContent = '▸ ' + msg;
    log.appendChild(line);
    log.scrollTop = log.scrollHeight;
  }
}

function _eraProgressClose(summary) {
  var panel = document.getElementById('era-progress-modal');
  if (!panel) return;
  // Show completion state briefly before closing
  var bar = document.getElementById('era-prog-bar');
  var sub = document.getElementById('era-prog-subtitle');
  var pct = document.getElementById('era-prog-pct');
  if (bar) bar.style.width = '100%';
  if (pct) pct.textContent = '100%';
  if (sub) sub.textContent = summary || 'Import complete';
  var log = document.getElementById('era-prog-log');
  if (log && summary) {
    var line = document.createElement('div');
    line.style.cssText = 'margin-top:6px;padding-top:6px;border-top:1px solid #e8e6dc;font-weight:700;color:#141413';
    line.textContent = '✓ ' + summary;
    log.appendChild(line);
    log.scrollTop = log.scrollHeight;
  }
  setTimeout(function() {
    if (panel.parentNode) panel.remove();
  }, 2200);
}

async function fetchERAFromClearinghouse() {
  var cfg = getApiConfig();
  if (!cfg.acctKey) { toast('Configure your Clearinghouse Account Key first','warn'); go('export'); return; }

  var alertEl = document.getElementById('eob-alert');
  var setAlert = function(html){ if(alertEl) alertEl.innerHTML=html; };

  setAlert('<div class="alert al-info" style="display:flex;align-items:center;gap:8px">'+
    '<i data-lucide="loader" class="lci" style="width:14px;height:14px;animation:spin 1s linear infinite"></i>'+
    'Fetching new ERA from ClaimMD&hellip;</div>');
  setTimeout(_renderLucideIcons, 50);

  var db = getDB();
  var cursorKey = 'lastERAID_' + activeProviderId;
  var lastERAID = (db.settings && db.settings[cursorKey]) ? db.settings[cursorKey] : '0';

  var eraList;
  try {
    eraList = await _eraWorkerPost('/eralist', { AccountKey:cfg.acctKey, ERAID:lastERAID, NewOnly:'0' });
  } catch(e) {
    setAlert('<div class="alert al-error">ERA list fetch failed: '+e.message+'</div>');
    toast('ERA fetch failed: '+e.message,'err'); return;
  }

  var root = eraList.result || eraList;
  var eras = root.era || [];
  if (!Array.isArray(eras)) eras = eras ? [eras] : [];

  if (!eras.length) {
    setAlert('<div class="alert al-info">No new ERA payments since last sync. (Last ERA ID: '+lastERAID+')</div>');
    toast('No new ERAs'); return;
  }

  setAlert('<div class="alert al-info">Found '+eras.length+' ERA(s) — importing&hellip;</div>');
  var eraDataCount = 0;

  // Open progress modal
  _eraProgressOpen(eras.length);
  _eraProgressUpdate(0, eras.length, 'Found ' + eras.length + ' ERA(s) — fetching details…');

  var allPosted=[], allUnmatched=[], allBatches=[], newLastERAID=lastERAID;

  // Safety check: a single ClaimMD Account Key can cover multiple billing
  // providers/NPIs. Each ERA entry carries the billing provider's own
  // prov_npi/prov_taxid — we must verify it matches the ACTIVE provider
  // before any matching/posting happens, or a check belonging to a
  // DIFFERENT provider could get posted onto this provider's claims.
  var activeProv = db.providers.find(function(p){ return p.id === activeProviderId; }) || {};
  var activeNpi   = String(activeProv.npi||'').replace(/\D/g,'');
  var activeTaxid = String(activeProv.taxid||'').replace(/\D/g,'');
  var skippedOtherProvider = 0;

  for (var i=0; i<eras.length; i++) {
    var eraInfo = eras[i];
    var eraid   = String(eraInfo.eraid || eraInfo.ERAID || '');
    if (!eraid) continue;

    var eraNpi   = String(eraInfo.prov_npi||'').replace(/\D/g,'');
    var eraTaxid = String(eraInfo.prov_taxid||'').replace(/\D/g,'');
    var belongsToActiveProvider = true;
    if (eraNpi && activeNpi) belongsToActiveProvider = (eraNpi === activeNpi);
    else if (eraTaxid && activeTaxid) belongsToActiveProvider = (eraTaxid === activeTaxid);
    // If neither NPI nor TaxID is present on the ERA record, we can't verify —
    // fall back to the existing PCN + providerId matching done downstream.

    // Always advance this provider's cursor so a foreign-provider ERA isn't
    // re-fetched/re-skipped forever — the OTHER provider has its own
    // separate cursor (lastERAID_<providerId>) and will pick it up correctly
    // the next time IT runs an import.
    if (parseInt(eraid) > parseInt(newLastERAID)) newLastERAID = eraid;

    if (!belongsToActiveProvider) {
      skippedOtherProvider++;
      _eraProgressUpdate(i+1, eras.length, '⚠ Skipped ERA #' + eraid + ' — belongs to a different billing provider (NPI ' + (eraNpi||'?') + ')');
      console.warn('[ERA] Skipping ERA', eraid, '— prov_npi', eraNpi, 'does not match active provider NPI', activeNpi);
      continue;
    }

    _eraProgressUpdate(i, eras.length, 'Fetching ERA #' + eraid + ' (' + (i+1) + ' of ' + eras.length + ')…');

    var eraData;
    try {
      eraData = await _eraWorkerPost('/eradata', { AccountKey:cfg.acctKey, eraid:eraid });
    } catch(e) {
      _eraProgressUpdate(i+1, eras.length, '⚠ ERA #' + eraid + ' failed: ' + e.message);
      console.warn('[ERA] eradata failed for eraid',eraid,e.message); continue;
    }

    var dataRoot = eraData.result || eraData;
    eraDataCount++;
    var parsed   = _parseERADataClaims(dataRoot, eraInfo, db);
    _eraProgressUpdate(i+1, eras.length, 'ERA #' + eraid + ': ' + parsed.posted.length + ' matched, ' + parsed.unmatched.length + ' unmatched');
    allPosted    = allPosted.concat(parsed.posted);
    allUnmatched = allUnmatched.concat(parsed.unmatched);

    if (parsed.posted.length > 0) {
      allBatches.push({
        id:uid(), providerId:activeProviderId, eraId:eraid,
        payerName:eraInfo.payer_name||'ClaimMD ERA', payerId:eraInfo.payerid||'',
        checkNum:eraInfo.check_number||('ERA-'+eraid), checkType:eraInfo.check_type||'eft',
        checkDate:eraInfo.paid_date||new Date().toLocaleDateString('en-US'),
        checkAmt:parseFloat(eraInfo.paid_amount||0),
        notes:'Auto-imported ERA #'+eraid, source:'era',
        lines:parsed.posted, createdAt:Date.now(), updatedAt:Date.now()
      });
    }
  }

  if (allBatches.length) {
    allBatches.forEach(function(batch){ _postEOBToClaims(batch); });
    setEOBBatches(function(arr){ allBatches.forEach(function(b){ arr.push(b); }); });
  }

  if (allUnmatched.length) {
    setDB(function(db2){
      if(!db2.eobUnmatched) db2.eobUnmatched=[];
      db2.eobUnmatched.push.apply(db2.eobUnmatched, allUnmatched);
    });
  }

  if (newLastERAID !== lastERAID) {
    setDB(function(db2){ if(!db2.settings) db2.settings={}; db2.settings[cursorKey]=newLastERAID; });
  }

  // ── Queue for preview — don't auto-post ──────────────────────────────
  var today2 = new Date(); today2.setHours(0,0,0,0);
  var previewItems = allBatches.map(function(batch) {
    var paidDate = batch.checkDate ? new Date(batch.checkDate) : null;
    return {
      id:         uid(),
      eraId:      batch.eraId,
      providerId: activeProviderId,
      payerName:  batch.payerName,
      checkNum:   batch.checkNum,
      checkDate:  batch.checkDate,
      checkAmt:   batch.checkAmt,
      claimCount: (batch.lines||[]).length,
      isFuture:   paidDate && paidDate > today2,
      fetchedAt:  Date.now(),
      status:     'preview'
    };
  });

  if (previewItems.length || allUnmatched.length) {
    setDB(function(db2){
      if(!db2.eraPreviewQueue) db2.eraPreviewQueue=[];
      // Add matched ERA preview items
      previewItems.forEach(function(item){
        var exists = db2.eraPreviewQueue.some(function(e){ return e.eraId===item.eraId; });
        if (!exists) db2.eraPreviewQueue.push(item);
      });
      // Add unmatched as NO_MATCH items in the same queue
      allUnmatched.forEach(function(um){
        var exists = db2.eraPreviewQueue.some(function(e){ return e.id===um.id; });
        if (!exists) {
          db2.eraPreviewQueue.push({
            id:um.id,
            eraId:um.eraId,
            providerId:um.providerId,
            payerName:um.payerName,
            checkNum:um.claimData ? (um.claimData.checkNumber||um.eraId) : um.eraId,
            checkDate:um.claimData ? (um.claimData.paidDate||'') : '',
            checkAmt:um.amt,
            claimCount:0,
            fetchedAt:Date.now(),
            status:'preview',
            matched:false,
            claimData:um.claimData||null,
            pcn:um.pcn, dos:um.dos
          });
        }
      });
    });
  }

  window._eraPreviewBatches = allBatches;

  setAlert('');
  if (!previewItems.length && !allUnmatched.length) {
    setAlert('<div class="alert al-info">No new ERA payments found since last sync. (Last ERA: '+lastERAID+')</div>');
    toast('No new ERAs'); renderEOBPage(); return;
  }

  var totalItems = previewItems.length;
  var futureCount = previewItems.filter(function(x){return x.isFuture;}).length;
  var unmatchedCount = allUnmatched.length;
  // Close progress modal
  var _summary2 = 'Imported '+eraDataCount+' ERA'+(eraDataCount!==1?'s':'')+' — '+totalItems+' matched'+(unmatchedCount?' · '+unmatchedCount+' unmatched':'')+(futureCount?' · '+futureCount+' future':'')+(skippedOtherProvider?' · '+skippedOtherProvider+' skipped (other provider)':'');
  _eraProgressClose(_summary2);
  toast('ERA imported: '+eraDataCount+' ERA'+(eraDataCount!==1?'s':'')+' — '+totalItems+' matched'+(unmatchedCount?' · '+unmatchedCount+' no match':'')+(futureCount?' · '+futureCount+' future':'')+(skippedOtherProvider?' · '+skippedOtherProvider+' from other providers (skipped)':'')+' ');
  renderEOBPage(); updateBadges();
  // Auto-navigate to Pending ERA tab
  setEOBTab('era-pending', document.getElementById('eob-tab-era-pending'));
}

// ── ERA Preview Modal ──────────────────────────────────────────────────────
function _openERAPreviewModal(previewItems, allBatches, allUnmatched) {
  var today = new Date(); today.setHours(0,0,0,0);
  var readyNow    = previewItems.filter(function(x){ return !x.isFuture; });
  var futureOnes  = previewItems.filter(function(x){ return x.isFuture; });
  var totalReady  = readyNow.reduce(function(s,x){ return s+parseFloat(x.checkAmt||0); }, 0);
  var totalFuture = futureOnes.reduce(function(s,x){ return s+parseFloat(x.checkAmt||0); }, 0);

  var rows = previewItems.map(function(item) {
    var badge = item.isFuture
      ? '<span style="font-size:9px;font-weight:700;padding:2px 6px;border-radius:10px;background:#ede9fe;color:#7c3aed">FUTURE</span>'
      : '<span style="font-size:9px;font-weight:700;padding:2px 6px;border-radius:10px;background:#f0faf5;color:#2d7a4f">READY</span>';
    return '<tr style="border-bottom:1px solid var(--border)">'
      +'<td style="padding:7px 8px;width:32px"><input type="checkbox" class="era-preview-cb"'+(!item.isFuture?' checked':'')+' data-eraid="'+item.eraId+'" style="width:14px;height:14px;accent-color:var(--brand)"></td>'
      +'<td style="padding:7px 8px;font-size:12px;font-weight:600">'+item.payerName+'</td>'
      +'<td style="padding:7px 8px;font-size:11px;font-family:monospace">'+item.checkNum+'</td>'
      +'<td style="padding:7px 8px;font-size:11px">'+item.checkDate+'</td>'
      +'<td style="padding:7px 8px;font-size:12px;font-family:monospace;font-weight:700;color:#2d7a4f">$'+fmtMoney(item.checkAmt)+'</td>'
      +'<td style="padding:7px 8px;text-align:center;font-size:11px">'+item.claimCount+'</td>'
      +'<td style="padding:7px 8px">'+badge+'</td>'
      +'</tr>';
  }).join('');

  var unmNote = allUnmatched.length
    ? '<div style="padding:8px 12px;background:#fff8e1;border:1px solid #f59e0b;border-radius:6px;font-size:11px;color:#b45309;margin-bottom:10px"><strong>'+allUnmatched.length+'</strong> claim(s) could not be matched — they appear in Unmatched tab.</div>'
    : '';

  var html =
    '<div class="overlay" id="modal-era-preview" style="z-index:9999">'
    +'<div class="modal" style="max-width:780px;width:98%;max-height:90vh;display:flex;flex-direction:column">'
      +'<div class="modal-hdr" style="flex-shrink:0">'
        +'<div><div class="modal-t"><i data-lucide="download-cloud" class="lci" style="width:16px;height:16px"></i> ERA Payment Preview</div>'
        +'<div class="modal-sub">Check the payments you want to post now. Future payments are unchecked — they save to Pending ERA.</div></div>'
        +'<button class="btn btn-ghost btn-sm" onclick="closeModal(&quot;modal-era-preview&quot;)">×</button>'
      +'</div>'
      +'<div class="modal-body" style="flex:1;overflow-y:auto;padding:16px">'
        +unmNote
        +'<div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:14px">'
          +'<div style="background:#f0faf5;border:1px solid #bbf7d0;border-radius:8px;padding:10px 12px"><div style="font-size:10px;font-weight:700;text-transform:uppercase;color:#2d7a4f;margin-bottom:3px">Ready to Post</div><div style="font-size:20px;font-weight:800;color:#2d7a4f">'+readyNow.length+'</div><div style="font-size:11px;font-family:monospace;color:#2d7a4f">$'+fmtMoney(totalReady)+'</div></div>'
          +'<div style="background:#ede9fe;border:1px solid #ddd6fe;border-radius:8px;padding:10px 12px"><div style="font-size:10px;font-weight:700;text-transform:uppercase;color:#7c3aed;margin-bottom:3px">Future</div><div style="font-size:20px;font-weight:800;color:#7c3aed">'+futureOnes.length+'</div><div style="font-size:11px;font-family:monospace;color:#7c3aed">$'+fmtMoney(totalFuture)+'</div></div>'
          +'<div style="background:var(--bg3);border:1px solid var(--border);border-radius:8px;padding:10px 12px"><div style="font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text3);margin-bottom:3px">Total ERA</div><div style="font-size:20px;font-weight:800;color:var(--text)">'+previewItems.length+'</div></div>'
          +'<div style="background:var(--bg3);border:1px solid var(--border);border-radius:8px;padding:10px 12px"><div style="font-size:10px;font-weight:700;text-transform:uppercase;color:var(--text3);margin-bottom:3px">Unmatched</div><div style="font-size:20px;font-weight:800;color:'+(allUnmatched.length?'#b35c00':'var(--text3)')+'">'+allUnmatched.length+'</div></div>'
        +'</div>'
        +'<div class="tbl-wrap" style="margin:0"><table style="width:100%"><thead><tr style="background:var(--bg3)">'
          +'<th style="padding:6px 8px;width:32px"><input type="checkbox" id="era-check-all" style="width:14px;height:14px;accent-color:var(--brand)" onchange="document.querySelectorAll(&quot;.era-preview-cb&quot;).forEach(function(c){c.checked=document.getElementById(&quot;era-check-all&quot;).checked})" title="Select all"></th>'
          +'<th style="padding:6px 8px;font-size:11px">Payer</th><th style="padding:6px 8px;font-size:11px">Check #</th>'
          +'<th style="padding:6px 8px;font-size:11px">Check Date</th><th style="padding:6px 8px;font-size:11px">Amount</th>'
          +'<th style="padding:6px 8px;font-size:11px;text-align:center">Claims</th><th style="padding:6px 8px;font-size:11px">Status</th>'
        +'</tr></thead><tbody>'+rows+'</tbody></table></div>'
      +'</div>'
      +'<div class="modal-ftr" style="flex-shrink:0;justify-content:space-between">'
        +'<button class="btn" onclick="closeModal(&quot;modal-era-preview&quot;);setEOBTab(&quot;era-pending&quot;,null)">Save All to Pending</button>'
        +'<button class="btn btn-primary" onclick="_eraPreviewPostSelected()"><i data-lucide="check-circle" class="lci" style="width:13px;height:13px"></i> Post Selected</button>'
      +'</div>'
    +'</div></div>';

  var existing = document.getElementById('modal-era-preview');
  if (existing) existing.remove();
  document.body.insertAdjacentHTML('beforeend', html);
  setTimeout(_renderLucideIcons, 50);
}

function _eraPreviewPostSelected() {
  var checked = Array.from(document.querySelectorAll('.era-preview-cb:checked'))
    .map(function(cb){ return cb.getAttribute('data-eraid'); });
  if (!checked.length) { toast('Select at least one ERA to post','warn'); return; }
  var batches = (window._eraPreviewBatches||[]).filter(function(b){ return checked.indexOf(b.eraId)>=0; });
  var posted = 0;
  batches.forEach(function(batch){
    _postEOBToClaims(batch);
    setEOBBatches(function(arr){ arr.push(batch); });
    posted += (batch.lines||[]).length;
  });
  setDB(function(db2){ (db2.eraPreviewQueue||[]).forEach(function(x){ if(checked.indexOf(x.eraId)>=0) x.status='posted'; }); });
  closeModal('modal-era-preview');
  toast(posted+' payment(s) posted from '+batches.length+' ERA(s)');
  renderEOBPage(); updateBadges();
}



// ── Specialty System ──────────────────────────────────────────────────────────

var _SPEC_MENU_DEFS = [
    {label:'Home', id:'tnav-dashboard', group:'tnav-dashboard'},
    {label:'Schedule', id:'tnav-appointments', group:'tnav-appointments'},
    {label:'Patients', id:'tnav-patients', group:'tnav-patients'},
    {label:'Billing (Claims/ERA)', id:'tng-billing', group:'tng-billing'},
    {label:'EHR / Encounters', id:'tng-ehr', group:'tng-ehr'},
    {label:'Case Management', id:'tng-cm', group:'tng-cm'},
    {label:'Settings', id:'tng-config', group:'tng-config'},
    {label:'Admin', id:'tng-admin', group:'tng-admin'},
    {label:'Invoicing', id:'tnd-invoices', group:'tnd-invoices'},
    {label:'Reports', id:'tnd-reports', group:'tnd-reports'},
    {label:'Service Groups', id:'tnd-servicegroups', group:'tnd-servicegroups'},
    {label:'Export / Submit', id:'tnd-export', group:'tnd-export'}
  ];

// Render editable specialty rows inside Billing Provider modal
function _mprovRenderSpecialties(defs) {
  var container = document.getElementById('mprov-spec-list');
  if (!container) return;
  container.innerHTML = '';
  (defs || []).forEach(function(sd) {
    container.appendChild(_mprovBuildSpecRow(sd));
  });
  setTimeout(_renderLucideIcons, 20);
}

function _mprovBuildSpecRow(sd) {
  sd = sd || {};
  var specId = sd.id || uid();
  var div = document.createElement('div');
  div.className = 'mprov-spec-row';
  div.dataset.specId = specId;
  div.style.cssText = 'border:1.5px solid var(--border2);border-radius:10px;padding:14px;background:var(--bg);display:flex;flex-direction:column;gap:10px';

  // Header row: name + taxonomy + delete
  var headerMenuHtml = _SPEC_MENU_DEFS.map(function(m) {
    var chk = (sd.menus || []).indexOf(m.id) >= 0 ? 'checked' : '';
    return '<label class="mprov-chip">' +
      '<input type="checkbox" class="mprov-spec-menu-cb" value="' + m.id + '" ' + chk + '>' +
      '<span>' + m.label + '</span></label>';
  }).join('');

  div.innerHTML =
    '<div style="display:grid;grid-template-columns:1fr 1fr auto;gap:8px;align-items:end">' +
      '<div class="field" style="margin:0">' +
        '<label style="font-size:11px;font-weight:600;color:var(--text3)">Specialty Name *</label>' +
        '<input class="mprov-spec-name" value="' + (sd.name||'') + '" placeholder="e.g. Applied Behavior Analysis"' +
        ' style="width:100%;box-sizing:border-box;padding:8px 10px;border:1.5px solid var(--border2);border-radius:var(--r);background:var(--bg2);color:var(--text);font-size:13px">' +
      '</div>' +
      '<div class="field" style="margin:0">' +
        '<label style="font-size:11px;font-weight:600;color:var(--text3)">Taxonomy Code</label>' +
        '<input class="mprov-spec-taxonomy" value="' + (sd.taxonomy||'') + '" placeholder="e.g. 103G00000X" maxlength="10"' +
        ' style="width:100%;box-sizing:border-box;padding:8px 10px;border:1.5px solid var(--border2);border-radius:var(--r);background:var(--bg2);color:var(--text);font-size:13px;font-family:monospace">' +
      '</div>' +
      '<button type="button" onclick="this.closest(\'.mprov-spec-row\').remove()" ' +
        'style="padding:8px 10px;border:1.5px solid var(--red,#dc2626);border-radius:var(--r);background:transparent;color:var(--red,#dc2626);cursor:pointer;font-size:12px;height:38px">' +
        '<i data-lucide="trash-2" class="lci" style="width:13px;height:13px"></i>' +
      '</button>' +
    '</div>' +
    '<div>' +
      '<div style="font-size:10px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px">Visible Menus</div>' +
      '<div style="display:flex;flex-wrap:wrap;gap:8px">' + headerMenuHtml + '</div>' +
    '</div>';

  setTimeout(_renderLucideIcons, 20);
  return div;
}

function _mprovAddSpecialty() {
  var container = document.getElementById('mprov-spec-list');
  if (!container) return;
  container.appendChild(_mprovBuildSpecRow({}));
  setTimeout(_renderLucideIcons, 20);
}

// ── Active Specialty Runtime ──────────────────────────────────────────────────

// Get active specialty for current user (from db.users)
// Specialty assignments can be either a plain string (legacy) or an object
// {name, role, active} (current). These helpers read either shape safely
// so existing data never breaks.
function _specEntryName(s) { return (s && typeof s === 'object') ? s.name : s; }
function _specEntryRole(s) { return (s && typeof s === 'object') ? (s.role||'') : ''; }
function _specEntryActive(s) { return (s && typeof s === 'object') ? (s.active !== false) : true; }
function _specNamesOf(list) { return (Array.isArray(list)?list:[]).filter(_specEntryActive).map(_specEntryName); }

function getActiveSpecialty() {
  var sess = getSession();
  if (!sess) return null;
  if (sess.role === 'Super Admin') return null; // SA sees all
  var db = getDB();
  var user = (db.users||[]).find(function(u){ return u.email === sess.email; });
  return user ? (user.activeSpecialty || null) : null;
}

// Switch specialty — persists to db.users
function switchSpecialty(specName) {
  var sess = getSession();
  if (!sess) return;
  setDB(function(db2){
    var user = (db2.users||[]).find(function(u){ return u.email === sess.email; });
    if (user) user.activeSpecialty = specName;
  });
  // Update session
  sess.activeSpecialty = specName;
  setSession(sess);
  toast('Switched to ' + specName, 'ok');
  applyActiveSpecialty();
  toggleUserMenu();
}

// Apply visibility rules based on active specialty
function applyActiveSpecialty() {
  var sess = getSession();
  if (!sess || sess.role === 'Super Admin') {
    // SA — show all
    _SPEC_MENU_DEFS.forEach(function(m){
      var el = document.getElementById(m.group);
      if (el) el.style.display = '';
    });
    return;
  }

  var db = getDB();
  var prov = (db.providers||[]).find(function(p){ return p.id === activeProviderId; }) || {};
  var specDefs = prov.specialtyDefs || [];
  if (!specDefs.length) return; // No specialties configured on provider — show all

  var dbUser = (db.users||[]).find(function(u){ return u.email === sess.email; });
  var userSpecNames = _specNamesOf(dbUser && dbUser.specialties);
  if (!userSpecNames.length) return; // User has no specialty assigned — show all (nothing to restrict to)

  // Specialties this specific user is actually allowed to use
  var eligibleDefs = specDefs.filter(function(sd){ return userSpecNames.indexOf(sd.name) >= 0; });
  if (!eligibleDefs.length) return; // Assigned specialty no longer exists on provider — show all rather than lock the user out

  var activeSpecName = getActiveSpecialty();
  var activeDef = eligibleDefs.find(function(sd){ return sd.name === activeSpecName; });
  if (!activeDef) {
    // Default to the first specialty THIS USER is assigned to (not the provider's first specialty)
    activeDef = eligibleDefs[0];
    switchSpecialty(activeDef.name);
    return;
  }

  var allowedMenus = activeDef.menus || [];
  _SPEC_MENU_DEFS.forEach(function(m){
    var el = document.getElementById(m.group);
    if (!el) return;
    el.style.display = allowedMenus.indexOf(m.id) >= 0 ? '' : 'none';
  });

  // Update active taxonomy on provider (runtime only — not saved to db)
  window._activeSpecialty = activeDef;
}

// Render the Change Specialty button in user menu
function _renderSpecialtySwitch() {
  var container = document.getElementById('tn-user-specialty-section');
  if (!container) return;

  var sess = getSession();
  if (!sess || sess.role === 'Super Admin') { container.style.display = 'none'; return; }

  var db = getDB();
  var prov = (db.providers||[]).find(function(p){ return p.id === activeProviderId; }) || {};
  var specDefs = prov.specialtyDefs || [];
  var dbUser = (db.users||[]).find(function(u){ return u.email === sess.email; });
  var rawSpecs = (dbUser && dbUser.specialties) || sess.specialties || [];
  var userSpecNames = _specNamesOf(rawSpecs);

  // Only show if user has 2+ specialties assigned
  var eligibleSpecs = specDefs.filter(function(sd){ return userSpecNames.indexOf(sd.name) >= 0; });
  if (eligibleSpecs.length < 2) { container.style.display = 'none'; return; }

  function roleFor(name) {
    var entry = rawSpecs.find(function(s){ return _specEntryName(s) === name; });
    return entry ? _specEntryRole(entry) : '';
  }

  var activeSpecName = getActiveSpecialty() || eligibleSpecs[0].name;
  container.style.display = '';
  container.innerHTML =
    '<div style="padding:10px 12px;border-bottom:1px solid var(--border)">' +
      '<div style="font-size:10px;font-weight:700;color:var(--text3);text-transform:uppercase;letter-spacing:.06em;margin-bottom:8px">Active Specialty</div>' +
      '<div style="display:flex;flex-direction:column;gap:6px">' +
        eligibleSpecs.map(function(sd){
          var isActive = sd.name === activeSpecName;
          var role = roleFor(sd.name);
          return '<button onclick="switchSpecialty(&quot;' + sd.name.replace(/"/g,'&quot;') + '&quot;)" type="button"' +
            ' style="display:flex;align-items:center;gap:10px;padding:9px 12px;border:' +
            (isActive ? '2px solid var(--brand)' : '1px solid var(--border2)') +
            ';border-radius:10px;background:' + (isActive ? 'var(--brand-bg)' : 'var(--bg3)') +
            ';cursor:pointer;text-align:left;width:100%">' +
            '<div style="width:8px;height:8px;border-radius:50%;background:' + (isActive ? 'var(--brand)' : 'var(--border2)') + ';flex-shrink:0"></div>' +
            '<div style="min-width:0"><div style="font-size:12px;font-weight:' + (isActive?'700':'600') + ';color:var(--text)">' + sd.name + (role?' <span style="font-weight:400;color:var(--text3)">— '+role+'</span>':'') + '</div>' +
            (sd.taxonomy ? '<div style="font-size:10px;color:var(--text3);font-family:monospace">' + sd.taxonomy + '</div>' : '') +
            '</div>' +
            (isActive ? '<div style="margin-left:auto;font-size:9px;font-weight:700;color:var(--brand);background:var(--brand-bg);padding:2px 7px;border-radius:10px">ACTIVE</div>' : '') +
            '</button>';
        }).join('') +
      '</div>' +
    '</div>';
}

function _recreateClaimFromERA(eraId) {
  var db = getDB();
  var item = (db.eraPreviewQueue||[]).find(function(x){ return (x.eraId===eraId||x.id===eraId) && x.matched===false; });
  if (!item || !item.claimData) { toast('No claim data available for recreation','warn'); return; }
  var cd = item.claimData;

  // Try to find patient by memberId
  var pat = null;
  if (cd.memberId) {
    pat = (db.patients||[]).find(function(p){
      var ins = _resolvePatientInsurance(p);
      return (ins.subNum||p.insnum||'').trim().toUpperCase() === cd.memberId.trim().toUpperCase();
    });
  }

  var newClaim = {
    id: uid(),
    providerId: activeProviderId,
    pcn: cd.pcn || ('ERA-'+eraId),
    patId: pat ? pat.id : '',
    dos: cd.dos || '',
    payerid: cd.payerId || '',
    payerName: cd.payerName || '',
    lines: (cd.chargeLines||[]).map(function(cl){
      return {
        cpt: cl.cpt||'',
        charge: (cl.charge||0).toFixed(2),
        units: '1',
        mod1:'', mod2:'', mod3:'', mod4:'',
        dxPtrs:'1'
      };
    }),
    dx1: '', dx2:'', dx3:'', dx4:'',
    status: 'submitted',
    eraRecreated: true,
    eraId: eraId,
    notes: 'Recreated from ERA #'+eraId+' — PCN: '+cd.pcn,
    createdAt: Date.now(),
    updatedAt: Date.now()
  };

  setDB(function(db2){
    if(!db2.claims) db2.claims=[];
    db2.claims.push(newClaim);
    // Mark ERA item as recreated
    (db2.eraPreviewQueue||[]).forEach(function(x){
      if(x.eraId===eraId||x.id===eraId) x.status='recreated';
    });
  });

  toast('Claim recreated from ERA — open Claims to review','ok');
  updateBadges();
  renderEOBPage();
  setEOBTab('era-pending', null);
}
function renderERAPendingTab() {
  var db = getDB();
  var today = new Date(); today.setHours(0,0,0,0);

  // Pending items (not yet posted)
  var pendingItems = (db.eraPreviewQueue||[]).filter(function(x){
    return x.providerId===activeProviderId && x.status!=='posted' && x.status!=='dismissed';
  }).sort(function(a,b){ return new Date(a.checkDate)-new Date(b.checkDate); });

  // Already posted batches (show at bottom with POSTED badge)
  var postedItems = (db.eraPreviewQueue||[]).filter(function(x){
    return x.providerId===activeProviderId && x.status==='posted';
  }).sort(function(a,b){ return b.fetchedAt - a.fetchedAt; }).slice(0, 20);

  if (!pendingItems.length && !postedItems.length) {
    return '<div class="empty">'
      +'<div class="empty-ico"><i data-lucide="download-cloud" class="lci" style="width:32px;height:32px;color:var(--text3)"></i></div>'
      +'<h3>No ERA payments yet</h3>'
      +'<p style="font-size:12px;color:var(--text3)">Click <strong>Import Payments</strong> to pull from ClaimMD.</p>'
      +'<button class="btn btn-primary btn-sm" style="margin-top:10px" onclick="fetchERAFromClearinghouse()">'
        +'<i data-lucide="download-cloud" class="lci" style="width:13px;height:13px"></i> Import Payments'
      +'</button></div>';
  }

  function makeRow(item, isPosted) {
    var paidDate = item.checkDate ? new Date(item.checkDate) : null;
    var isFuture = !isPosted && paidDate && paidDate > today;
    var daysUntil = paidDate ? Math.ceil((paidDate - today)/(1000*60*60*24)) : null;

    var isNoMatch = item.matched === false;
    var badge = isPosted
      ? '<span style="font-size:9px;font-weight:700;padding:2px 7px;border-radius:10px;background:#f0faf5;color:#2d7a4f">✓ POSTED</span>'
      : item.status === 'recreated'
        ? '<span style="font-size:9px;font-weight:700;padding:2px 7px;border-radius:10px;background:#f5f4ed;color:#5e5d59">RECREATED</span>'
        : isNoMatch
          ? '<span style="font-size:9px;font-weight:700;padding:2px 7px;border-radius:10px;background:#fee2e2;color:#b91c1c">NO MATCH</span>'
          : isFuture
            ? '<span style="font-size:9px;font-weight:700;padding:2px 7px;border-radius:10px;background:#ede9fe;color:#7c3aed">In '+daysUntil+' day'+(daysUntil!==1?'s':'')+'</span>'
            : '<span style="font-size:9px;font-weight:700;padding:2px 7px;border-radius:10px;background:#fff3e0;color:#b35c00">READY</span>';

    var actions = isPosted
      ? '<span style="font-size:11px;color:#87867f">Posted</span>'
      : item.status === 'recreated'
        ? '<span style="font-size:11px;color:#87867f">Recreated</span>'
        : isNoMatch
          ? '<div style="display:flex;gap:4px">'
              +'<button class="btn btn-xs" style="background:var(--brand);color:#fff;border:none" onclick="event.stopPropagation();_recreateClaimFromERA(&quot;'+item.eraId+'&quot;)" title="Recreate Claim from ERA data">'
                +'<i data-lucide="refresh-cw" class="lci" style="width:11px;height:11px"></i> Recreate'
              +'</button>'
              +'<button class="btn btn-xs" onclick="event.stopPropagation();_eraDismissPending(&quot;'+item.eraId+'&quot;)" title="Dismiss">'
                +'<i data-lucide="x" class="lci" style="width:12px;height:12px"></i>'
              +'</button>'
            +'</div>'
          : '<div style="display:flex;gap:4px">'
              +'<button class="btn btn-xs btn-primary" onclick="_eraOpenPaymentDetail(&quot;'+item.eraId+'&quot;)" title="View & Post">'
                +'<i data-lucide="eye" class="lci" style="width:12px;height:12px"></i> Review'
              +'</button>'
              +'<button class="btn btn-xs" onclick="_eraDismissPending(&quot;'+item.eraId+'&quot;)" title="Dismiss">'
                +'<i data-lucide="x" class="lci" style="width:12px;height:12px"></i>'
              +'</button>'
            +'</div>';

    return '<tr style="border-bottom:1px solid var(--border)'+(isPosted?';opacity:.7':'')+'" '
      +'onclick="_eraOpenPaymentDetail(&quot;'+item.eraId+'&quot;)" '
      +'style="cursor:pointer;border-bottom:1px solid var(--border)'+(isPosted?';opacity:.7':'')+'">'
      +'<td style="padding:8px 10px;font-size:12px;font-weight:600;color:var(--text)">'+item.payerName+(isNoMatch&&item.pcn?'<div style="font-size:10px;font-family:monospace;color:var(--text3);margin-top:2px">PCN: '+item.pcn+'</div>':'')+'</td>'
      +'<td style="padding:8px 10px;font-size:11px;font-family:monospace;color:var(--text2)">'+item.checkNum+'</td>'
      +'<td style="padding:8px 10px;font-size:11px;color:var(--text2)">'+item.checkDate||item.dos||''+'</td>'
      +'<td style="padding:8px 10px">'+badge+'</td>'
      +'<td style="padding:8px 10px;font-size:13px;font-family:monospace;font-weight:800;color:#2d7a4f">$'+fmtMoney(item.checkAmt)+'</td>'
      +'<td style="padding:8px 10px;text-align:center;font-size:12px;color:var(--text2)">'+item.claimCount+'</td>'
      +'<td style="padding:8px 10px" onclick="event.stopPropagation()">'+actions+'</td>'
      +'</tr>';
  }

  var totalPending = pendingItems.reduce(function(s,x){return s+parseFloat(x.checkAmt||0);},0);
  var readyNow = pendingItems.filter(function(x){
    var d = x.checkDate ? new Date(x.checkDate) : null;
    return !d || d <= today;
  });

  var html = '';

  // Summary bar
  html += '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:14px">'
    +'<div style="display:flex;gap:12px;align-items:center">'
      +'<div style="font-size:12px;color:var(--text2)">'
        +'<strong style="font-size:15px;color:var(--text)">'+pendingItems.length+'</strong> pending'
        +' &nbsp;·&nbsp; <strong style="color:#2d7a4f">$'+fmtMoney(totalPending)+'</strong>'
        +(readyNow.length ? ' &nbsp;·&nbsp; <strong style="color:#b35c00">'+readyNow.length+' ready now</strong>' : '')
      +'</div>'
    +'</div>'
    +'<div style="display:flex;gap:6px">'
      +(readyNow.length ? '<button class="btn btn-primary btn-sm" onclick="_eraPostAllPending()">'
        +'<i data-lucide="check-circle" class="lci" style="width:13px;height:13px"></i> Post All Ready'
        +'</button>' : '')
    +'</div>'
  +'</div>';

  // Main table
  html += '<div class="tbl-wrap" style="margin:0">'
    +'<table style="width:100%"><thead><tr>'
      +'<th style="font-size:11px">Payer</th>'
      +'<th style="font-size:11px">Check / EFT #</th>'
      +'<th style="font-size:11px">Check Date</th>'
      +'<th style="font-size:11px">Status</th>'
      +'<th style="font-size:11px">Amount</th>'
      +'<th style="font-size:11px;text-align:center">Claims</th>'
      +'<th style="font-size:11px">Actions</th>'
    +'</tr></thead><tbody>';

  if (pendingItems.length) {
    html += pendingItems.map(function(item){ return makeRow(item, false); }).join('');
  }
  if (postedItems.length) {
    html += '<tr><td colspan="7" style="padding:8px 10px;font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);background:var(--bg3)">Recently Posted</td></tr>';
    html += postedItems.map(function(item){ return makeRow(item, true); }).join('');
  }

  html += '</tbody></table></div>';
  return html;
}


// ── ERA Payment Detail Floating Panel ─────────────────────────────────────
function _eraOpenPaymentDetail(eraId) {
  var db = getDB();
  var item = (db.eraPreviewQueue||[]).find(function(x){ return x.eraId===eraId; });
  var batch = (window._eraPreviewBatches||[]).find(function(b){ return b.eraId===eraId; });

  if (!item) { toast('ERA not found — please re-import','warn'); return; }

  // Build claim rows from batch lines (or from db if already posted)
  var lines = batch ? (batch.lines||[]) : [];
  var isPosted = item.status === 'posted';

  var claimRows = lines.map(function(l, idx) {
    var claim = db.claims.find(function(c){ return c.id===l.claimId; })||{};
    var pat   = db.patients.find(function(p){ return p.id===claim.patId; })||{};
    var patName = ((pat.last||'')+(pat.first?', '+pat.first:'')).trim()||'—';
    var cpts  = ((claim.lines)||[]).map(function(cl){ return cl.cpt||cl.code||''; }).filter(Boolean).join(', ');
    var billed = claimTotal(claim)||parseFloat(l.amtPaid||0);
    var coAdj = parseFloat(l.amtAdj||0);
    var paid  = parseFloat(l.amtPaid||0);
    var pr    = parseFloat(l.patResp||0);
    var alw   = billed - coAdj;
    // Adj lines for this claim
    var adjLines = (l.chargeLines||[]).flatMap ? (l.chargeLines||[]).flatMap(function(cl){
      return (cl.adjustments||[]).map(function(a){ return a.group+'-'+a.code+': $'+parseFloat(a.amount||0).toFixed(2); });
    }) : [];

    var alreadyPosted = !!(db.claimEOB && db.claimEOB[claim.id] &&
      db.claimEOB[claim.id].some(function(e){ return e.eraId===eraId; }));

    var rowBg = alreadyPosted ? 'background:#f0faf5' : '';
    var postBtn = alreadyPosted
      ? '<span style="font-size:10px;color:#2d7a4f;font-weight:700">✓ Posted</span>'
      : '<button class="btn btn-xs btn-primary" onclick="_eraPostSingleLine(&quot;'+eraId+'&quot;,'+idx+')" style="white-space:nowrap">'
          +'<i data-lucide="check-circle" class="lci" style="width:11px;height:11px"></i> Post'
        +'</button>';

    return '<tr style="border-bottom:1px solid var(--border);'+rowBg+';cursor:default">'
      +'<td style="padding:7px 10px">'
        +'<div style="font-size:11px;font-family:monospace;font-weight:700;color:var(--brand);cursor:pointer" '
          +'onclick="go(&quot;claim-editor&quot;);openClaimDetail(&quot;'+claim.id+'&quot;)" '
          +'title="Open claim">'+( claim.pcn||l.pcn||'—')+'</div>'
        +'<div style="font-size:10px;color:var(--text3)">'+(claim.billNum||'')+'</div>'
      +'</td>'
      +'<td style="padding:7px 10px;font-size:12px">'+patName+'</td>'
      +'<td style="padding:7px 10px;font-size:11px;color:var(--text2)">'+(l.dos||claim.dos||'—')+'</td>'
      +'<td style="padding:7px 10px;font-size:11px;color:var(--text2)">'+( cpts||'—')+'</td>'
      +'<td style="padding:7px 10px;font-size:11px;font-family:monospace;text-align:right">$'+billed.toFixed(2)+'</td>'
      +'<td style="padding:7px 10px;font-size:11px;font-family:monospace;text-align:right;color:#5e5d59">$'+alw.toFixed(2)+'</td>'
      +'<td style="padding:7px 10px;font-size:12px;font-family:monospace;font-weight:700;text-align:right;color:#2d7a4f">$'+paid.toFixed(2)+'</td>'
      +'<td style="padding:7px 10px;font-size:11px;font-family:monospace;text-align:right;color:#c96442">$'+coAdj.toFixed(2)+'</td>'
      +'<td style="padding:7px 10px;font-size:11px;font-family:monospace;text-align:right;color:#b35c00">$'+pr.toFixed(2)+'</td>'
      +'<td style="padding:7px 10px;font-size:10px;color:var(--text3)">'+adjLines.join('<br>')+'</td>'
      +'<td style="padding:7px 10px" onclick="event.stopPropagation()">'+postBtn+'</td>'
      +'</tr>';
  }).join('');

  var totalBilled = lines.reduce(function(s,l){ return s+claimTotal(db.claims.find(function(c){return c.id===l.claimId;})||{}); }, 0)||parseFloat(item.checkAmt||0);
  var totalPaid   = lines.reduce(function(s,l){ return s+parseFloat(l.amtPaid||0); }, 0);
  var totalAdj    = lines.reduce(function(s,l){ return s+parseFloat(l.amtAdj||0); }, 0);
  var totalPR     = lines.reduce(function(s,l){ return s+parseFloat(l.patResp||0); }, 0);

  var allPostedAlready = lines.length > 0 && lines.every(function(l){
    return !!(db.claimEOB && db.claimEOB[l.claimId] &&
      db.claimEOB[l.claimId].some(function(e){ return e.eraId===eraId; }));
  });

  var today = new Date(); today.setHours(0,0,0,0);
  var paidDate = item.checkDate ? new Date(item.checkDate) : null;
  var isFuture = paidDate && paidDate > today;

  var statusBanner = isPosted
    ? '<div style="padding:8px 14px;background:#f0faf5;border-bottom:1px solid #bbf7d0;font-size:12px;font-weight:600;color:#2d7a4f">'
        +'<i data-lucide="check-circle" class="lci" style="width:13px;height:13px"></i> All payments posted</div>'
    : isFuture
      ? '<div style="padding:8px 14px;background:#ede9fe;border-bottom:1px solid #ddd6fe;font-size:12px;font-weight:600;color:#7c3aed">'
          +'<i data-lucide="clock" class="lci" style="width:13px;height:13px"></i> Future payment — expected '+item.checkDate+'</div>'
      : '';

  var modalHtml =
    '<div class="overlay" id="modal-era-detail" style="z-index:9998">'
    +'<div class="modal" style="max-width:1100px;width:99%;max-height:92vh;display:flex;flex-direction:column">'

      // Header
      +'<div class="modal-hdr" style="flex-shrink:0;background:var(--bg3)">'
        +'<div style="flex:1">'
          +'<div class="modal-t" style="display:flex;align-items:center;gap:10px">'
            +'<i data-lucide="file-text" class="lci" style="width:16px;height:16px;color:var(--brand)"></i>'
            +item.payerName
            +(isPosted?'<span style="font-size:10px;font-weight:700;padding:2px 8px;border-radius:10px;background:#f0faf5;color:#2d7a4f">POSTED</span>':'')
          +'</div>'
          +'<div class="modal-sub">ERA #'+eraId+' &nbsp;·&nbsp; Check '+item.checkNum+' &nbsp;·&nbsp; '+item.checkDate+'</div>'
        +'</div>'
        +'<button class="btn btn-ghost btn-sm" onclick="closeModal(&quot;modal-era-detail&quot;)">×</button>'
      +'</div>'

      // Status banner
      +statusBanner

      // Check info grid
      +'<div style="flex-shrink:0;display:grid;grid-template-columns:repeat(5,1fr);gap:0;border-bottom:1px solid var(--border)">'
        +['Payer|'+item.payerName, 'Check / EFT #|'+item.checkNum, 'Check Date|'+item.checkDate,
          'Check Amount|$'+fmtMoney(item.checkAmt), 'Claims|'+lines.length]
          .map(function(kv){ var p=kv.split('|'); return '<div style="padding:10px 14px;border-right:1px solid var(--border)">'
            +'<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:3px">'+p[0]+'</div>'
            +'<div style="font-size:13px;font-weight:700;color:var(--text)">'+p[1]+'</div>'
          +'</div>'; }).join('')
      +'</div>'

      // Totals summary
      +'<div style="flex-shrink:0;display:grid;grid-template-columns:repeat(4,1fr);gap:0;border-bottom:2px solid var(--border);background:var(--bg2)">'
        +[['Total Billed','$'+fmtMoney(totalBilled),'var(--text)'],
          ['Allowed','$'+fmtMoney(totalBilled-totalAdj),'var(--text)'],
          ['Total Paid','$'+fmtMoney(totalPaid),'#2d7a4f'],
          ['Pat Resp','$'+fmtMoney(totalPR),'#c96442']]
          .map(function(item){ return '<div style="padding:8px 14px;border-right:1px solid var(--border)">'
            +'<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:2px">'+item[0]+'</div>'
            +'<div style="font-size:15px;font-weight:800;font-family:monospace;color:'+item[2]+'">'+item[1]+'</div>'
          +'</div>'; }).join('')
      +'</div>'

      // Claims table
      +'<div style="flex:1;overflow:auto">'
        +'<table style="width:100%;border-collapse:collapse">'
        +'<thead style="position:sticky;top:0;z-index:1"><tr style="background:var(--bg3)">'
          +'<th style="padding:7px 10px;font-size:10px;text-align:left">PCN / Bill#</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:left">Patient</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:left">DOS</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:left">CPT(s)</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:right">Billed</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:right">Allowed</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:right;color:#2d7a4f">Paid</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:right">CO Adj</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:right;color:#c96442">Pat Resp</th>'
          +'<th style="padding:7px 10px;font-size:10px">Remark Codes</th>'
          +'<th style="padding:7px 10px;font-size:10px;text-align:center">Action</th>'
        +'</tr></thead>'
        +'<tbody>'+( claimRows || '<tr><td colspan="11" style="padding:20px;text-align:center;color:var(--text3);font-size:12px">No claim details available — batch data may not be loaded. Please re-import.</td></tr>')+'</tbody>'
        +'</table>'
      +'</div>'

      // Footer
      +'<div class="modal-ftr" style="flex-shrink:0;justify-content:space-between">'
        +'<button class="btn" onclick="closeModal(&quot;modal-era-detail&quot;)">Close</button>'
        +(isPosted||allPostedAlready ? ''
          : '<button class="btn btn-primary" onclick="_eraPostAllFromDetail(&quot;'+eraId+'&quot;)">'
              +'<i data-lucide="check-circle" class="lci" style="width:13px;height:13px"></i> Post All Claims in This Payment'
            +'</button>')
      +'</div>'

    +'</div></div>';

  var ex = document.getElementById('modal-era-detail');
  if (ex) ex.remove();
  document.body.insertAdjacentHTML('beforeend', modalHtml);
  setTimeout(_renderLucideIcons, 50);
}

// Post a single claim line from the detail modal
function _eraPostSingleLine(eraId, lineIdx) {
  var batch = (window._eraPreviewBatches||[]).find(function(b){ return b.eraId===eraId; });
  if (!batch) { toast('Batch data not found — re-import','warn'); return; }
  var singleLineBatch = Object.assign({}, batch, { lines: [batch.lines[lineIdx]] });
  _postEOBToClaims(singleLineBatch);
  // Check if all lines are now posted, if so mark item as posted
  var db = getDB();
  var allDone = batch.lines.every(function(l){
    return !!(db.claimEOB && db.claimEOB[l.claimId] &&
      db.claimEOB[l.claimId].some(function(e){ return e.eraId===eraId; }));
  });
  if (allDone) {
    setEOBBatches(function(arr){ arr.push(batch); });
    setDB(function(db2){ (db2.eraPreviewQueue||[]).forEach(function(x){ if(x.eraId===eraId) x.status='posted'; }); });
  }
  toast('Claim posted');
  _eraOpenPaymentDetail(eraId); // refresh modal
  renderEOBPage();
}

// Post all claims from the detail modal
function _eraPostAllFromDetail(eraId) {
  var batch = (window._eraPreviewBatches||[]).find(function(b){ return b.eraId===eraId; });
  if (!batch) { toast('Batch data not found — re-import','warn'); return; }
  _postEOBToClaims(batch);
  setEOBBatches(function(arr){ arr.push(batch); });
  setDB(function(db2){ (db2.eraPreviewQueue||[]).forEach(function(x){ if(x.eraId===eraId) x.status='posted'; }); });
  closeModal('modal-era-detail');
  toast((batch.lines||[]).length+' claim(s) posted from ERA #'+eraId);
  renderEOBPage(); updateBadges(); setEOBTab('era-pending', null);
}

function _eraPostSinglePending(eraId) {
  var batch = (window._eraPreviewBatches||[]).find(function(b){ return b.eraId===eraId; });
  if (!batch) { toast('Batch data not found — re-fetch ERA','warn'); return; }
  _postEOBToClaims(batch);
  setEOBBatches(function(arr){ arr.push(batch); });
  setDB(function(db2){ (db2.eraPreviewQueue||[]).forEach(function(x){ if(x.eraId===eraId) x.status='posted'; }); });
  toast('ERA #'+eraId+' posted');
  renderEOBPage(); setEOBTab('era-pending', null);
}

function _eraPostAllPending() {
  var db = getDB();
  var today = new Date(); today.setHours(0,0,0,0);
  var items = (db.eraPreviewQueue||[]).filter(function(x){
    if(x.providerId!==activeProviderId||x.status==='posted'||x.status==='dismissed') return false;
    var d = x.checkDate ? new Date(x.checkDate) : null;
    return !d || d <= today;
  });
  if (!items.length) { toast('No ERA payments ready to post today','warn'); return; }
  var posted = 0;
  items.forEach(function(item){
    var batch = (window._eraPreviewBatches||[]).find(function(b){ return b.eraId===item.eraId; });
    if (!batch) return;
    _postEOBToClaims(batch);
    setEOBBatches(function(arr){ arr.push(batch); });
    posted++;
  });
  setDB(function(db2){
    var t = new Date(); t.setHours(0,0,0,0);
    (db2.eraPreviewQueue||[]).forEach(function(x){
      var d = x.checkDate ? new Date(x.checkDate) : null;
      if(x.providerId===activeProviderId&&x.status!=='posted'&&x.status!=='dismissed'&&(!d||d<=t)) x.status='posted';
    });
  });
  toast(posted+' ERA(s) posted');
  renderEOBPage(); setEOBTab('payments', null);
}

function _eraDismissPending(eraId) {
  setDB(function(db2){ (db2.eraPreviewQueue||[]).forEach(function(x){ if(x.eraId===eraId) x.status='dismissed'; }); });
  setEOBTab('era-pending', null); renderEOBPage();
}


// ?? EDI 835 Upload & Parse ????????????????????????????????????????
function handleEDI835Upload(event) {
const file = event.target.files[0];
if (!file) return;
const reader = new FileReader();
reader.onload = e => {
const text = e.target.result;
try {
const batch = parse835(text);
if (!batch) { toast('Could not parse 835 file','err'); return; }
_postEOBToClaims(batch);
setEOBBatches(arr => arr.push(batch));
renderEOBPage();
toast(`835 posted: ${batch.lines.length} claim(s)`);
} catch(err) {
toast('835 parse error: '+err.message,'err');
}
};
reader.readAsText(file);
event.target.value = '';
}

function parse835(text) {
const db = getDB();
const lines = [];
const unmatched = [];
let payerName = 'EDI 835 Import';
let checkNum = '';
let checkAmt = 0;
let checkDate = new Date().toLocaleDateString('en-US');

// Parse ISA/GS/ST segments
const segs = text.split(/[\n\r~]+/).map(s=>s.trim()).filter(Boolean);
let curClaim = null;
let clpPcn = '';
let clpPaid = 0;

segs.forEach(seg => {
const els = seg.split('*');
const id = els[0];

if (id==='N1' && els[1]==='PR') payerName = els[3]||payerName;
if (id==='TRN') { checkNum=els[2]||''; checkAmt=parseFloat(els[3]||0)||0; }
if (id==='DTM' && els[1]==='405') checkDate = _fmtEDIDate(els[2]);

if (id==='CLP') {
clpPcn = (els[1]||'').toUpperCase();
clpPaid = parseFloat(els[4]||0);
curClaim= db.claims.find(c=>c.pcn?.toUpperCase()===clpPcn && c.providerId===activeProviderId)||null;
}

if (id==='CAS' && curClaim) {
// CAS = adjustment — record first one
}

if (id==='SVC' && curClaim && clpPaid>0) {
const svcPaid = parseFloat(els[3]||0);
const svcAdj = parseFloat(els[4]||0);
const dos = curClaim.dos||'';
lines.push({
claimId: curClaim.id, pcn: clpPcn, dos,
amtPaid: svcPaid.toFixed(2),
amtAdj: svcAdj.toFixed(2),
adjCode: '835',
patResp: '0',
});
}
});

// Fallback: if no SVC segments but CLP has paid amount
if (!lines.length) {
segs.forEach(seg => {
const els = seg.split('*');
if (els[0]==='CLP') {
const pcn = (els[1]||'').toUpperCase();
const paid = parseFloat(els[4]||0);
const claim = db.claims.find(c=>c.pcn?.toUpperCase()===pcn && c.providerId===activeProviderId);
if (claim && paid>0) {
lines.push({ claimId:claim.id, pcn, dos:claim.dos||'', amtPaid:paid.toFixed(2), amtAdj:'0', adjCode:'835', patResp:'0' });
} else if (paid>0) {
unmatched.push({ id:uid(), providerId:activeProviderId, pcn, dos:'', amt:paid, source:'835', createdAt:Date.now() });
}
}
});
}

if (unmatched.length) {
setDB(db2=>{ if(!db2.eobUnmatched) db2.eobUnmatched=[]; db2.eobUnmatched.push(...unmatched); });
}

if (!lines.length && !unmatched.length) return null;

return {
id:uid(), providerId:activeProviderId,
payerName, payerId:'', checkNum,
checkDate, checkAmt: lines.reduce((s,l)=>s+parseFloat(l.amtPaid||0),0),
notes:`Imported from EDI 835 file`,
source:'835', lines,
createdAt:Date.now(), updatedAt:Date.now(),
};
}

function _fmtEDIDate(d) {
if (!d||d.length<8) return new Date().toLocaleDateString('en-US');
return `${d.slice(4,6)}/${d.slice(6,8)}/${d.slice(0,4)}`;
}

// ?? Secondary billing ????????????????????????????????????????????
function submitSecondary(claimId) {
const db = getDB();
const claim = db.claims.find(c=>c.id===claimId);
if (!claim) return;
const pat = db.patients.find(p=>p.id===claim.patId)||{};
const ins2 = (pat.insurances||[]).find(i=>!i.inactive&&(i.insType||i.type||'').toLowerCase().includes('secondary'));
if (!ins2) { toast('No secondary insurance on file','warn'); return; }

// Build secondary claim — swap payer info
const secClaim = {
...JSON.parse(JSON.stringify(claim)),
id: uid(),
pcn: buildNextPCN(claim.patId, activeProviderId, db.claims),
status: 'pending',
isSecondary: true,
primaryClaimId: claimId,
primaryPaid: claim.primaryPaid||0,
payerOverride: { payerId:ins2.payerId||'', payerName:ins2.name||ins2.insuranceName||'Secondary', memberId:ins2.memberId||ins2.policy||'' },
createdAt: Date.now(), updatedAt: Date.now(),
};

setDB(db2 => {
// Mark original as secondary-sent
const orig = db2.claims.find(c=>c.id===claimId);
if (orig) { orig.readyForSecondary=false; orig.secondarySent=true; orig.updatedAt=Date.now(); }
db2.claims.push(secClaim);
});

renderEOBPage();
renderClaims();
toast(`Secondary claim created: ${secClaim.pcn}`);
}

function exportSecondaryCSV() {
const db = getDB();
const ready = db.claims.filter(c=>c.providerId===activeProviderId && c.readyForSecondary);
if (!ready.length) { toast('No claims ready for secondary','warn'); return; }
// Use same CSV export but override payer info with secondary
const secClaims = ready.map(c => {
const pat = db.patients.find(p=>p.id===c.patId)||{};
const ins2 = (pat.insurances||[]).find(i=>!i.inactive&&(i.insType||i.type||'').toLowerCase().includes('secondary'));
if (!ins2) return null;
return {...c, _payerOverride: ins2};
}).filter(Boolean);
exportBulkClaimsCSV(secClaims);
toast(`${secClaims.length} secondary claim(s) exported`);
}

function matchUnmatched(id) {
const db = getDB();
const item = (db.eobUnmatched||[]).find(u=>u.id===id);
if (!item) return;
// Pre-fill search with PCN
document.getElementById('eob-search-field').value = 'pcn';
document.getElementById('eob-search-val').value = item.pcn||'';
document.getElementById('eob-search-dos').value = item.dos||'';
// Open search
openEOBClaimSearch();
setTimeout(searchEOBClaims, 100);
}

function dismissUnmatched(id) {
setDB(db2=>{ if(db2.eobUnmatched) db2.eobUnmatched=db2.eobUnmatched.filter(u=>u.id!==id); });
renderEOBPage();
}
function renderNotes() {
const el = document.getElementById('notes-list');
if (!el) return;
const db = getDB();
const notes = getNotes().filter(n=>n.providerId===activeProviderId);
console.log('[CDC] renderNotes: activeProviderId='+activeProviderId+' | total notes='+getNotes().length+' | matching='+notes.length);
_populateNoteFilters(db, notes);
if (!notes.length) {
el.innerHTML='<div class="empty"><div class="empty-ico"></div><h3>No encounters yet</h3><p>Encounters are automatically created when claims are generated.</p></div>';
return;
}
const q = (document.getElementById('notes-q')?.value||'').toLowerCase();
const patF = document.getElementById('notes-filter-pat')?.value||'';
const statusF = document.getElementById('notes-filter-status')?.value||'';
let list = [...notes].sort((a,b)=>b.createdAt-a.createdAt);
if (patF) list = list.filter(n=>n.patId===patF);
if (statusF) list = list.filter(n=>n.status===statusF);
if (q) list = list.filter(n=>{
const p=db.patients.find(x=>x.id===n.patId)||{};
return (p.last+' '+p.first+' '+n.cpt+' '+n.dos).toLowerCase().includes(q);
});
if (!list.length){el.innerHTML='<div class="empty"><div class="empty-ico"><i data-lucide="search" class="lci"></i></div><h3>No notes match filters</h3></div>';return;}
el.innerHTML=list.map(n=>{
const pat = db.patients.find(p=>p.id===n.patId)||{};
const rend = db.rendering.find(r=>r.id===n.renderingId)||{};
const cptLabel = (CPT_ENGINE[n.cpt]||CPT_ENGINE['DEFAULT']).label;
const preview = (n.body?.subjective||n.body?.s||'').slice(0,130)+'...';
const stBadge = n.status==='finalized'
? '<span class="badge b-green"><i data-lucide="check-circle" class="lci" style="width:11px;height:11px"></i> Finalized</span>'
: '<span class="badge b-amber">Draft</span>';
return `<div class="card" style="margin-bottom:10px;border-left:3px solid ${n.status==='finalized'?'var(--green)':'var(--amber)'}">
<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:6px">
<div style="flex:1">
<div style="font-size:14px">${ptLinkName(pat.id, pat.last, pat.first)} ${ptLinkAcct(pat.id, pat.acct)}</div>
<div style="font-size:12px;color:var(--text3);margin-top:2px">DOS: ${n.dos} &nbsp;·&nbsp; <strong>${(n.cptAll||[n.cpt]).join(', ')}</strong> &nbsp;·&nbsp; ${cptLabel} &nbsp;·&nbsp; ${rend.last?rend.last+', '+rend.first:''}</div>
<div style="font-size:11px;color:var(--text3);margin-top:4px;font-style:italic">${preview}</div>
</div>
<div style="display:flex;flex-direction:column;align-items:flex-end;gap:4px;flex-shrink:0">
${stBadge}
<div style="font-size:10px;color:var(--text3)">v${n.version||1} · ${new Date(n.createdAt).toLocaleDateString()}</div>
</div>
</div>
<div class="btn-group">
<button class="btn btn-sm" onclick="openEncounterEditor('${n.id}')">Edit / View</button>
<button class="btn btn-sm" onclick="exportNotePDF('${n.id}',false)"><i data-lucide="file-text" class="lci"></i> Export Note</button>
<button class="btn btn-sm" onclick="exportNotePDF('${n.id}',true)"><i data-lucide="clipboard-list" class="lci"></i> Note + Superbill</button>
${n.status!=='finalized'
?`<button class="btn btn-sm" style="color:var(--green)" onclick="finalizeNote('${n.id}')"><i data-lucide="check-circle" class="lci"></i> Finalize</button>
<button class="btn btn-sm" onclick="regenerateNote('${n.id}')"><i data-lucide="refresh-cw" class="lci"></i> Regenerate</button>`
:`<button class="btn btn-xs" onclick="unfinalizeNote('${n.id}')">Reopen</button>`}
<button title="Remove" class="btn btn-xs btn-danger" onclick="deleteNote('${n.id}')"><i data-lucide="x" class="lci"></i></button>
</div>
</div>`;
}).join('');

setTimeout(_renderLucideIcons, 20);
}


function _populateNoteFilters(db, notes) {
const sel=document.getElementById('notes-filter-pat');
if(!sel) return;
const pats=[...new Set((notes||[]).map(n=>n.patId))]
.map(id=>db.patients.find(p=>p.id===id)).filter(Boolean);
const curVal=sel.value;
sel.innerHTML='<option value="">All Patients</option>'+
pats.map(p=>`<option value="${p.id}" ${p.id===curVal?'selected':''}>${ptLinkName(p.id,p.last||'?',p.first||'')}</option>`).join('');
}

