function closeEncounterEditor() {
  if (_eeDirty && !confirm('You have unsaved changes. Discard them?')) return;
  _eeNoteId = ''; _eeDirty = false; _eeSaving = false;
  if (_eeAutoSaveTimer) { clearTimeout(_eeAutoSaveTimer); _eeAutoSaveTimer = null; }
  _eeCloseIcdDropdown();
  document.getElementById('encounter-editor').style.display = 'none';
  document.querySelector('#sec-notes .page-hdr').style.display = '';
  document.querySelector('#sec-notes .page-body > div:first-child').style.display = '';
  document.getElementById('notes-list').style.display = '';
  renderNotes();
}

function eeNavSection(key) {
  document.querySelectorAll('.ee-nav-item').forEach(el => el.classList.remove('active'));
  document.querySelectorAll('.ee-section').forEach(el => el.classList.remove('active'));
  if (!key) {
    document.querySelector('.ee-nav-item[data-key=""]')?.classList.add('active');
    document.getElementById('ee-sec-overview')?.classList.add('active');
    return;
  }
  const navEl = document.querySelector(`.ee-nav-item[data-key="${key}"]`);
  if (navEl) navEl.classList.add('active');
  const secEl = document.getElementById(`ee-sec-${key}`);
  if (secEl) secEl.classList.add('active');
  // Focus textarea if editable
  const ta = secEl?.querySelector('textarea');
  if (ta && !ta.readOnly) setTimeout(() => ta.focus(), 100);
}

function eeMarkDirty() {
  if (_eeSaving) return;
  _eeDirty = true;
  document.getElementById('ee-status').textContent = 'Unsaved changes';
  document.getElementById('ee-status').style.color = 'var(--amber)';
  if (_eeAutoSaveTimer) clearTimeout(_eeAutoSaveTimer);
  _eeAutoSaveTimer = setTimeout(() => { if (_eeDirty) eeSave(); }, 3000);
  const previewEl = document.getElementById('ee-preview');
  if (previewEl?.classList.contains('show')) eeUpdatePreview();
}

function eeSave(andFinalize) {
  if (_eeSaving) return;
  const id = _eeNoteId;
  if (!id) return;
  _eeSaving = true;
  const saveLabel = document.getElementById('ee-save-label');
  if (saveLabel) saveLabel.textContent = 'Saving...';

  const body = {};
  _eeSections.forEach(s => { body[s.key] = document.getElementById(`ee-txt-${s.key}`)?.value || ''; });
  const dx = [];
  for (let dxi = 0; dxi < 8; dxi++) {
    const inp = document.getElementById('ee-dx'+(dxi+1));
    dx.push(inp ? inp.value.trim().toUpperCase() : '');
  }

  setNotes(arr => {
    const n = arr.find(x => x.id === id);
    if (n) {
      n.body = { ...n.body, ...body };
      n.dx = dx;
      n.editedAt = Date.now(); n.updatedAt = Date.now(); n.version = (n.version||1) + 1;
      if (andFinalize) { n.status = 'finalized'; n.finalizedAt = Date.now(); }
    }
  });
  _neSyncDxToClaim(id, dx);
  _eeDirty = false;

  if (andFinalize) {
    eeAuditLog('ENCOUNTER_FINALIZE', `Encounter ${id} finalized by ${(getSession()?.email||'?')}`);
    closeEncounterEditor();
    toast('Encounter finalized ?');
  } else {
    _eeSaving = false;
    if (saveLabel) saveLabel.textContent = 'Save';
    document.getElementById('ee-status').textContent = 'Saved ' + new Date().toLocaleTimeString();
    document.getElementById('ee-status').style.color = 'var(--green)';
    toast('Saved');
  }
}

function eeTogglePreview() {
  const el = document.getElementById('ee-preview');
  const label = document.getElementById('ee-preview-label');
  if (!el) return;
  const show = !el.classList.contains('show');
  el.classList.toggle('show', show);
  if (label) label.textContent = show ? 'Hide Preview' : 'Preview';
  if (show) eeUpdatePreview();
}

function eeUpdatePreview() {
  const db = getDB();
  const notes = getNotes();
  const n = notes.find(x => x.id === _eeNoteId);
  if (!n) return;
  const pat = db.patients.find(p => p.id === n.patId) || {};
  const el = document.getElementById('ee-preview');
  el.innerHTML = `<div class="ep-title">Note Preview — ${pat.last||''}, ${pat.first||''}</div>
    ${_eeSections.map(s => {
      const txt = document.getElementById(`ee-txt-${s.key}`)?.value?.trim();
      return txt ? `<div class="ep-section">
        <div class="ep-section-label">${s.label}</div>
        <div class="ep-section-text">${txt.slice(0,300)}</div>
      </div>` : '';
    }).filter(Boolean).join('')||'<div style="color:var(--text3);font-style:italic">No content yet</div>'}
    <div style="margin-top:auto;padding-top:8px;border-top:1px solid var(--border);font-size:10px;color:var(--text3)">
      ${n.status==='finalized'?'FINALIZED':'Draft'} · v${n.version||1}
    </div>`;
}

// Hook preview updates into section navigation
const _origNavSection = eeNavSection;
eeNavSection = function(key) {
  _origNavSection(key);
  const previewEl = document.getElementById('ee-preview');
  if (previewEl?.classList.contains('show')) eeUpdatePreview();
};

