function openTCMEncounter(patId) {
  const db = getDB();
  if (!patId) {
    const pats = (db.patients||[]).filter(p=>p.providerId===activeProviderId);
    if (!pats.length) { toast('No patients found','warn'); return; }
    const d = document.createElement('div');
    d.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:5500;display:flex;align-items:center;justify-content:center;padding:16px;backdrop-filter:blur(8px)';
    d.innerHTML=`<div style="background:var(--surface);border-radius:20px;padding:20px 18px;width:100%;max-width:380px;max-height:80vh;overflow-y:auto;box-shadow:0 24px 60px rgba(0,0,0,.3)">
      <div style="font-size:17px;font-weight:700;margin-bottom:4px;color:var(--text);letter-spacing:-.03em">Select Patient</div>
      <div style="font-size:12px;color:var(--text3);margin-bottom:14px">Choose a patient for the TCM encounter</div>
      ${pats.map(p=>`<div onclick="this.closest('[style]').remove();openTCMEncounter('${p.id}')"
        style="padding:11px 14px;border-radius:12px;cursor:pointer;border:1px solid var(--border);margin-bottom:6px;display:flex;align-items:center;gap:12px;transition:all .15s"
        onmouseover="this.style.background='var(--brand-bg)';this.style.borderColor='var(--brand)'"
        onmouseout="this.style.background='';this.style.borderColor='var(--border)'">
        <div style="width:40px;height:40px;flex-shrink:0;border-radius:50%;overflow:hidden;background:var(--brand-bg)">
        ${p.photo?`<img src="${p.photo}" style="width:100%;height:100%;object-fit:cover">`:_patientAvatar(p,40)}
        </div>
        <div><div style="font-weight:600;font-size:13px;color:var(--text)">${p.last||'?'}, ${p.first||''}</div><div style="font-size:11px;color:var(--text3)">File #${p.acct||''}</div></div>
        <i data-lucide="chevron-right" class="lci" style="width:14px;height:14px;color:var(--text3);margin-left:auto"></i>
      </div>`).join('')}
      <button onclick="this.closest('[style]').remove()" style="width:100%;padding:10px;margin-top:6px;background:var(--bg3);border:none;border-radius:12px;font-size:13px;cursor:pointer;font-family:var(--font);color:var(--text2);font-weight:500">Cancel</button>
    </div>`;
    document.body.appendChild(d);
    setTimeout(_renderLucideIcons,10);
    return;
  }
  const pat = db.patients.find(p=>p.id===patId)||{};
  const rend = db.rendering.find(r=>r.id===activeProviderId)||{};
  const prov = db.providers.find(p=>p.id===activeProviderId)||{};
  const note = {
    id: uid(), patId, providerId: activeProviderId, renderingId: rend?.id||'',
    dos: new Date().toLocaleDateString('en-US',{month:'2-digit',day:'2-digit',year:'numeric'}),
    cpt: 'T1017', cptAll: ['T1017'], dx: [], pos: '53',
    encounterType: 'tcm', templateId: 0, status: 'draft',
    body: {}, createdAt: Date.now(), updatedAt: Date.now(),
    finalizedAt: null, editedAt: null, version: 1,
  };
  setNotes(arr => arr.push(note));
  toast('New TCM encounter created');
  openEncounterEditor(note.id, 'tcm');
}

