function eeApplyTemplate(tmplId) {
  const notes = getNotes();
  const n = notes.find(x => x.id === _eeNoteId);
  if (!n) return;
  const db = getDB();
  const pat = db.patients.find(p => p.id === n.patId) || {};
  const rend = db.rendering.find(r => r.id === n.renderingId) || {};
  const prov = db.providers.find(p => p.id === n.providerId) || {};
  const claim = db.claims?.find(c => c.id === n.claimId) || { dos: n.dos, pos: n.pos, lines: [], dx: n.dx || [] };
  const body = buildNoteBody(n.cpt, parseInt(tmplId), pat, rend, prov, claim, db, _eeEncType);
  _eeSections.forEach(s => {
    const ta = document.getElementById(`ee-txt-${s.key}`);
    if (ta) ta.value = body[s.key] || '';
  });
  setNotes(arr => {
    const x = arr.find(m => m.id === _eeNoteId);
    if (x) { x.templateId = parseInt(tmplId); x.body = body; x.updatedAt = Date.now(); x.version = (x.version || 1) + 1; }
  });
  _eeDirty = false;
  document.getElementById('ee-status').textContent = 'Template applied';
  document.getElementById('ee-status').style.color = 'var(--green)';
  const previewEl = document.getElementById('ee-preview');
  if (previewEl?.classList.contains('show')) eeUpdatePreview();
  toast('Template applied');
}

function eeInsertMacro(sectionKey, text) {
  const ta = document.getElementById(`ee-txt-${sectionKey}`);
  if (!ta) return;
  const start = ta.selectionStart, end = ta.selectionEnd;
  const before = ta.value.substring(0, start);
  const after = ta.value.substring(end);
  ta.value = before + (before && !before.match(/\n$/) ? '\n' : '') + text + (after ? '\n' : '') + after;
  const pos = start + text.length + (before && !before.match(/\n$/) ? 1 : 0);
  ta.selectionStart = ta.selectionEnd = pos;
  ta.focus();
  eeMarkDirty();
  document.querySelector('.ee-macro-dd')?.remove();
}

function eeToggleMacros(sectionKey, btn) {
  const existing = document.querySelector('.ee-macro-dd');
  if (existing) { existing.remove(); return; }
  const macros = EE_MACROS[sectionKey] || [];
  const dd = document.createElement('div');
  dd.className = 'ee-macro-dd';
  dd.innerHTML = '<div style="padding:6px 12px;font-weight:600;font-size:10.5px;color:var(--text3);text-transform:uppercase;letter-spacing:.04em;border-bottom:1px solid var(--border);background:var(--bg3)">Quick Phrases</div>' +
    macros.map(m => `<div class="ee-macro-dd-item" onclick="eeInsertMacro('${sectionKey}',\`${m.replace(/`/g,'\\`')}\`)">${m}</div>`).join('');
  btn.parentElement.appendChild(dd);
}

