function eeOpenSignature() {
  const notes = getNotes();
  const n = notes.find(x => x.id === _eeNoteId);
  if (!n) return;
  const db = getDB();
  const pat = db.patients.find(p => p.id === n.patId) || {};
  const rend = db.rendering.find(r => r.id === n.renderingId) || {};
  const prov = db.providers.find(p => p.id === n.providerId) || {};
  const sigName = rend.last ? `${rend.last}, ${rend.first||''} ${rend.cred||''}`.trim() : (prov.name || '');
  const existingSig = n.signatureData || '';

  const old = document.getElementById('modal-ee-sig');
  if (old) old.remove();
  document.body.insertAdjacentHTML('beforeend', `
  <div class="overlay" id="modal-ee-sig" style="display:flex;z-index:6000">
  <div class="modal" style="max-width:440px;width:94%">
    <div class="modal-hdr"><div><div class="modal-t">Signature — ${sigName}</div></div>
    <button title="Close" class="btn btn-ghost btn-sm" onclick="this.closest('.overlay').remove()"><i data-lucide="x" class="lci"></i></button></div>
    <div class="modal-body" style="min-height:300px">
      <div style="margin-bottom:12px">
        <div style="display:flex;gap:8px;margin-bottom:12px">
          <button id="ee-sig-tab-draw" class="btn btn-sm btn-primary" onclick="eeSigTab('draw')"><i data-lucide="pen" class="lci"></i> Draw</button>
          <button id="ee-sig-tab-upload" class="btn btn-sm" onclick="eeSigTab('upload')"><i data-lucide="upload" class="lci"></i> Upload</button>
          <button id="ee-sig-tab-electronic" class="btn btn-sm" onclick="eeSigTab('electronic')"><i data-lucide="check" class="lci"></i> Electronic</button>
        </div>
        <div id="ee-sig-panel-draw" style="display:block">
          <div style="font-size:11px;color:var(--text3);margin-bottom:6px">Draw your signature below:</div>
          <canvas id="ee-sig-canvas" class="ee-sig-canvas" width="380" height="160"></canvas>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="btn btn-sm" onclick="eeSigClear()"><i data-lucide="eraser" class="lci"></i> Clear</button>
          </div>
        </div>
        <div id="ee-sig-panel-upload" style="display:none">
          <div style="font-size:11px;color:var(--text3);margin-bottom:6px">Upload a signature image (PNG, JPG):</div>
          <label class="ee-sig-upload" id="ee-sig-upload-label">
            <i data-lucide="cloud-upload" class="lci" style="width:28px;height:28px;display:block;margin:0 auto 6px;color:var(--text3)"></i>
            Click to select image
            <input type="file" accept="image/png,image/jpeg,image/gif" style="display:none" onchange="eeSigUploaded(this)">
          </label>
          <img id="ee-sig-upload-preview" class="ee-sig-preview" style="display:none">
        </div>
        <div id="ee-sig-panel-electronic" style="display:none">
          <label style="display:flex;align-items:center;gap:8px;padding:14px;background:var(--bg3);border-radius:var(--r);cursor:pointer;font-size:13px">
            <input type="checkbox" id="ee-sig-electronic-cb" ${n.electronicSig?'checked':''} style="accent-color:var(--brand);width:18px;height:18px">
            <span>Electronically sign as <strong>${sigName}</strong></span>
          </label>
          <div style="font-size:11px;color:var(--text3);margin-top:8px;padding:8px 14px;background:var(--amber-bg);border-radius:var(--r);border:1px solid var(--amber-bdr)">
            <i data-lucide="info" class="lci" style="width:12px;height:12px;display:inline;vertical-align:middle"></i>
            Electronic signature confirms identity and intent to sign.
          </div>
        </div>
      </div>
      ${existingSig ? `<div style="margin-top:12px;padding-top:12px;border-top:1px solid var(--border)">
        <div style="font-size:11px;font-weight:600;color:var(--text3);margin-bottom:6px">Current Signature</div>
        <img src="${existingSig}" style="max-width:200px;max-height:50px;border-radius:6px;border:1px solid var(--border)">
      </div>` : ''}
    </div>
    <div class="modal-ftr">
      <button class="btn btn-ghost btn-sm" onclick="this.closest('.overlay').remove()">Cancel</button>
      <button class="btn btn-primary btn-sm" onclick="eeSigSave()"><i data-lucide="save" class="lci"></i> Save Signature</button>
    </div>
  </div>
  </div>`);
  setTimeout(() => {
    _renderLucideIcons();
    const canvas = document.getElementById('ee-sig-canvas');
    if (canvas) eeSigInitCanvas(canvas);
  }, 50);
}

let _eeSigCtx = null, _eeSigDrawing = false;

function eeSigInitCanvas(canvas) {
  const ctx = canvas.getContext('2d');
  _eeSigCtx = ctx;
  ctx.strokeStyle = '#1a1a2e';
  ctx.lineWidth = 2.5;
  ctx.lineCap = 'round';
  ctx.lineJoin = 'round';
  const rect = canvas.getBoundingClientRect();
  const getPos = e => {
    const r = canvas.getBoundingClientRect();
    const t = e.touches ? e.touches[0] : e;
    return { x: (t.clientX - r.left) * (canvas.width / r.width), y: (t.clientY - r.top) * (canvas.height / r.height) };
  };
  const start = e => { _eeSigDrawing = true; const p = getPos(e); ctx.beginPath(); ctx.moveTo(p.x, p.y); };
  const move = e => { if (!_eeSigDrawing) return; e.preventDefault(); const p = getPos(e); ctx.lineTo(p.x, p.y); ctx.stroke(); };
  const end = () => { _eeSigDrawing = false; };
  canvas.addEventListener('mousedown', start);
  canvas.addEventListener('mousemove', move);
  canvas.addEventListener('mouseup', end);
  canvas.addEventListener('mouseleave', end);
  canvas.addEventListener('touchstart', start, { passive: true });
  canvas.addEventListener('touchmove', move, { passive: false });
  canvas.addEventListener('touchend', end);
}

function eeSigTab(tab) {
  ['draw','upload','electronic'].forEach(t => {
    document.getElementById(`ee-sig-tab-${t}`).className = 'btn btn-sm' + (t === tab ? ' btn-primary' : '');
    document.getElementById(`ee-sig-panel-${t}`).style.display = t === tab ? 'block' : 'none';
  });
}

function eeSigClear() {
  if (!_eeSigCtx) return;
  const canvas = document.getElementById('ee-sig-canvas');
  _eeSigCtx.clearRect(0, 0, canvas.width, canvas.height);
}

function eeSigUploaded(input) {
  if (!input.files || !input.files[0]) return;
  const reader = new FileReader();
  reader.onload = function(e) {
    const img = document.getElementById('ee-sig-upload-preview');
    img.src = e.target.result;
    img.style.display = 'block';
    document.getElementById('ee-sig-upload-label').style.display = 'none';
  };
  reader.readAsDataURL(input.files[0]);
}

function eeSigSave() {
  const notes = getNotes();
  const n = notes.find(x => x.id === _eeNoteId);
  if (!n) return;
  let sigData = '';
  let sigType = '';
  if (document.getElementById('ee-sig-panel-draw')?.style.display !== 'none') {
    const canvas = document.getElementById('ee-sig-canvas');
    sigData = canvas.toDataURL('image/png');
    sigType = 'drawn';
  } else if (document.getElementById('ee-sig-panel-upload')?.style.display !== 'none') {
    const img = document.getElementById('ee-sig-upload-preview');
    if (img?.src && img.style.display !== 'none') { sigData = img.src; sigType = 'uploaded'; }
    else { toast('Please upload a signature image first','warn'); return; }
  } else {
    const cb = document.getElementById('ee-sig-electronic-cb');
    sigType = 'electronic';
    sigData = cb?.checked ? 'electronic' : '';
    if (!sigData) { toast('Please check the electronic signature box','warn'); return; }
  }
  setNotes(arr => {
    const x = arr.find(m => m.id === _eeNoteId);
    if (x) { x.signatureData = sigData; x.signatureType = sigType; x.signedAt = Date.now(); x.updatedAt = Date.now(); }
  });
  document.getElementById('modal-ee-sig')?.remove();
  _eeDirty = true;
  eeMarkDirty();
  toast('Signature saved');
  const navEl = document.querySelector('.ee-nav-item[data-key="sig"]');
  if (navEl) navEl.innerHTML = '<i data-lucide="pen-box" class="lci" style="width:14px;height:14px"></i> Signature ✓';
  setTimeout(_renderLucideIcons, 10);
}

// ?? Unlock Workflow ????????????????????????????????????????????????????
function eeAuditLog(action, details) {
  try {
    const key = 'cdc_audit_' + (activeProviderId || 'g');
    const logs = JSON.parse(localStorage.getItem(key) || '[]');
    const s = getSession();
    logs.push({ ts: Date.now(), user: s?.email || s?.name || 'unknown', role: s?.role || '', action, details });
    localStorage.setItem(key, JSON.stringify(logs.slice(-500)));
  } catch(e) {}
}

function eeUnlock(reason) {
  if (!reason || !reason.trim()) { reason = prompt('Reason for unlocking this encounter:'); if (!reason) return; }
  if (!confirm('Unlock this finalized encounter? It will revert to draft status.')) return;
  const notes = getNotes();
  const n = notes.find(x => x.id === _eeNoteId);
  if (!n) return;
  const s = getSession();
  setNotes(arr => {
    const x = arr.find(m => m.id === _eeNoteId);
    if (x) { x.status = 'draft'; x.finalizedAt = null; x.unlockedAt = Date.now(); x.unlockedBy = s?.email || s?.name || 'unknown'; x.unlockReason = reason.trim(); x.updatedAt = Date.now(); }
  });
  eeAuditLog('ENCOUNTER_UNLOCK', `Encounter ${_eeNoteId} unlocked by ${s?.email||'?'}: ${reason}`);
  closeEncounterEditor();
  openEncounterEditor(_eeNoteId);
  toast('Encounter unlocked and reopened');
}

function openClaimById(claimId) {
const db=getDB();
const idx=db.claims.findIndex(c=>c.id===claimId);
if(idx>=0) openClaim(idx);
}

// PDF Export — Professional, Audit-Ready ?????????????????????????????
async function exportNotePDF(noteId, withSuperbill) {
const notes=getNotes();
const n=notes.find(x=>x.id===noteId);
if(!n){toast('Note not found','err');return;}
const db=getDB();
const pat=db.patients.find(p=>p.id===n.patId)||{};
const prov=db.providers.find(p=>p.id===n.providerId)||{};
const rend=db.rendering.find(r=>r.id===n.renderingId)||{};
const {jsPDF}=window.jspdf;
const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'letter'});
const W=216,M=16,RX=W-M,CW=RX-M;
const BLUE=[201,100,66],BGBLUE=[250,245,237],WHITE=[255,255,255],
BLACK=[22,22,22],DARK=[50,48,44],MID=[90,88,82],
LIGHT=[245,244,237],BORDER=[222,220,210],BGDARK=[40,38,34];

const fill=(x,y,w,h,c)=>{doc.setFillColor(...c);doc.rect(x,y,w,h,'F');};
const hln=(y,c=BORDER,lw=0.25)=>{doc.setDrawColor(...c);doc.setLineWidth(lw);doc.line(M,y,RX,y);};
const t=(s,x,y,o={})=>{
doc.setFont(o.font||'helvetica',o.bold?'bold':o.italic?'italic':'normal');
doc.setFontSize(o.size||9);
doc.setTextColor(...(o.color||BLACK));
doc.text(String(s||''),x,y,{align:o.align||'left',maxWidth:o.maxWidth});
};
const newPageIfNeeded=(needed,curY)=>{
if(curY+needed>255){
// footer current
_drawNoteFooter(doc,prov,fill,t,BGDARK,BLUE,WHITE,MID,W,M,RX);
doc.addPage();
fill(0,0,W,2,BLUE);
return M+4;
}
return curY;
};

// ?? Page 1: Document Header ??????????????????????????????????????????
fill(0,0,W,2,BLUE);
// Logo
let _encLogoH = 24;
if (prov.logo) {
  try { const _ld = _fitLogo(prov.logo, 24); doc.addImage(prov.logo, _imgFmt(prov.logo), M, M+2, _ld.w, _ld.h); _encLogoH = _ld.h; } catch(e) {}
}
const hx = prov.logo ? M + _encLogoH + 6 : M;
t(prov.name||'',hx,M+8,{bold:true,size:10,color:DARK,maxWidth:90});
t(`NPI: ${rend.npi||prov.npi||''} · EIN: ${prov.taxid||''}`,hx,M+14,{size:7.5,color:MID});
t([prov.addr1,prov.city,prov.state].filter(Boolean).join(', '),hx,M+19,{size:7,color:MID});
// Document label
const eType = n.encounterType || 'medical';
const eLabel = (ENCOUNTER_TYPES[eType]||ENCOUNTER_TYPES.medical).label;
t(eLabel.toUpperCase(),RX,M+9,{bold:true,size:14,color:DARK,align:'right'});
const cptLabel=(CPT_ENGINE[n.cpt]||CPT_ENGINE['DEFAULT']).label;
t(cptLabel,RX,M+15,{size:8,color:BLUE,align:'right'});
t(n.status==='finalized'?'FINALIZED':'DRAFT — Not for Billing',RX,M+21,{size:7.5,color:n.status==='finalized'?[0,140,70]:MID,align:'right'});
let y=M+_encLogoH+8;
hln(y,BORDER,0.5); y+=5;

// ?? Patient / Encounter Information Block ????????????????????????????
fill(M,y,CW,26,LIGHT);
fill(M,y,3,26,BLUE);
t('PATIENT & ENCOUNTER INFORMATION',M+6,y+5,{size:7,bold:true,color:MID});
// Row 1
t('Patient Name:',M+6,y+10,{size:7.5,color:MID});
t(`${pat.last||'?'}, ${pat.first||''}`,M+36,y+10,{size:8.5,bold:true,color:DARK});
t('Date of Birth:',M+100,y+10,{size:7.5,color:MID});
t(pat.dob||'',M+126,y+10,{size:8.5,bold:true,color:DARK});
// Row 2
t('Account #:',M+6,y+15.5,{size:7.5,color:MID});
t(pat.acct||'',M+36,y+15.5,{size:8.5,color:DARK});
t('Date of Service:',M+100,y+15.5,{size:7.5,color:MID});
t(n.dos,M+130,y+15.5,{size:8.5,bold:true,color:BLUE});
// Row 3
t('Insurance:',M+6,y+21,{size:7.5,color:MID});
t(`${pat.payerName||''} · ID: ${pat.subNum||''}`,M+36,y+21,{size:8,color:DARK,maxWidth:60});
t('POS:',M+100,y+21,{size:7.5,color:MID});
t(n.pos||'',M+115,y+21,{size:8,color:DARK});
y+=30;

// ?? Service & Provider Information Block ?????????????????????????????
fill(M,y,CW,26,BGBLUE);
fill(M,y,3,26,BLUE);
t('SERVICE & PROVIDER INFORMATION',M+6,y+5,{size:7,bold:true,color:MID});
t('CPT Code(s):',M+6,y+10,{size:7.5,color:MID});
t((n.cptAll||[n.cpt]).join(', '),M+36,y+10,{size:8.5,bold:true,color:BLUE});
t('Service Type:',M+100,y+10,{size:7.5,color:MID});
t(cptLabel,M+126,y+10,{size:8,color:DARK,maxWidth:60});
t('Rendering Provider:',M+6,y+15.5,{size:7.5,color:MID});
t(rend.last?`${rend.last}, ${rend.first||''}`:(prov.name||''),M+42,y+15.5,{size:8.5,bold:true,color:DARK});
t('NPI:',M+100,y+15.5,{size:7.5,color:MID});
t(rend.npi||prov.npi||'',M+112,y+15.5,{size:8,color:DARK});
t('Diagnosis (ICD-10):',M+6,y+21,{size:7.5,color:MID});
t((n.dx||[]).filter(Boolean).map((d,i)=>`${String.fromCharCode(65+i)}) ${d}`).join(' '),M+42,y+21,{size:8,color:DARK,maxWidth:130});
y+=30;
hln(y,BORDER,0.4); y+=5;

// ?? Clinical Sections ????????????????????????????????????????????????
const eSections = (ENCOUNTER_TYPES[eType]||ENCOUNTER_TYPES.medical).sections;
const clinSections = eSections.map(s => ({
  key: s.key,
  label: s.label.toUpperCase(),
  highlight: s.key === 'mn_statement' || s.key === 'interventions' || s.key === 'barriers',
}));

clinSections.forEach(sec=>{
const text=n.body?.[sec.key]||'Not documented.';
const lines=doc.splitTextToSize(text, CW-10);
const secH=lines.length*4.8+12;
y=newPageIfNeeded(secH,y);
// Section label bar
fill(M,y,CW,8,sec.highlight?BGBLUE:LIGHT);
fill(M,y,3,8,BLUE);
t(sec.label,M+6,y+5.5,{size:7.5,bold:true,color:sec.highlight?BLUE:MID});
y+=10;
// Text content
doc.setFont('helvetica','normal');
doc.setFontSize(9);
doc.setTextColor(...DARK);
doc.text(lines,M+2,y);
y+=lines.length*4.8+4;
hln(y,[230,234,240],0.2); y+=3;
});

// ?? Signature Block ??????????????????????????????????????????????????
y=newPageIfNeeded(20,y);
y+=3;
const sigH = (n.signatureData && n.signatureData !== 'electronic') ? 20 : 16;
fill(M,y,CW,sigH,LIGHT);
fill(M,y,3,sigH,BLUE);
const now=new Date();
const sigName=rend.last?`${rend.last}, ${rend.first||''} ${rend.cred||''}`.trim():prov.name||'';
t('PROVIDER AUTHENTICATION',M+6,y+5,{size:6.5,bold:true,color:MID});
// Draw signature image if available (not electronic-only)
if (n.signatureData && n.signatureData !== 'electronic') {
  try { doc.addImage(n.signatureData, 'PNG', M+48, y+3, 40, 14); } catch(e) {
    // fallback: if image fails, just show name text
    t(sigName,M+46,y+10,{font:'courier',bold:true,size:9,color:DARK});
  }
} else {
  t(sigName,M+46,y+10,{font:'courier',bold:true,size:9,color:DARK});
}
t(`Signed: ${n.signedAt?new Date(n.signedAt).toLocaleString():n.dos+' '+now.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`,RX,y+10,{font:'courier',size:7.5,color:MID,align:'right'});
if(rend.npi) t(`NPI: ${rend.npi}`,M+6,y+sigH-5,{font:'courier',size:7.5,color:MID});
if(n.finalizedAt) t(`Finalized: ${new Date(n.finalizedAt).toLocaleString()}`,RX,y+sigH-5,{font:'courier',size:7.5,color:[0,140,70],align:'right'});
// Generate note-specific QR for verification
try {
  const qrText = `CDCNOTE:${n.id}:${prov.npi||rend.npi||''}:${n.dos}:${n.status}`;
  const qrSize = 18;
  if (!_qrDataURL || _qrDataURL.indexOf('claimdatacare.com')>0) _qrDataURL = generateQRDataURL(qrText, 80);
  if (_qrDataURL) {
    try { doc.addImage(_qrDataURL, 'PNG', RX - qrSize - 2, y + 1, qrSize, qrSize, undefined, 'FAST'); } catch(e) {}
  }
} catch(e) {}
y+=sigH+3;

// ?? Optional Superbill Reference Page ????????????????????????????????
if(withSuperbill){
const claim=db.claims?.find(c=>c.id===n.claimId);
if(claim){
_drawNoteFooter(doc,prov,fill,t,BGDARK,BLUE,WHITE,MID,W,M,RX);
doc.addPage(); fill(0,0,W,2,BLUE); y=M;
fill(M,y,CW,10,BGBLUE); fill(M,y,3,10,BLUE);
t('SUPERBILL ATTACHMENT',M+6,y+7,{bold:true,size:10,color:BLUE});
t(`PCN: ${claim.pcn} · Total: $${fmtMoney(claimTotal(claim))}`,RX,y+7,{size:8,color:DARK,align:'right'});
y+=14;
// Services
fill(M,y,CW,7,[200,210,230]);
t('CPT',M+3,y+5,{size:7,bold:true,color:DARK});
t('Description',M+16,y+5,{size:7,bold:true,color:DARK});
t('Units',M+100,y+5,{size:7,bold:true,color:DARK});
t('Charge',RX,y+5,{size:7,bold:true,color:DARK,align:'right'});
y+=8;
claim.lines?.forEach((l,li)=>{
const svc=db.services?.find(s=>s.code===l.cpt)||{};
if(li%2===1)fill(M,y-1,CW,7,LIGHT);
t(l.cpt,M+3,y+4,{size:8.5,bold:true,color:BLUE});
t((svc.desc||'').slice(0,35),M+16,y+4,{size:8,color:DARK});
t(String(l.units||1),M+100,y+4,{size:8,color:DARK});
t(`$${fmtMoney((parseFloat(l.charge)||0))}`,RX,y+4,{size:8.5,bold:true,color:DARK,align:'right'});
hln(y+5.5,BORDER,0.2); y+=7;
});
y+=3;
fill(M,y,CW,10,BGBLUE); fill(M,y,3,10,BLUE);
t('TOTAL CHARGES',M+6,y+7,{bold:true,size:9,color:BLUE});
t(`$${fmtMoney(claimTotal(claim))}`,RX,y+7,{size:11,bold:true,color:BLUE,align:'right'});
}
}

// Footer all pages
const totalPgs=doc.getNumberOfPages();
for(let pg=1;pg<=totalPgs;pg++){
doc.setPage(pg);
_drawNoteFooter(doc,prov,fill,t,BGDARK,BLUE,WHITE,MID,W,M,RX,pg,totalPgs);
}

// Filename
const ln2=(pat.last||'XX').replace(/[^A-Za-z]/g,'').slice(0,2).toUpperCase();
const fn2=(pat.first||'XX').replace(/[^A-Za-z]/g,'').slice(0,2).toUpperCase();
const ts=now.getFullYear().toString()+String(now.getMonth()+1).padStart(2,'0')+String(now.getDate()).padStart(2,'0')+String(now.getHours()).padStart(2,'0')+String(now.getMinutes()).padStart(2,'0')+String(now.getSeconds()).padStart(2,'0');
addPDFWatermark(doc); doc.save(`MN${ln2}${fn2}${ts}${withSuperbill?'_SB':''}.pdf`);
toast('Encounter note PDF exported ?');
}

function _drawNoteFooter(doc,prov,fill,t,BGDARK,BLUE,WHITE,MID,W,M,RX,pg,total){
fill(0,263,W,12,BGDARK); fill(0,263,W,2,BLUE);
t(prov.name||'',M+2,271.5,{size:7.5,color:[200,205,210]});
t('Encounter Note — Confidential',W/2,271.5,{size:7.5,color:[160,175,195],align:'center'});
if(pg&&total) t(`Page ${pg} of ${total}`,RX,271.5,{size:7.5,color:[200,205,210],align:'right'});
}

