function toggleTnDropdown(name, e) {
if (e) e.stopPropagation();
const grp = document.getElementById('tng-' + name);
if (!grp) return;
const isOpen = grp.classList.contains('open');
document.querySelectorAll('.tn-group.open').forEach(g => g.classList.remove('open'));
if (!isOpen) { grp.classList.add('open'); _openTnGroup = name; }
else { _openTnGroup = null; }
}

function closeTnDropdown() {
document.querySelectorAll('.tn-group.open').forEach(g => g.classList.remove('open'));
_openTnGroup = null;
}

// Wire hover-to-close on each dropdown group after DOM is ready
function _initTnHover() {
document.querySelectorAll('.tn-group').forEach(grp => {
grp.addEventListener('mouseleave', () => {
_tnHideTimer = setTimeout(() => grp.classList.remove('open'), 200);
});
grp.addEventListener('mouseenter', () => {
if (_tnHideTimer) { clearTimeout(_tnHideTimer); _tnHideTimer = null; }
});
});
}

