function _openCropFromDoc(patId, docId) {
document.getElementById('pt-photo-dialog')?.remove();
const db = getDB();
const pat = db.patients.find(p=>p.id===patId)||{};
const doc = (pat.documents||[]).find(d=>d.id===docId);
if (!doc||!doc.data) { toast('Document not available','err'); return; }

const isPDF = (doc.type&&doc.type.includes('pdf')) || /\.pdf$/i.test(doc.name||'');

if (isPDF) {
// Render PDF first page to canvas, then open crop tool
toast('Rendering PDF for cropping...','info');
if (typeof pdfjsLib === 'undefined') {
// Load PDF.js on demand
const script = document.createElement('script');
script.src = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
script.onload = () => { pdfjsLib.GlobalWorkerOptions.workerSrc='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js'; _renderPDFForCrop(patId, doc.data); };
document.head.appendChild(script);
} else {
_renderPDFForCrop(patId, doc.data);
}
} else {
window._cropSrc = doc.data;
_openCropTool(patId, doc.data);
}
}

function _renderPDFForCrop(patId, pdfData) {
const loading = document.createElement('div');
loading.id = 'pt-pdf-loading';
loading.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.7);z-index:5800;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:12px;color:#fff;font-size:14px;font-weight:600';
loading.innerHTML='<i data-lucide="loader" class="lci" style="width:32px;height:32px;animation:spin 1s linear infinite"></i><div>Rendering PDF...</div>';
document.body.appendChild(loading);
setTimeout(_renderLucideIcons, 10);

pdfjsLib.getDocument({data: atob(pdfData.split(',')[1]||pdfData)}).promise
.then(pdf => pdf.getPage(1))
.then(page => {
const scale = 2;
const vp = page.getViewport({scale});
const canvas = document.createElement('canvas');
canvas.width = vp.width;
canvas.height = vp.height;
return page.render({canvasContext:canvas.getContext('2d'), viewport:vp}).promise
.then(() => {
document.getElementById('pt-pdf-loading')?.remove();
const imgData = canvas.toDataURL('image/jpeg', 0.95);
window._cropSrc = imgData;
_openCropTool(patId, imgData);
});
})
.catch(err => {
document.getElementById('pt-pdf-loading')?.remove();
toast('Could not render PDF: '+err.message,'err');
});
}



