// ?? Wire all nav icons after shell renders ?????????????????????????????
function _initNavIcons() {
// Icons are inline data-lucide in the HTML — just trigger Lucide and update buttons
const isDark = document.documentElement.getAttribute('data-theme') === 'dark';
const btnDark = document.getElementById('btn-dark');
if (btnDark) btnDark.innerHTML = isDark ? _iconSun() : _iconMoon();
const btnLang = document.getElementById('btn-lang');
if (btnLang) btnLang.textContent = (typeof LANG !== 'undefined' && LANG === 'es') ? 'EN' : 'ES';
_renderLucideIcons();
}
var _lucideTimer = null;
function _renderLucideIcons() {
if (_lucideTimer) return;
_lucideTimer = setTimeout(function() {
_lucideTimer = null;
if (typeof lucide !== 'undefined' && typeof lucide.createIcons === 'function') {
lucide.createIcons();
}
}, 20);
}



// Uppercase all text rendered in PDFs
function _patchPDF() {
  try {
    var proto = (window.jspdf && window.jspdf.jsPDF && window.jspdf.jsPDF.prototype);
    if (!proto) return;
    var origText = proto.text;
    if (!origText.__patched) {
      proto.text = function() {
        var args = Array.prototype.slice.call(arguments);
        if (typeof args[0] === 'string') args[0] = args[0].toUpperCase();
        else if (Array.isArray(args[0])) args[0] = args[0].map(function(t){return typeof t==='string'?t.toUpperCase():t;});
        return origText.apply(this, args);
      };
      proto.text.__patched = true;
    }
  } catch(e) {}
}
_patchPDF();

