const CM_KEY = 'cdc_cm_data_v1';

// CM empty template
function _cmEmpty() {
  return {
    clients:[], workers:[], plans:[], notes:[], billing:[],
    referrals:[], eligibility:[], assessments:[], tasks:[],
    authorizations:[], communityReferrals:[], encounters:[],
    discharges:[], cmSettings:{ billingRate:12.50, defaultCode:'T1017' }
  };
}

// getCMData -- reads from _localDB.cm (Firestore-backed).
// Falls back to legacy CM_KEY localStorage on first run and auto-migrates.
function getCMData() {
  // Primary: in-memory _localDB.cm (populated from Firestore on login)
  if (_localDB && _localDB.cm && Object.keys(_localDB.cm).length > 0) {
    return _localDB.cm;
  }
  // Migration: if old CM_KEY data exists in localStorage, adopt it
  try {
    var r = localStorage.getItem(CM_KEY);
    if (r) {
      var parsed = JSON.parse(r);
      if (parsed && typeof parsed === 'object') {
        if (!_localDB) _localDB = {};
        _localDB.cm = Object.assign(_cmEmpty(), parsed);
        // Kick off async Firestore write so it propagates to other devices
        _saveCMToFirestore(_localDB.cm);
        // Clear old key so migration only happens once
        try { localStorage.removeItem(CM_KEY); } catch(e) {}
        console.log('[CDC] CM data migrated from localStorage to Firestore');
        return _localDB.cm;
      }
    }
  } catch(e) {}
  // No data anywhere -- return empty and initialize in _localDB
  if (!_localDB) _localDB = {};
  if (!_localDB.cm) _localDB.cm = _cmEmpty();
  return _localDB.cm;
}

// saveCMData -- writes to _localDB.cm and syncs to Firestore
function saveCMData(d) {
  if (!_localDB) _localDB = {};
  _localDB.cm = d;
  // Save full cache so offline reload includes updated CM data
  try { _saveCache(_localDB); } catch(e) {}
  // Async sync to Firestore
  _saveCMToFirestore(d);
}

// Async Firestore write for CM data (stored as a single meta document)
function _saveCMToFirestore(d) {
  if (!_fbReady || !_db || !d) return;
  try {
    _db.collection('meta').doc('cmData').set(d).catch(function(e){
      console.warn('[CDC] CM Firestore write failed:', e.message);
    });
  } catch(e) {}
}
function _cmId() { return 'cm_' + Date.now() + '_' + Math.random().toString(36).slice(2,7); }
function _cmDateStr(d) {
  if (!d) return '';
  if (typeof d === 'string') return d;
  return (d.getMonth()+1)+'/'+d.getDate()+'/'+d.getFullYear();
}
function _cmNowISO() { return new Date().toISOString(); }
function _cmFmtMoney(n) { return '$' + Number(n||0).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }
function _cmStatusBadge(s) {
  var m = {
    Active:'b-green', Inactive:'b-gray', Discharged:'b-red',
    Draft:'b-gray', Ready:'b-blue', Submitted:'b-amber',
    Paid:'b-green', Rejected:'b-red',
    Completed:'b-green', Expired:'b-amber',
    Pending:'b-amber', Approved:'b-green', 'Needs Review':'b-amber',
    'Billing Hold':'b-red', 'Ready to Bill':'b-blue',
    Verified:'b-green', Unverified:'b-gray',
    Open:'b-blue', Closed:'b-green',
    High:'b-red', Medium:'b-amber', Low:'b-gray',
    'In Progress':'b-blue', 'Not Started':'b-gray',
    Signed:'b-green', 'Missed':'b-red', Cancelled:'b-gray',
    Converted:'b-blue'
  };
  var c = m[s] || 'b-gray';
  return '<span class="badge '+c+'">'+s+'</span>';
}
function _cmWorkerName(wid) {
  var d = getCMData();
  var w = d.workers.find(function(x){return x.id===wid;});
  return w ? (w.first+' '+w.last) : '—';
}
function _cmClientName(cid) {
  var d = getCMData();
  var c = d.clients.find(function(x){return x.id===cid;});
  return c ? (c.last+', '+c.first) : '—';
}
function _cmClientOpts() {
  var d = getCMData();
  return d.clients.filter(function(c){return c.status==='Active';}).map(function(c){
    return '<option value="'+c.id+'">'+c.last+', '+c.first+' ('+(c.medicaidId||'')+')</option>';
  }).join('');
}
function _cmWorkerOpts() {
  var d = getCMData();
  return d.workers.filter(function(w){return w.status!=='Inactive';}).map(function(w){
    var sup = w.supervisorId ? ' — Sup: '+_cmWorkerName(w.supervisorId) : '';
    return '<option value="'+w.id+'">'+w.first+' '+w.last+sup+'</option>';
  }).join('');
}
function _isCMRole() {
  var s = getSession();
  if (!s) return false;
  if (s.role === 'Super Admin') return true;
  // Single source of truth: Case Management access now follows the same
  // specialty → menu grant used everywhere else (tng-cm), instead of a
  // separate "Case Management" role flag that could drift out of sync.
  var db = getDB();
  var prov = (db.providers||[]).find(function(p){ return p.id === activeProviderId; }) || {};
  var specDefs = prov.specialtyDefs || [];
  if (!specDefs.length) return true; // no specialties configured on this provider — don't lock anyone out
  var activeSpecName = getActiveSpecialty();
  var activeDef = specDefs.find(function(sd){ return sd.name === activeSpecName; });
  if (!activeDef) return true; // couldn't resolve an active specialty — fail open rather than lock out
  return (activeDef.menus||[]).indexOf('tng-cm') >= 0;
}

