function saveCMPlan(id) {
  var d = getCMData();
  var clientId = document.getElementById('cmp-client')?.value;
  if (!clientId) { toast('Select a client','warn'); return; }
  var goalEls = document.querySelectorAll('.cmp-goal');
  var goalStEls = document.querySelectorAll('.cmp-goal-st');
  var goals = [];
  goalEls.forEach(function(el,i){
    var txt = el.value.trim();
    if (txt) goals.push({text:txt, status:goalStEls[i]?.value||'Not Started'});
  });
  var obj = {
    clientId: clientId,
    workerId: document.getElementById('cmp-worker')?.value||'',
    createdDate: document.getElementById('cmp-created')?.value||'',
    nextReview: document.getElementById('cmp-review')?.value||'',
    status: document.getElementById('cmp-status')?.value||'Active',
    goals: goals,
    updatedAt: _cmNowISO()
  };
  if (id) {
    var idx = d.plans.findIndex(function(x){return x.id===id;});
    if (idx>=0) Object.assign(d.plans[idx], obj);
  } else {
    obj.id = _cmId();
    obj.createdAt = _cmNowISO();
    d.plans.push(obj);
  }
  saveCMData(d);
  document.querySelectorAll('[data-cm]').forEach(function(o){o.remove();});
  renderCMPlans();
  toast('Plan saved');
}
function editCMPlan(id) { openCMPlanModal(id); }
function delCMPlan(id) {
  if (!confirm('Delete this plan?')) return;
  var d = getCMData();
  d.plans = d.plans.filter(function(x){return x.id!==id;});
  saveCMData(d);
  renderCMPlans();
  toast('Plan deleted');
}

// ── CM: PROGRESS NOTES ─────────────────────────────────────────
function renderCMNotes() {
  if (!_isCMRole()) return;
  var el = document.getElementById('cm-notes-tbl');
  if (!el) return;
  var d = getCMData();
  var q = (document.getElementById('cm-note-q')?.value||'').toLowerCase().trim();
  var bf = document.getElementById('cm-note-billable')?.value||'';
  var list = d.notes.slice().sort(function(a,b){return new Date(b.date)-new Date(a.date);});
  if (bf) list = list.filter(function(n){return String(n.billable?1:0)===bf;});
  if (q) list = list.filter(function(n){return (_cmClientName(n.clientId)+' '+_cmWorkerName(n.workerId)).toLowerCase().includes(q);});
  if (!list.length) {
    el.innerHTML = '<div class="empty"><h3>No progress notes found</h3><button class="btn btn-primary btn-sm" onclick="openCMNoteModal()">+ New Note</button></div>';
    return;
  }
  el.innerHTML =
    '<div class="tbl-wrap"><table><thead><tr><th>Date</th><th>Client</th><th>Worker</th><th>Type</th><th>Units</th><th>Location</th><th>Signature</th><th></th></tr></thead><tbody>'+
    list.map(function(n){
      return '<tr>'+
        '<td style="font-size:12px;white-space:nowrap">'+(n.date||'')+'</td>'+
        '<td style="font-weight:600">'+_cmClientName(n.clientId)+'</td>'+
        '<td style="font-size:12px">'+_cmWorkerName(n.workerId)+'</td>'+
        '<td>'+(n.billable?'<span class="badge b-green">Billable</span>':'<span class="badge b-gray">Non-Billable</span>')+'</td>'+
        '<td style="text-align:center;font-weight:600">'+(n.units||0)+'</td>'+
        '<td style="font-size:12px">'+(n.location||'')+'</td>'+
        '<td style="font-size:11px">'+(n.signature?'<span style="color:var(--green)">Signed</span>':'<span style="color:var(--text3)">—</span>')+'</td>'+
        '<td><div class="btn-group" style="gap:3px">'+
        '<button class="btn-icon sm" onclick="editCMNote(\''+n.id+'\')" title="Edit"><i data-lucide="pencil" class="lci" style="width:12px;height:12px"></i></button>'+
        '<button class="btn-icon sm danger" onclick="delCMNote(\''+n.id+'\')" title="Delete"><i data-lucide="trash-2" class="lci" style="width:12px;height:12px"></i></button>'+
        '</div></td></tr>';
    }).join('')+
    '</tbody></table></div>';
  setTimeout(_renderLucideIcons, 20);
}
