// ── CM: SUPERVISOR REVIEW / QA ──────────────────────────────────
function renderCMSupervisor() {
  if (!_isCMRole()) return;
  var el = document.getElementById('cm-supervisor-tbl');
  var statsEl = document.getElementById('cm-sup-stats');
  if (!el) return;
  var d = getCMData();
  var allEnc = d.encounters || [];
  var filter = document.getElementById('cm-sup-filter')?.value||'pending';
  var list = allEnc.slice().sort(function(a,b){return new Date(b.date)-new Date(a.date);});
  if (filter==='pending') list = list.filter(function(n){return n.supervisorStatus==='Pending'||!n.supervisorStatus;});
  else if (filter==='approved') list = list.filter(function(n){return n.supervisorStatus==='Approved';});
  else if (filter==='returned') list = list.filter(function(n){return n.supervisorStatus==='Returned';});
  var pending = allEnc.filter(function(n){return n.supervisorStatus==='Pending'||!n.supervisorStatus;}).length;
  var approved = allEnc.filter(function(n){return n.supervisorStatus==='Approved';}).length;
  var returned = allEnc.filter(function(n){return n.supervisorStatus==='Returned';}).length;
  if (statsEl) statsEl.innerHTML =
    '<div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800;color:var(--amber)">'+pending+'</div><div style="font-size:10px;color:var(--text3)">Pending Review</div></div>'+
    '<div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800;color:var(--green)">'+approved+'</div><div style="font-size:10px;color:var(--text3)">Approved</div></div>'+
    '<div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800;color:var(--red)">'+returned+'</div><div style="font-size:10px;color:var(--text3)">Returned</div></div>'+
    '<div class="card" style="padding:12px;text-align:center"><div style="font-size:22px;font-weight:800;color:var(--blue)">'+allEnc.length+'</div><div style="font-size:10px;color:var(--text3)">Total Encounters</div></div>';
  if (!list.length) {
    el.innerHTML = '<div class="empty"><h3>No encounters to review</h3></div>';
    return;
  }
  el.innerHTML =
    '<div class="tbl-wrap"><table><thead><tr><th>Date</th><th>Client</th><th>Worker</th><th>Contact</th><th>Billable</th><th>Status</th><th>Actions</th></tr></thead><tbody>'+
    list.map(function(n){
      return '<tr>'+
        '<td style="font-size:12px">'+(n.date||'')+'</td>'+
        '<td style="font-weight:600">'+_cmClientName(n.clientId)+'</td>'+
        '<td style="font-size:12px">'+_cmWorkerName(n.workerId)+'</td>'+
        '<td style="font-size:11px">'+(n.contactType||'—')+'</td>'+
        '<td>'+(n.billable?'<span class="badge b-green">Yes</span>':'<span class="badge b-gray">No</span>')+'</td>'+
        '<td>'+_cmStatusBadge(n.supervisorStatus||'Pending')+'</td>'+
        '<td><div class="btn-group" style="gap:3px">'+
        '<button class="btn-icon sm" onclick="viewCMEncounter(\''+n.id+'\')" title="View"><i data-lucide="eye" class="lci" style="width:12px;height:12px"></i></button>'+
        (n.supervisorStatus!=='Approved'?'<button class="btn-icon sm" onclick="approveCMEncounter(\''+n.id+'\')" title="Approve" style="color:var(--green)"><i data-lucide="check-circle" class="lci" style="width:12px;height:12px"></i></button>':'')+
        (n.supervisorStatus!=='Returned'?'<button class="btn-icon sm" onclick="returnCMEncounter(\''+n.id+'\')" title="Return for Correction" style="color:var(--red)"><i data-lucide="undo-2" class="lci" style="width:12px;height:12px"></i></button>':'')+
        '</div></td></tr>';
    }).join('')+
    '</tbody></table></div>';
  setTimeout(_renderLucideIcons, 20);
}
function approveCMEncounter(id) {
  if (!confirm('Approve this encounter for billing?')) return;
  var d = getCMData();
  var n = (d.encounters||[]).find(function(x){return x.id===id;});
  if (n) { n.supervisorStatus='Approved'; n.approvedAt=_cmNowISO(); n.updatedAt=_cmNowISO(); }
  saveCMData(d);
  renderCMSupervisor();
  toast('Encounter approved');
}
function returnCMEncounter(id) {
  var reason = prompt('Reason for returning this note:');
  if (!reason) return;
  var d = getCMData();
  var n = (d.encounters||[]).find(function(x){return x.id===id;});
  if (n) { n.supervisorStatus='Returned'; n.returnReason=reason; n.returnedAt=_cmNowISO(); n.updatedAt=_cmNowISO(); }
  saveCMData(d);
  renderCMSupervisor();
  toast('Encounter returned for correction');
}

// ── CM: DISCHARGE ──────────────────────────────────────────────
function renderCMDischarges() {
  if (!_isCMRole()) return;
  var el = document.getElementById('cm-discharge-tbl');
  if (!el) return;
  var d = getCMData();
  var q = (document.getElementById('cm-dc-q')?.value||'').toLowerCase().trim();
  var list = (d.discharges||[]).slice().sort(function(a,b){return new Date(b.dischargeDate||'2099')-new Date(a.dischargeDate||'2099');});
  if (q) list = list.filter(function(dc){return _cmClientName(dc.clientId).toLowerCase().includes(q);});
  if (!list.length) {
    el.innerHTML = '<div class="empty"><h3>No discharges recorded</h3><button class="btn btn-primary btn-sm" onclick="openCMDischargeModal()">+ New Discharge</button></div>';
    return;
  }
  el.innerHTML =
    '<div class="tbl-wrap"><table><thead><tr><th>Client</th><th>Discharge Date</th><th>Reason</th><th>Goals Met</th><th>Supervisor</th><th></th></tr></thead><tbody>'+
    list.map(function(dc){
      return '<tr>'+
        '<td style="font-weight:600">'+_cmClientName(dc.clientId)+'</td>'+
        '<td style="font-size:12px">'+(dc.dischargeDate||'')+'</td>'+
        '<td style="font-size:12px">'+(dc.reason||'')+'</td>'+
        '<td>'+(dc.goalsAchieved?'<span class="badge b-green">'+dc.goalsAchieved+'</span>':'—')+'</td>'+
        '<td>'+(dc.supervisorApproved?'<span class="badge b-green">Approved</span>':'<span class="badge b-amber">Pending</span>')+'</td>'+
        '<td><div class="btn-group" style="gap:3px">'+
        '<button class="btn-icon sm" onclick="viewCMDischarge(\''+dc.id+'\')" title="View"><i data-lucide="eye" class="lci" style="width:12px;height:12px"></i></button>'+
        '<button class="btn-icon sm" onclick="editCMDischarge(\''+dc.id+'\')" title="Edit"><i data-lucide="pencil" class="lci" style="width:12px;height:12px"></i></button>'+
        '<button class="btn-icon sm danger" onclick="delCMDischarge(\''+dc.id+'\')" title="Delete"><i data-lucide="trash-2" class="lci" style="width:12px;height:12px"></i></button>'+
        '</div></td></tr>';
    }).join('')+
    '</tbody></table></div>';
  setTimeout(_renderLucideIcons, 20);
}
function openCMDischargeModal(editId) {
  var d = getCMData();
  var dc = editId ? (d.discharges||[]).find(function(x){return x.id===editId;}) : {};
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
  overlay.onclick = function(e){if(e.target===overlay)overlay.remove();};
  overlay.innerHTML =
    '<div style="background:var(--bg2);border-radius:12px;width:100%;max-width:540px;box-shadow:0 20px 60px rgba(0,0,0,.3)">'+
    '<div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center">'+
    '<div><div style="font-size:16px;font-weight:700">'+(editId?'Edit Discharge':'New Discharge')+'</div></div>'+
    '<button class="btn btn-ghost btn-sm" onclick="this.closest(\'[data-cm]\').remove()">&times;</button></div>'+
    '<div style="padding:16px 20px">'+
    '<div class="fg g2"><div class="field"><label>Client</label><select id="cmd-client">'+_cmClientOpts()+'</select></div>'+
    '<div class="field"><label>Discharge Date</label><input id="cmd-date" type="date" value="'+(dc.dischargeDate||_cmDateStr(new Date()))+'"></div></div>'+
    '<div class="field"><label>Reason for Discharge</label><select id="cmd-reason"><option value="Goals Achieved"'+(dc.reason==='Goals Achieved'?' selected':'')+'>Goals Achieved</option><option value="Transferred"'+(dc.reason==='Transferred'?' selected':'')+'>Transferred</option><option value="Moved"'+(dc.reason==='Moved'?' selected':'')+'>Moved</option><option value="Client Request"'+(dc.reason==='Client Request'?' selected':'')+'>Client Request</option><option value="Lost Contact"'+(dc.reason==='Lost Contact'?' selected':'')+'>Lost Contact</option><option value="Deceased"'+(dc.reason==='Deceased'?' selected':'')+'>Deceased</option><option value="Other"'+(dc.reason==='Other'?' selected':'')+'>Other</option></select></div>'+
    '<div class="fg g2"><div class="field"><label>Goals Achieved</label><input id="cmd-ga" value="'+(dc.goalsAchieved||'')+'" placeholder="e.g. 3 of 5" style="width:100%;padding:8px;border:1px solid var(--border2);border-radius:6px"></div>'+
    '<div class="field"><label>Goals Not Achieved</label><input id="cmd-gna" value="'+(dc.goalsNotAchieved||'')+'" placeholder="e.g. 2 of 5" style="width:100%;padding:8px;border:1px solid var(--border2);border-radius:6px"></div></div>'+
    '<div class="field"><label>Referrals Provided at Discharge</label><textarea id="cmd-referrals" style="width:100%;min-height:50px;padding:8px;border:1px solid var(--border2);border-radius:6px;font-size:12px">'+(dc.referralsProvided||'')+'</textarea></div>'+
    '<div class="field"><label>Continuity of Care Plan</label><textarea id="cmd-continuity" style="width:100%;min-height:50px;padding:8px;border:1px solid var(--border2);border-radius:6px;font-size:12px">'+(dc.continuityPlan||'')+'</textarea></div>'+
    '<div class="field"><label>Final Summary</label><textarea id="cmd-summary" style="width:100%;min-height:60px;padding:8px;border:1px solid var(--border2);border-radius:6px;font-size:12px">'+(dc.finalSummary||'')+'</textarea></div>'+
    '<div class="field"><label><input type="checkbox" id="cmd-sup" '+(dc.supervisorApproved?'checked':'')+'> Supervisor approved this discharge</label></div>'+
    '</div>'+
    '<div style="padding:14px 20px;border-top:1px solid var(--border);display:flex;gap:8px;justify-content:flex-end">'+
    '<button class="btn" onclick="this.closest(\'[data-cm]\').remove()">Cancel</button>'+
    '<button class="btn btn-primary" onclick="saveCMDischarge(\''+(editId||'')+'\')">Save</button></div></div>';
  overlay.setAttribute('data-cm','1');
  document.body.appendChild(overlay);
  if (editId && dc.clientId) { var sel=document.getElementById('cmd-client'); if(sel) sel.value=dc.clientId; }
}
function saveCMDischarge(id) {
  var d = getCMData();
  var clientId = document.getElementById('cmd-client')?.value;
  if (!clientId) { toast('Select a client','warn'); return; }
  var obj = {
    clientId: clientId,
    dischargeDate: document.getElementById('cmd-date')?.value||'',
    reason: document.getElementById('cmd-reason')?.value||'',
    goalsAchieved: document.getElementById('cmd-ga')?.value||'',
    goalsNotAchieved: document.getElementById('cmd-gna')?.value||'',
    referralsProvided: document.getElementById('cmd-referrals')?.value||'',
    continuityPlan: document.getElementById('cmd-continuity')?.value||'',
    finalSummary: document.getElementById('cmd-summary')?.value||'',
    supervisorApproved: !!document.getElementById('cmd-sup')?.checked,
    updatedAt: _cmNowISO()
  };
  if (!d.discharges) d.discharges = [];
  if (id) {
    var idx = d.discharges.findIndex(function(x){return x.id===id;});
    if (idx>=0) Object.assign(d.discharges[idx], obj);
  } else {
    obj.id = _cmId(); obj.createdAt = _cmNowISO();
    d.discharges.push(obj);
  }
  // Mark client as discharged
  var cli = d.clients.find(function(c){return c.id===clientId;});
  if (cli) cli.status = 'Discharged';
  saveCMData(d);
  document.querySelectorAll('[data-cm]').forEach(function(o){o.remove();});
  renderCMDischarges();
  toast('Discharge recorded');
}
function viewCMDischarge(id) {
  var d = getCMData();
  var dc = (d.discharges||[]).find(function(x){return x.id===id;});
  if (!dc) return;
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:9999;display:flex;align-items:center;justify-content:center;padding:16px';
  overlay.onclick = function(e){if(e.target===overlay)overlay.remove();};
  overlay.innerHTML =
    '<div style="background:var(--bg2);border-radius:12px;width:100%;max-width:500px;max-height:80vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.3)">'+
    '<div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:center">'+
    '<div><div style="font-size:16px;font-weight:700">Discharge: '+_cmClientName(dc.clientId)+'</div></div>'+
    '<button class="btn btn-ghost btn-sm" onclick="this.closest(\'[data-cm]\').remove()">&times;</button></div>'+
    '<div style="padding:16px 20px;font-size:12px">'+
    '<div><strong>Date:</strong> '+dc.dischargeDate+'</div>'+
    '<div><strong>Reason:</strong> '+dc.reason+'</div>'+
    '<div><strong>Goals Achieved:</strong> '+dc.goalsAchieved+'</div>'+
    '<div><strong>Goals Not Achieved:</strong> '+dc.goalsNotAchieved+'</div>'+
    (dc.referralsProvided?'<div style="margin-top:8px"><strong>Referrals:</strong><p>'+dc.referralsProvided+'</p></div>':'')+
    (dc.continuityPlan?'<div style="margin-top:8px"><strong>Continuity Plan:</strong><p>'+dc.continuityPlan+'</p></div>':'')+
    (dc.finalSummary?'<div style="margin-top:8px"><strong>Final Summary:</strong><p style="white-space:pre-wrap">'+dc.finalSummary+'</p></div>':'')+
    '<div style="margin-top:10px">'+(dc.supervisorApproved?'<span class="badge b-green">Supervisor Approved</span>':'<span class="badge b-amber">Pending Supervisor</span>')+'</div>'+
    '</div></div>';
  document.body.appendChild(overlay);
}
function editCMDischarge(id) { openCMDischargeModal(id); }
function delCMDischarge(id) {
  if (!confirm('Delete this discharge record?')) return;
  var d = getCMData();
  d.discharges = (d.discharges||[]).filter(function(x){return x.id!==id;});
  saveCMData(d);
  renderCMDischarges();
  toast('Discharge deleted');
}

// ── CM: PATIENT SUMMARY ────────────────────────────────────────
function renderCMPatientSummary() {
  if (!_isCMRole()) return;
  var el = document.getElementById('cm-patient-summary-content');
  if (!el) return;
  var clientId = window._cmSummaryClientId;
  if (!clientId) { el.innerHTML = '<div class="empty"><p style="color:var(--text3)">Select a client from the Clients page to view their CM summary.</p></div>'; return; }
  var d = getCMData();
  var c = d.clients.find(function(x){return x.id===clientId;});
  if (!c) { el.innerHTML = '<div class="empty"><h3>Client not found</h3></div>'; return; }
  var enc = (d.encounters||[]).filter(function(n){return n.clientId===clientId;}).sort(function(a,b){return new Date(b.date)-new Date(a.date);});
  var plans = (d.plans||[]).filter(function(p){return p.clientId===clientId;});
  var tasks = (d.tasks||[]).filter(function(t){return t.clientId===clientId && t.status==='Open';});
  var auths = (d.authorizations||[]).filter(function(a){return a.clientId===clientId;});
  var referrals = (d.communityReferrals||[]).filter(function(r){return r.clientId===clientId;});
  var assessments = (d.assessments||[]).filter(function(a){return a.clientId===clientId;});
  var elig = (d.eligibility||[]).filter(function(e){return e.clientId===clientId;});
  var lastContact = enc.length ? enc[0].date : '—';
  var nextFup = tasks.length ? tasks[0].dueDate||'—' : '—';
  var activePlan = plans.find(function(p){return p.status==='Active';});
  var activeAuth = auths.find(function(a){return a.status==='Active';});
  var billingIssues = [];
  if (activeAuth && activeAuth.endDate && new Date(activeAuth.endDate) < new Date()) billingIssues.push('Authorization expired');
  if (elig.length && !elig[0].tcmEligible) billingIssues.push('Eligibility inactive');
  el.innerHTML =
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">'+
    '<div class="card"><div style="font-weight:700;font-size:14px;padding:12px 16px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between">'+
    '<span>'+c.last+', '+c.first+'</span><span class="badge b-green">'+c.status+'</span></div>'+
    '<div style="padding:12px 16px;font-size:12px">'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">'+
    '<div><strong>Medicaid ID:</strong> '+(c.medicaidId||'—')+'</div>'+
    '<div><strong>DOB:</strong> '+(c.dob||'—')+'</div>'+
    '<div><strong>Phone:</strong> '+(c.phone||'—')+'</div>'+
    '<div><strong>Worker:</strong> '+_cmWorkerName(c.workerId)+'</div>'+
    '<div><strong>Auth:</strong> '+(c.authStart||'—')+' → '+(c.authEnd||'—')+'</div>'+
    '<div><strong>Auth Units:</strong> '+(c.authUnits||0)+'</div>'+
    '</div></div></div>'+
    '<div class="card"><div style="font-weight:700;font-size:14px;padding:12px 16px;border-bottom:1px solid var(--border)">Case Overview</div>'+
    '<div style="padding:12px 16px;font-size:12px">'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:6px">'+
    '<div><strong>Last Contact:</strong> '+lastContact+'</div>'+
    '<div><strong>Next Follow-Up:</strong> '+nextFup+'</div>'+
    '<div><strong>Open Tasks:</strong> '+tasks.length+'</div>'+
    '<div><strong>Encounters:</strong> '+enc.length+'</div>'+
    '<div><strong>Active Plan:</strong> '+(activePlan?'<span class="badge b-green">Yes</span>':'<span class="badge b-gray">No</span>')+'</div>'+
    '<div><strong>Active Auth:</strong> '+(activeAuth?'<span class="badge b-green">Yes</span>':'<span class="badge b-gray">No</span>')+'</div>'+
    '</div>'+
    (billingIssues.length?'<div style="margin-top:8px;padding:6px;background:var(--bg3);border-radius:6px;color:var(--red)"><strong>Alerts:</strong> '+billingIssues.join('; ')+'</div>':'')+
    '</div></div>'+
    '<div class="card" style="grid-column:1/-1"><div style="font-weight:700;font-size:13px;padding:12px 16px;border-bottom:1px solid var(--border)">Recent Encounters</div>'+
    '<div style="padding:12px 16px;max-height:180px;overflow-y:auto">'+
    (enc.length?enc.slice(0,5).map(function(n){
      var bi = _cmBillingHolds(n, d);
      return '<div style="display:flex;justify-content:space-between;padding:4px 0;border-bottom:1px solid var(--border);font-size:12px"><span>'+n.date+' · '+n.contactType+'</span><span>'+(bi.length?'<span class="badge b-red">Hold</span>':'<span class="badge b-green">Clear</span>')+' '+_cmStatusBadge(n.supervisorStatus||'Pending')+'</span></div>';
    }).join(''):'<div style="color:var(--text3);font-size:12px">No encounters recorded.</div>')+
    '</div></div>'+
    '<div class="card"><div style="font-weight:700;font-size:13px;padding:12px 16px;border-bottom:1px solid var(--border)">Open Tasks</div><div style="padding:12px 16px;max-height:160px;overflow-y:auto">'+
    (tasks.length?tasks.map(function(t){return '<div style="font-size:12px;padding:4px 0">• '+(t.title||'')+' — due '+(t.dueDate||'—')+'</div>';}).join(''):'<div style="color:var(--text3);font-size:12px">No open tasks.</div>')+
    '</div></div>'+
    '<div class="card"><div style="font-weight:700;font-size:13px;padding:12px 16px;border-bottom:1px solid var(--border)">Active Referrals</div><div style="padding:12px 16px;max-height:160px;overflow-y:auto">'+
    (referrals.length?referrals.map(function(r){return '<div style="font-size:12px;padding:4px 0">• '+r.referralType+' → '+(r.provider||'')+' ('+r.status+')</div>';}).join(''):'<div style="color:var(--text3);font-size:12px">No active referrals.</div>')+
    '</div></div></div>';
}
function openCMPatientSummary(clientId) {
  window._cmSummaryClientId = clientId;
  go('cm-patient-summary');
}

// ── CM: ENHANCED DASHBOARD ─────────────────────────────────────
function renderCMDashboard() {
  if (!_isCMRole()) { go('dashboard'); return; }
  var el = document.getElementById('cm-dash-content');
  if (!el) return;
  var d = getCMData();
  var s = getSession();
  var isSup = s.role==='Super Admin' || _cmIsSupervisor();
  var activeClients = d.clients.filter(function(c){return c.status==='Active';});
  var activeWorkers = d.workers.filter(function(w){return w.status!=='Inactive';});
  var now = new Date();
  // Smart alerts
  var expiringAuths = (d.authorizations||[]).filter(function(a){return a.status==='Active' && a.endDate && new Date(a.endDate) < new Date(now.getTime()+30*86400000) && new Date(a.endDate) >= now;});
  var expiredAuths = (d.authorizations||[]).filter(function(a){return a.status==='Active' && a.endDate && new Date(a.endDate) < now;});
  var expiringPlans = d.plans.filter(function(p){return p.status==='Active' && p.nextReview && new Date(p.nextReview) < new Date(now.getTime()+30*86400000);});
  var pendingNotes = (d.encounters||[]).filter(function(n){return n.supervisorStatus==='Pending'||!n.supervisorStatus;});
  var overdueTasks = (d.tasks||[]).filter(function(t){return t.status==='Open' && t.dueDate && new Date(t.dueDate) < now;});
  var billingHolds = (d.encounters||[]).filter(function(n){return n.billable && _cmBillingHolds(n,d).length > 0;});
  var unsignedNotes = (d.encounters||[]).filter(function(n){return n.signatureStatus!=='Signed' && n.billable;});
  var alerts = [];
  if (expiringAuths.length) alerts.push({type:'warn', text:expiringAuths.length+' authorization(s) expiring within 30 days'});
  if (expiredAuths.length) alerts.push({type:'err', text:expiredAuths.length+' authorization(s) expired — billing blocked'});
  if (expiringPlans.length) alerts.push({type:'warn', text:expiringPlans.length+' care plan(s) due for 90-day review'});
  if (pendingNotes.length) alerts.push({type:'info', text:pendingNotes.length+' encounter(s) pending supervisor review'});
  if (overdueTasks.length) alerts.push({type:'err', text:overdueTasks.length+' overdue task(s) — needs attention'});
  if (billingHolds.length) alerts.push({type:'warn', text:billingHolds.length+' encounter(s) on billing hold'});
  if (unsignedNotes.length) alerts.push({type:'info', text:unsignedNotes.length+' unsigned billable encounter(s)'});
  var alertHtml = alerts.length ?
    '<div style="display:flex;flex-direction:column;gap:6px;margin-bottom:14px">'+
    alerts.map(function(a){
      var bg = a.type==='err'?'var(--red)':a.type==='warn'?'var(--amber)':'var(--brand)';
      return '<div style="padding:10px 14px;border-radius:8px;background:'+bg+'15;border-left:3px solid '+bg+';font-size:12px;color:var(--text);display:flex;align-items:center;gap:8px">'+
        '<i data-lucide="'+(a.type==='err'?'alert-triangle':a.type==='warn'?'alert-circle':'info')+'" class="lci" style="width:14px;height:14px;color:'+bg+';flex-shrink:0"></i> '+a.text+'</div>';
    }).join('')+'</div>' : '';
  var thisMonth = now.getMonth();
  var thisYear = now.getFullYear();
  var monthEncounters = (d.encounters||[]).filter(function(n){
    var nd = new Date(n.date); return nd.getMonth()===thisMonth && nd.getFullYear()===thisYear;
  });
  var billableThisMonth = monthEncounters.filter(function(n){return n.billable;}).length;
  var totalBilled = (d.billing||[]).reduce(function(s,b){return s+(b.total||0);},0);
  var billingReady = (d.billing||[]).filter(function(b){return b.status==='Ready';}).length;
  el.innerHTML =
    // Quick Actions
    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px">'+
    '<button class="btn btn-sm" onclick="openCMEncounterModal()" style="display:flex;align-items:center;gap:4px"><i data-lucide="notebook-pen" class="lci" style="width:13px;height:13px"></i> New Note</button>'+
    '<button class="btn btn-sm" onclick="openCMIntakeModal()" style="display:flex;align-items:center;gap:4px"><i data-lucide="user-plus" class="lci" style="width:13px;height:13px"></i> New Referral</button>'+
    '<button class="btn btn-sm" onclick="openCMPlanModal()" style="display:flex;align-items:center;gap:4px"><i data-lucide="clipboard-list" class="lci" style="width:13px;height:13px"></i> New Care Plan</button>'+
    '<button class="btn btn-sm" onclick="openCMTaskModal()" style="display:flex;align-items:center;gap:4px"><i data-lucide="list-checks" class="lci" style="width:13px;height:13px"></i> Add Follow-Up</button>'+
    '<button class="btn btn-sm" onclick="openCMAuthModal()" style="display:flex;align-items:center;gap:4px"><i data-lucide="file-check" class="lci" style="width:13px;height:13px"></i> Add Authorization</button>'+
    '</div>'+
    // Alerts
    alertHtml+
    // Stats
    '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:16px">'+
    '<div class="card" style="padding:14px;text-align:center"><div style="font-size:24px;font-weight:800;color:var(--brand)">'+activeClients.length+'</div><div style="font-size:10px;color:var(--text3);margin-top:2px">Active Clients</div></div>'+
    '<div class="card" style="padding:14px;text-align:center"><div style="font-size:24px;font-weight:800;color:var(--green)">'+activeWorkers.length+'</div><div style="font-size:10px;color:var(--text3);margin-top:2px">Active Workers</div></div>'+
    '<div class="card" style="padding:14px;text-align:center"><div style="font-size:24px;font-weight:800;color:'+(pendingNotes.length?'var(--amber)':'var(--text)')+'">'+pendingNotes.length+'</div><div style="font-size:10px;color:var(--text3);margin-top:2px">Pending Review</div></div>'+
    '<div class="card" style="padding:14px;text-align:center"><div style="font-size:24px;font-weight:800;color:'+(expiringAuths.length?'var(--red)':'var(--text)')+'">'+expiringAuths.length+'</div><div style="font-size:10px;color:var(--text3);margin-top:2px">Expiring Auths</div></div>'+
    '<div class="card" style="padding:14px;text-align:center"><div style="font-size:24px;font-weight:800;color:'+(billingReady?'var(--brand)':'var(--text)')+'">'+billingReady+'</div><div style="font-size:10px;color:var(--text3);margin-top:2px">Billing Ready</div></div>'+
    '</div>'+
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">'+
    '<div class="card"><div style="font-weight:700;font-size:13px;padding:10px 14px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between"><span>Recent Notes</span><span style="font-weight:400;font-size:11px;color:var(--text3)">This month: '+monthEncounters.length+' ('+billableThisMonth+' billable)</span></div>'+
    '<div style="padding:10px 14px;max-height:200px;overflow-y:auto">'+
    (monthEncounters.length?monthEncounters.slice(0,8).map(function(n){
      return '<div style="display:flex;justify-content:space-between;font-size:12px;padding:5px 0;border-bottom:1px solid var(--border)"><span><strong>'+_cmClientName(n.clientId)+'</strong> — '+n.contactType+'</span><span>'+(n.billable?'<span class="badge b-green">$</span>':'')+' '+_cmStatusBadge(n.supervisorStatus||'Pending')+'</span></div>';
    }).join(''):'<div style="font-size:12px;color:var(--text3)">No encounters this month.</div>')+
    '</div></div>'+
    '<div class="card"><div style="font-weight:700;font-size:13px;padding:10px 14px;border-bottom:1px solid var(--border)">Overdue Tasks</div>'+
    '<div style="padding:10px 14px;max-height:200px;overflow-y:auto">'+
    (overdueTasks.length?overdueTasks.slice(0,10).map(function(t){
      return '<div style="font-size:12px;padding:5px 0;border-bottom:1px solid var(--border);display:flex;justify-content:space-between"><span>• '+(t.title||'')+'</span><span style="color:var(--red)">'+(t.dueDate||'')+'</span></div>';
    }).join(''):'<div style="font-size:12px;color:var(--text3)">No overdue tasks. ?</div>')+
    '</div></div>'+
    '</div>'+
    // Caseload + Productivity
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px">'+
    '<div class="card"><div style="font-weight:700;font-size:13px;padding:10px 14px;border-bottom:1px solid var(--border)">Caseload by Worker</div>'+
    '<div style="padding:10px 14px;max-height:180px;overflow-y:auto">'+
    (activeWorkers.length?activeWorkers.map(function(w){
      var cnt = activeClients.filter(function(c){return c.workerId===w.id;}).length;
      var cap = w.capacity||20;
      var pct = Math.round(cnt/cap*100);
      return '<div style="font-size:12px;padding:4px 0;display:flex;justify-content:space-between;align-items:center"><span>'+w.first+' '+w.last+'</span>'+
        '<span style="display:flex;align-items:center;gap:6px"><div style="background:var(--bg3);border-radius:8px;height:5px;width:50px;overflow:hidden"><div style="background:'+(pct>80?'var(--red)':pct>50?'var(--amber)':'var(--green)')+';height:5px;width:'+Math.min(pct,100)+'%;border-radius:8px"></div></div> '+cnt+'/'+cap+'</span></div>';
    }).join(''):'<div style="font-size:12px;color:var(--text3)">No workers assigned.</div>')+
    '</div></div>'+
    '<div class="card"><div style="font-weight:700;font-size:13px;padding:10px 14px;border-bottom:1px solid var(--border)">Productivity Summary</div>'+
    '<div style="padding:10px 14px;font-size:12px">'+
    '<div style="display:flex;justify-content:space-between;padding:4px 0"><span>Total Billed</span><strong>'+_cmFmtMoney(totalBilled)+'</strong></div>'+
    '<div style="display:flex;justify-content:space-between;padding:4px 0"><span>Encounters This Month</span><strong>'+monthEncounters.length+'</strong></div>'+
    '<div style="display:flex;justify-content:space-between;padding:4px 0"><span>Billable This Month</span><strong>'+billableThisMonth+'</strong></div>'+
    '<div style="display:flex;justify-content:space-between;padding:4px 0"><span>Pending Supervisor</span><strong>'+(pendingNotes.length)+'</strong></div>'+
    '<div style="display:flex;justify-content:space-between;padding:4px 0"><span>On Billing Hold</span><strong>'+(billingHolds.length)+'</strong></div>'+
    '<div style="display:flex;justify-content:space-between;padding:4px 0"><span>Overdue Tasks</span><strong>'+(overdueTasks.length)+'</strong></div>'+
    '</div></div></div>';
  setTimeout(_renderLucideIcons, 20);
}
function _cmIsSupervisor() {
  var s = getSession(); if (!s) return false;
  var d = getCMData();
  return d.workers.some(function(w){return w.email===s.email;});
}

document.addEventListener("DOMContentLoaded", async function() {
  // Hydrate the cache from IndexedDB FIRST — before applyTheme/getDB/render —
  // so the synchronous _loadCache() mirror is ready. One-time-migrates the old
  // localStorage cache and frees that space. Must complete before first paint.
  await _idbBootLoad();
  applyTheme();

  const waitForFirebase = (retries = 30) => new Promise(resolve => {
    if (typeof firebase !== 'undefined') { resolve(); return; }
    if (retries <= 0) { resolve(); return; }
    setTimeout(() => waitForFirebase(retries - 1).then(resolve), 150);
  });

  await waitForFirebase();
  initFirebase();

  function _afterLoad() {
    var db2 = getDB(); var s = getSession(); if (!s) return;
    if (typeof _resetIdleTimer === 'function') _resetIdleTimer();
    if (db2.providers && db2.providers.length) {
      var savedId = s.activeBillingProviderId;
      var vp = (savedId && db2.providers.find(function(p){ return p.id===savedId; })) || db2.providers[0];
      activeProviderId = vp.id;
      s.activeBillingProviderId = activeProviderId;
      setSession(s);
      rebuildProvSel();
    }
    updateAdminUI();
    updateBadges();
    setTimeout(function(){ if(typeof applyActiveSpecialty==='function') applyActiveSpecialty(); }, 600);
    // Re-populate user chip billing provider after data loads
    try {
      var _provEl2 = document.getElementById('tn-user-prov');
      if (_provEl2 && activeProviderId) {
        var _db3 = getDB();
        var _prov3 = (_db3.providers||[]).find(function(p){ return p.id===activeProviderId; });
        if (_prov3) _provEl2.textContent = _prov3.name||'';
      }
    } catch(e) {}

    // Re-render current page or dashboard with fresh data
    try {
      var _curActive = document.querySelector('.section.active');
      if (!_curActive || _curActive.id === 'sec-dashboard') {
        go('dashboard');
      } else {
        var _curPage = _curActive.id.replace('sec-', '');
        var _renderFns = ({dashboard:renderDashboard,claims:renderClaims,patients:renderPatients,services:renderServices,facilities:renderFacilities,rendering:renderRendering,referring:renderReferring,eob:renderEOBPage,insurances:renderInsurances,validate:renderValidation,export:renderExportSummary,reports:renderReports,'admin-providers':renderAdminProviders,servicegroups:renderServiceGroups,account:renderAccountPage,appointments:renderAppointments,notes:renderNotes,bills:renderBills,'provider-info':renderProviderInfo,'cm-dashboard':renderCMDashboard,'cm-intake':renderCMIntake,'cm-clients':renderCMClients,'cm-workers':renderCMWorkers,'cm-assessments':renderCMAssessments,'cm-plans':renderCMPlans,'cm-encounters':renderCMEncounters,'cm-tasks':renderCMTasks,'cm-authorizations':renderCMAuths,'cm-referrals':renderCMCommReferrals,'cm-supervisor':renderCMSupervisor,'cm-billing':renderCMBilling,'cm-reports':renderCMReports,'cm-discharge':renderCMDischarges,'intake-center':renderIntakeCenter,'intake-clients':renderIntakeClients,'intake-forms':renderIntakeConsentForms,'intake-eval':renderIntakeEvaluation})[_curPage];
        if (_renderFns) { _renderFns(); updateBadges(); }
      }
    } catch(e) { go('dashboard'); }
  }

  // ── Check landing page pending login ──────────────────────────
  var pendingLogin = localStorage.getItem('cdc_pending_login');
  if (pendingLogin === '1') {
    localStorage.removeItem('cdc_pending_login');

    var fbUser = await new Promise(function(resolve) {
      var unsub = _auth.onAuthStateChanged(function(user) { unsub(); resolve(user); });
      setTimeout(function() { resolve(null); }, 3000);
    });

    if (fbUser) {
      if (!getSession()) {
        setSession({
          id: fbUser.uid,
          email: fbUser.email,
          name: fbUser.displayName || fbUser.email.split('@')[0] || 'Admin',
          role: 'Super Admin',
          activeBillingProviderId: null
        });
      }
      var sess = getSession();
      window._sessionVerified = true;
      sessionStorage.setItem('cdc_verified', 'yes');
      showApp(sess.name || sess.email);
      Promise.resolve(loadFromFirestoreWhenReady()).then(_afterLoad).catch(function(){ go('dashboard'); });
      return;
    }
  }

  // F5 safe: restore session from localStorage if available
  var existSess = getSession();
  if (existSess) {
    // Re-stamp verified token in case sessionStorage lost it
    sessionStorage.setItem('cdc_verified', 'yes');
    showApp(existSess.name || existSess.email);
    Promise.resolve(loadFromFirestoreWhenReady()).then(_afterLoad).catch(function(){ go('dashboard'); });
    return;
  }
  checkVerifyToken();
  checkIntakeToken();
  if (!window.location.search.startsWith('?verify=') && !window.location.search.startsWith('?intake=') && !window.location.search.startsWith('?demographics=')) renderLoginScreen();
});

// ── Send Invoice by Email ─────────────────────────────────────────
function sendInvoiceEmail(inv) {
  try {
    const db = getInvDB();
    const iss = db.invoicingIssuers.find(x => x.id === inv.issuerId) || {};
    const cli = resolveInvClient(inv.clientId, db) || {};
    const sess = getSession() || {};
    const senderEmail = sess.email || iss.email || '';
    const fromName = iss.name || 'ClaimDataCare Billing';

    const toEmail = cli.email || cli.billingEmail || '';
    const amount = '$' + fmtMoney(parseFloat(inv.billingFee||inv.total||0));
    const subject = 'Invoice ' + (inv.number||'') + ' — ' + (inv.month||'') + ' — ' + amount;

    if (!toEmail) {
      toast('No email on file for this client. Add an email address first.','err');
      return;
    }

    var msg = 'Send Invoice ' + (inv.number||'') + ' to ' + (cli.name||'Client') + ' <' + toEmail + '>';
    if (senderEmail) msg += '\n\nCC: ' + senderEmail;
    msg += '\n\nThe PDF will be downloaded for you to attach.';
    if (!confirm(msg)) return;

    const body = [
      'Dear ' + (cli.name||'Client') + ',',
      '',
      'Please find attached the invoice for ' + (inv.month||'the current billing period') + '.',
      '',
      'Invoice #: ' + (inv.number||''),
      'Period: ' + (inv.month||''),
      'Amount: ' + amount,
      'Due Date: ' + (inv.due||'Upon receipt'),
      '',
      'Payment Instructions:',
      iss.zelleMode ? 'Zelle: ' + (iss.zelleMode==='email' ? iss.email : fmtPhone(iss.phone)) : '',
      'Paper checks accepted at ' + (iss.addr1 || 'the address on file') + '.',
      '',
      'Please remit payment by the due date. For questions, contact ' + (iss.email||'our billing department') + '.',
      '',
      'Thank you for your partnership,',
      fromName
    ].filter(Boolean).join('\n');

    var mailtoUrl = 'mailto:' + toEmail + '?subject=' + encodeURIComponent(subject) + '&body=' + encodeURIComponent(body);
    if (senderEmail) mailtoUrl += '&cc=' + encodeURIComponent(senderEmail);

    try {
      const doc = _buildInvoicePDF(inv.id);
      if (doc) doc.save('Invoice_' + (inv.number||'draft') + '.pdf');
    } catch(pdfErr) { console.warn('PDF generation failed:', pdfErr); }

    var mailWin = window.open(mailtoUrl, '_blank', 'noopener,noreferrer');
    if (!mailWin || mailWin.closed) window.location.href = mailtoUrl;

    setDB(function(db) {
      var idx = db.invoices.findIndex(function(x){ return x.id === inv.id; });
      if (idx >= 0 && db.invoices[idx].status === 'Draft') db.invoices[idx].status = 'Sent';
    });
    renderInvoicesList();

    toast('Invoice PDF downloaded — email ready to send to ' + toEmail + (senderEmail ? ' (CC: ' + senderEmail + ')' : ''), 'ok');
  } catch(e) {
    toast('Failed to send invoice: ' + (e.message||'unknown error'), 'err');
    console.error('sendInvoiceEmail error:', e);
  }
}


