// Synchronous local cache (for all sync callers)
// Merge two arrays of records by id — keeps the record with the higher updatedAt.
// Records present in remote but not local are added (multi-device additions).
// Records deleted locally via _fsDeleteDoc are already gone from Firestore.
function _mergeByUpdatedAt(local, remote) {
  var map = {};
  (local||[]).forEach(function(r){ if(r&&r.id) map[r.id]=r; });
  (remote||[]).forEach(function(r){
    if(!r||!r.id) return;
    var existing = map[r.id];
    if(!existing) { map[r.id]=r; return; } // new record from another device
    var remoteTs = r.updatedAt||r.createdAt||0;
    var localTs  = existing.updatedAt||existing.createdAt||0;
    if(remoteTs>=localTs) map[r.id]=r; // Firestore wins on tie or newer
  });
  return Object.values(map);
}

function getDB() {
if (_localDB) { return _localDB; }
var _cached = _loadCache();
if (_cached) {
_localDB = _mergeEmpty(_cached);
console.log('[CDC] getDB: loaded from cache | providers='+(_localDB.providers||[]).length+' patients='+(_localDB.patients||[]).length+' claims='+(_localDB.claims||[]).length);
} else {
_localDB = { providers:[], facilities:[], rendering:[], referring:[], patients:[], claims:[], services:[], serviceGroups:[], appointments:[], notes:[], claimLogs:{}, claimEOB:{}, invoicingIssuers:[], invoicingClients:[], invoices:[], insurances:[], intakeClients:[], intakeForms:[], intakeSubmissions:[], evaluations:[] };
console.log('[CDC] getDB: NO cache found, created empty DB');
}
return _localDB;
}

// ????????????????????????????????????????????????????????????????????????????
// FIRESTORE PERSISTENCE LAYER v2
// Architecture: individual documents in typed collections (not one monolithic doc)
//
// Collections:
// providers/{id} — billing providers
// patients/{id} — patients (each own doc)
// claims/{id} — claims (each own doc)
// facilities/{id} — facilities
// rendering/{id} — rendering providers
// referring/{id} — referring providers
// services/{id} — CPT services
// serviceGroups/{id} — service groups
// appointments/{id} — appointments
// notes/{id} — encounter notes
// claimLogs/{claimId} — claim log entries
// claimEOB/{claimId} — EOB records
// invoicingIssuers/{id} — billing entities
// invoicingClients/{id} — clients
// invoices/{id} — invoices
// meta/config — app config (apiKey, etc.)
// meta/users — users list
//
// All writes go to Firestore first. localStorage is a read-time cache only.
// ????????????????????????????????????????????????????????????????????????????

// ?? Constants ???????????????????????????????????????????????????????????????
const BATCH_SIZE = 400; // Firestore batch limit is 500 writes
const CACHE_KEY = 'cdc_cache_v2';
// ?? Helpers ??????????????????????????????????????????????????????????????????

// Write an array of objects to a Firestore collection using batched writes
async function _fsWriteCollection(collName, items) {
  if (!_fbReady || !_db || !items?.length) return;
  try {
    for (let i = 0; i < items.length; i += BATCH_SIZE) {
      const chunk = items.slice(i, i + BATCH_SIZE);
      const batch = _db.batch();
      chunk.forEach(item => {
        if (!item.id) return;
        const safe = {};
        for (const [k, v] of Object.entries(item)) {
          if (typeof v === 'string' && v.startsWith('data:image') && v.length > 933333) {
            try {
              const canvas = document.createElement('canvas');
              const img = new Image();
              img.src = v;
              if (img.width > 0) {
                const ratio = Math.min(500/img.width, 500/img.height, 1);
                canvas.width  = Math.round(img.width  * ratio);
                canvas.height = Math.round(img.height * ratio);
                canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
                safe[k] = canvas.toDataURL('image/jpeg', 0.7);
              } else {
                safe[k] = '';
              }
            } catch(e) { safe[k] = ''; }
          } else {
            safe[k] = v;
          }
        }
        batch.set(_db.collection(collName).doc(String(item.id)), safe);
      });
      await batch.commit();
    }
  } catch(e) {
    console.warn(`Firestore write failed for ${collName}:`, e.message);
  }
}

// Read all docs from a collection
async function _fsReadCollection(collName) {
if (!_fbReady || !_db) return [];
try {
  const snap = await _db.collection(collName).get();
  return snap.docs.map(d => d.data());
} catch(e) {
  console.warn(`Firestore read failed for ${collName}:`, e.message);
  return [];
}
}

// Delete docs from a collection that are not in the current list
async function _fsSyncCollection(collName, items) {
if (!_fbReady || !_db) return;
try {
  // SAFE MERGE: only write items that changed — never delete based on local state alone.
  // Deletes are handled explicitly by _fsDeleteDoc (called when user deletes a record).
  // This prevents data loss when claims are created on another device.
  await _fsWriteCollection(collName, items);
} catch(e) {
  console.warn(`Firestore sync failed for ${collName}:`, e.message);
}
}

// Write/delete a single document
async function _fsSetDoc(collName, id, data) {
if (!_fbReady || !_db) return;
try {
  await _db.collection(collName).doc(String(id)).set(data);
} catch(e) {
  console.warn(`Firestore setDoc failed for ${collName}/${id}:`, e.message);
}
}

async function _fsDeleteDoc(collName, id) {
if (!_fbReady || !_db) return;
try {
  await _db.collection(collName).doc(String(id)).delete();
} catch(e) {
  console.warn(`Firestore deleteDoc failed for ${collName}/${id}:`, e.message);
}
}

// ?? Cache ????????????????????????????????????????????????????????????????????
// Collections excluded from the localStorage snapshot: they're audit/history
// data (one entry can be added per claim action, per ERA import, etc.) that
// isn't needed for instant page load — always live and available from
// Firestore the moment you actually open a claim's Log or EOB tab. Keeping
// them out of the local cache is the single biggest lever for staying under
// localStorage's fixed ~5-10MB-per-origin ceiling, which doesn't grow no
// matter how much free disk space the computer has.
var _CACHE_EXCLUDED_KEYS = ['claimLogs','claimEOB','eraPreviewQueue','eobUnmatched'];

// ?? IndexedDB cache layer ????????????????????????????????????????????????????
// Replaces localStorage as the primary first-paint cache. localStorage has a
// FIXED ~5-10MB per-origin ceiling that doesn't grow with free disk — that's
// what caused the "Storage Full" data loss. IndexedDB has no such practical
// limit (hundreds of MB to GB), so the full lean snapshot lives here instead.
// Firestore is still the source of truth; this is only a read-time cache.
//
// getDB()/_loadCache() are SYNCHRONOUS and called all over the app, so we keep
// a synchronous in-memory mirror (_idbCacheSnapshot) that is hydrated from
// IndexedDB once at boot (before any getDB call) and kept fresh on every save.
var _IDB_NAME = 'cdc_cache_db';
var _IDB_STORE = 'kv';
var _IDB_KEY = 'cache_v2';
var _idbDB = null;
var _idbCacheSnapshot = null;     // sync mirror returned by _loadCache()
var _idbWriteInFlight = false;
var _idbWriteDirty = false;

function _idbOpen() {
  return new Promise(function(resolve, reject){
    try {
      if (!('indexedDB' in window) || !window.indexedDB) { reject(new Error('IndexedDB not supported')); return; }
      var req = indexedDB.open(_IDB_NAME, 1);
      req.onupgradeneeded = function(e){
        var d = e.target.result;
        if (!d.objectStoreNames.contains(_IDB_STORE)) d.createObjectStore(_IDB_STORE);
      };
      req.onsuccess = function(e){ _idbDB = e.target.result; resolve(_idbDB); };
      req.onerror = function(e){ reject((e.target && e.target.error) || new Error('idb open failed')); };
    } catch(e) { reject(e); }
  });
}

function _idbGet(key) {
  return new Promise(function(resolve){
    if (!_idbDB) { resolve(null); return; }
    try {
      var tx = _idbDB.transaction(_IDB_STORE, 'readonly');
      var req = tx.objectStore(_IDB_STORE).get(key);
      req.onsuccess = function(){ resolve(req.result != null ? req.result : null); };
      req.onerror = function(){ resolve(null); };
    } catch(e) { resolve(null); }
  });
}

function _idbSet(key, val) {
  return new Promise(function(resolve, reject){
    if (!_idbDB) { reject(new Error('idb not open')); return; }
    try {
      var tx = _idbDB.transaction(_IDB_STORE, 'readwrite');
      tx.objectStore(_IDB_STORE).put(val, key);
      tx.oncomplete = function(){ resolve(true); };
      tx.onerror = function(){ reject(tx.error || new Error('idb write failed')); };
      tx.onabort = function(){ reject(tx.error || new Error('idb write aborted')); };
    } catch(e) { reject(e); }
  });
}

// Coalesced async write: if a write is already running, mark dirty and re-fire
// with the latest snapshot when it lands, so we never lose the newest state and
// never pile up overlapping transactions during bulk operations.
function _idbScheduleWrite() {
  if (_idbWriteInFlight) { _idbWriteDirty = true; return; }
  _idbWriteInFlight = true;
  _idbWriteDirty = false;
  var payload;
  try { payload = JSON.stringify(_idbCacheSnapshot); }
  catch(e) { _idbWriteInFlight = false; return; }
  _idbSet(_IDB_KEY, payload).then(function(){
    if (window._cacheSaveFailed) { window._cacheSaveFailed = false; _hideStorageFullWarning(); }
  }).catch(function(e){
    console.error('[CDC] IndexedDB cache write failed:', e && e.message);
  }).finally(function(){
    _idbWriteInFlight = false;
    if (_idbWriteDirty) _idbScheduleWrite();   // a save arrived mid-write — flush latest
  });
}

// Runs ONCE at boot, before anything calls getDB(). Hydrates the sync mirror
// from IndexedDB, and on first run migrates the old localStorage cache over,
// then frees the localStorage space.
async function _idbBootLoad() {
  try {
    await _idbOpen();
    var stored = await _idbGet(_IDB_KEY);      // JSON string or null
    if (stored) {
      try { _idbCacheSnapshot = JSON.parse(stored); } catch(e) { _idbCacheSnapshot = null; }
    }
    // One-time migration: old localStorage cache → IndexedDB
    if (!_idbCacheSnapshot) {
      var legacy = '';
      try { legacy = localStorage.getItem(CACHE_KEY) || ''; } catch(e) {}
      if (legacy) {
        try { _idbCacheSnapshot = JSON.parse(legacy); } catch(e) { _idbCacheSnapshot = null; }
        if (_idbCacheSnapshot) {
          try { await _idbSet(_IDB_KEY, legacy); console.log('[CDC] Cache migrated localStorage → IndexedDB ('+(legacy.length/1024/1024).toFixed(2)+'MB)'); } catch(e) {}
        }
      }
    }
    window._idbReady = true;
    // Free the old localStorage cache — it lives in IndexedDB now.
    try { if (localStorage.getItem(CACHE_KEY)) { localStorage.removeItem(CACHE_KEY); console.log('[CDC] Legacy localStorage cache cleared (space freed)'); } } catch(e) {}
    if (typeof _hideStorageFullWarning === 'function') _hideStorageFullWarning();
  } catch(e) {
    // IndexedDB unavailable (e.g. some private-mode configs) — app keeps working
    // on the old localStorage path via the fallback in _saveCache/_loadCache.
    console.warn('[CDC] IndexedDB unavailable, using localStorage fallback:', e && e.message);
    window._idbReady = false;
  }
}

function _saveCache(db) {
  // Build the lean snapshot (heavy audit/ERA collections excluded — see notes).
  var lean = {};
  for (var k in db) { if (_CACHE_EXCLUDED_KEYS.indexOf(k) === -1) lean[k] = db[k]; }
  // Keep the synchronous mirror fresh so the next first-paint _loadCache() is current.
  _idbCacheSnapshot = lean;

  // Primary path: IndexedDB (no ~5MB quota — this is the whole point of the migration).
  if (window._idbReady && _idbDB) {
    _idbScheduleWrite();
    return;
  }

  // ?? Fallback: IndexedDB unavailable → old localStorage behavior, unchanged ??
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify(lean));
    if (window._cacheSaveFailed) { window._cacheSaveFailed = false; _hideStorageFullWarning(); }
  } catch(e) {
    // localStorage has a fixed ~5-10MB quota per origin. Detect the overflow,
    // do a reduced save so core records survive a refresh, and warn loudly.
    window._cacheSaveFailed = true;
    console.error('[CDC] CRITICAL: localStorage cache save failed (IndexedDB also unavailable) —', e.name, e.message);
    try {
      var lean2 = {};
      for (var k2 in db) { if (_CACHE_EXCLUDED_KEYS.indexOf(k2) === -1) lean2[k2] = db[k2]; }
      var trimmed = JSON.parse(JSON.stringify(lean2));
      var strippedCount = 0;
      (trimmed.patients||[]).forEach(function(p){
        if (p.photo && p.photo.indexOf('data:')===0) { p.photo=''; strippedCount++; }
        (p.documents||[]).forEach(function(d){ if (d.data) { d.data = null; d._strippedForSpace = true; strippedCount++; } });
        (p.superbills||[]).forEach(function(sb){ if (sb.data) { sb.data = null; sb._strippedForSpace = true; strippedCount++; } });
      });
      localStorage.setItem(CACHE_KEY, JSON.stringify(trimmed));
      console.warn('[CDC] Saved a reduced cache (stripped '+strippedCount+' attachment(s)) to avoid total data loss.');
    } catch(e2) {
      console.error('[CDC] Even the reduced cache save failed:', e2.message);
    }
    _showStorageFullWarning();
  }
}

// Diagnostic — run _inspectCacheSize() from the console to see exactly which
// collection is responsible for the bulk of the local cache, in KB, instead
// of guessing. (Numbers are approximate — JS string length, not exact UTF-8
// byte size, but close enough to identify the real offender.)
function _inspectCacheSize() {
  var db = getDB();
  var rows = [];
  var memTotal = 0;       // size of the full in-memory db
  var cacheTotal = 0;     // size of what ACTUALLY gets persisted (lean snapshot)
  for (var k in db) {
    var sz = 0;
    try { sz = JSON.stringify(db[k]).length; } catch(e) {}
    memTotal += sz;
    var excluded = _CACHE_EXCLUDED_KEYS.indexOf(k) !== -1;
    if (!excluded) cacheTotal += sz;
    rows.push({key:k, kb: (sz/1024).toFixed(1), excluded: excluded});
  }
  rows.sort(function(a,b){ return parseFloat(b.kb)-parseFloat(a.kb); });
  console.log('--- ClaimDataCare cache size breakdown ---');
  rows.forEach(function(r){
    console.log(r.key.padEnd(20), (r.kb+' KB').padStart(12), r.excluded ? '  (NOT cached — excluded)' : '');
  });
  console.log('');
  console.log('IN MEMORY total :', (memTotal/1024/1024).toFixed(2), 'MB');
  console.log('CACHED snapshot :', (cacheTotal/1024/1024).toFixed(2), 'MB');
  var backend = (window._idbReady && _idbDB) ? 'IndexedDB (no ~5MB limit — hundreds of MB available)' : 'localStorage FALLBACK (~5-10MB limit — IndexedDB unavailable)';
  console.log('Cache backend   :', backend);
  // Measured payload actually stored:
  if (window._idbReady && _idbDB) {
    _idbGet(_IDB_KEY).then(function(v){
      if (v != null) console.log('Measured in IDB :', (v.length/1024/1024).toFixed(2), 'MB  (actual string in IndexedDB right now)');
    });
  } else {
    try { var raw = localStorage.getItem(CACHE_KEY); if (raw != null) console.log('Measured cache  :', (raw.length/1024/1024).toFixed(2), 'MB  (actual string in localStorage)'); } catch(e) {}
  }
  return rows;
}

// Loud, persistent, impossible-to-miss banner — shown the moment a local
// save fails, telling the user not to navigate away until it clears.
function _showStorageFullWarning() {
  if (document.getElementById('cdc-storage-warning')) return;
  var bar = document.createElement('div');
  bar.id = 'cdc-storage-warning';
  bar.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:999999;background:#b91c1c;color:#fff;padding:10px 16px;font-size:13px;font-weight:700;text-align:center;box-shadow:0 2px 8px rgba(0,0,0,.3);display:flex;align-items:center;justify-content:center;gap:10px';
  bar.innerHTML = '<span>⚠ STORAGE FULL — your browser ran out of space to save data locally. '+
    '<u style="cursor:pointer" onclick="alert(\'Your device storage for this app is full. To fix:\\n\\n1. Do NOT close or refresh this tab yet.\\n2. Ask support to help clear old superbill/document attachments from old patients.\\n3. Once cleared, refresh to confirm your recent work is saved.\\n\\nClosing this tab now may lose anything not yet confirmed saved.\')">What do I do?</u></span>'+
    '<button onclick="document.getElementById(\'cdc-storage-warning\').remove()" title="Dismiss (will reappear if saving fails again)" style="background:rgba(255,255,255,.2);border:none;color:#fff;border-radius:5px;width:22px;height:22px;cursor:pointer;font-size:15px;line-height:1;flex-shrink:0">&times;</button>';
  document.body.appendChild(bar);
}
function _hideStorageFullWarning() {
  document.getElementById('cdc-storage-warning')?.remove();
}

function _loadCache() {
  // Primary: the IndexedDB snapshot hydrated at boot (no quota limit).
  if (_idbCacheSnapshot) return _idbCacheSnapshot;
  // Fallback: legacy localStorage cache (if IndexedDB is unavailable, or in the
  // brief case getDB runs before _idbBootLoad resolves — boot awaits it first).
  try {
    const raw = localStorage.getItem(CACHE_KEY) || '';
    return raw ? JSON.parse(raw) : null;
  } catch(e) { return null; }
}

// ?? Load all collections from Firestore ?????????????????????????????????????
async function loadFromFirestoreWhenReady() {
  return new Promise(function(resolve) {
    var tries = 0;
    function attempt() {
      tries++;
      if (tries > 30) { resolve(); return; } // timeout after 3s
      if (_fbReady && _db) {
        loadFromFirestore().then(resolve).catch(resolve);
      } else {
        setTimeout(attempt, 100);
      }
    }
    attempt();
  });
}

async function loadFromFirestore() {
  if (!_fbReady || !_db) {
    const cached = _loadCache();
    if (cached) { _localDB = _mergeEmpty(cached); console.log('Loaded from cache (offline)'); }
    return;
  }
  if (window._restoreInProgress) return;

  // ── Load config first (palette/theme) so UI looks right immediately ──
  try {
    const configDoc = await _db.collection('meta').doc('config').get();
    if (configDoc.exists) {
      const cfg = configDoc.data();
      _apiConfigCache = cfg;
      if (cfg.acctKey) { try { localStorage.setItem(API_CFG_KEY, JSON.stringify(cfg)); } catch(e) {} }
      try { applyTheme(); } catch(e) {}
    }
  } catch(e) {}

  setFbStatus('Syncing...', 'amber');

  // ── Load critical collections first (providers, patients, claims) ──
  try {
    const [providers, patients, claims, configDoc2, usersDoc, cmDoc] = await Promise.all([
      _fsReadCollection('providers'),
      _fsReadCollection('patients'),
      _fsReadCollection('claims'),
      _db.collection('meta').doc('config').get(),
      _db.collection('meta').doc('users').get(),
      _db.collection('meta').doc('cmData').get(),
    ]);

    // Merge collections — Firestore wins per-document by updatedAt
    if (!_localDB) _localDB = _mergeEmpty({});
    _localDB.providers = _mergeByUpdatedAt(_localDB.providers||[], providers);
    _localDB.patients  = _mergeByUpdatedAt(_localDB.patients||[], patients);
    _localDB.claims    = _mergeByUpdatedAt(_localDB.claims||[], claims);

    if (usersDoc.exists) {
      _usersCache = usersDoc.data().list || [];
      try { localStorage.setItem(USERS_KEY, JSON.stringify(_usersCache)); } catch(e) {}
    }

    // Load CM data from Firestore (merged with empty template to ensure all keys exist)
    if (cmDoc.exists) {
      _localDB.cm = Object.assign(_cmEmpty(), cmDoc.data());
      console.log('[CDC] CM data loaded from Firestore: ' + (_localDB.cm.clients||[]).length + ' clients');
    } else {
      // Check if there is legacy data in localStorage to migrate
      try {
        var _cmLegacy = localStorage.getItem(CM_KEY);
        if (_cmLegacy) {
          var _cmParsed = JSON.parse(_cmLegacy);
          if (_cmParsed && typeof _cmParsed === 'object') {
            _localDB.cm = Object.assign(_cmEmpty(), _cmParsed);
            _saveCMToFirestore(_localDB.cm);
            try { localStorage.removeItem(CM_KEY); } catch(e) {}
            console.log('[CDC] CM data migrated from localStorage to Firestore on load');
          }
        }
      } catch(e) {}
      if (!_localDB.cm) _localDB.cm = _cmEmpty();
    }

    setFbStatus('', 'green');
    console.log('Core loaded: ' + patients.length + ' patients, ' + claims.length + ' claims');

    // Trigger _afterLoad-style update with core data
    try {
      const s = getSession();
      if (s && providers.length) {
        const savedId = s.activeBillingProviderId;
        const vp = (savedId && providers.find(function(p){ return p.id===savedId; })) || providers[0];
        activeProviderId = vp.id;
        s.activeBillingProviderId = activeProviderId;
        setSession(s);
        rebuildProvSel();
      } else if (!activeProviderId && patients.length) {
        const pIds = [...new Set(patients.map(function(p){ return p.providerId; }).filter(Boolean))];
        if (pIds.length) activeProviderId = pIds[0];
      }
      try { renderDashboard(); } catch(e) {}
      updateBadges();
    } catch(e) {}

  } catch(err) {
    console.warn('Firestore core load failed:', err.message, err.code);
    if (err.code === 'permission-denied') {
      setFbStatus('Auth error', 'red');
      console.error('PERMISSION DENIED — Check Firestore rules');
    } else {
      setFbStatus('Offline', 'amber');
    }
    const cached = _loadCache();
    if (cached) { _localDB = _mergeEmpty(cached); }
    return;
  }

  // ── Load secondary collections in background ──────────────────
  try {
    const [
      facilities, rendering, referring, services, serviceGroups,
      appointments, notes, invoicingIssuers, invoicingClients, invoices,
      insurances, intakeClients, intakeForms, intakeSubmissions, evaluations,
      eobBatches, eobUnmatched, eraPreviewQueue,
      claimLogsSnap, claimEOBSnap, settingsSnap
    ] = await Promise.all([
      _fsReadCollection('facilities'),
      _fsReadCollection('rendering'),
      _fsReadCollection('referring'),
      _fsReadCollection('services'),
      _fsReadCollection('serviceGroups'),
      _fsReadCollection('appointments'),
      _fsReadCollection('notes'),
      _fsReadCollection('invoicingIssuers'),
      _fsReadCollection('invoicingClients'),
      _fsReadCollection('invoices'),
      _fsReadCollection('insurances'),
      _fsReadCollection('intakeClients'),
      _fsReadCollection('intakeForms'),
      _fsReadCollection('intakeSubmissions'),
      _fsReadCollection('evaluations'),
      _fsReadCollection('eobBatches'),
      _fsReadCollection('eobUnmatched'),
      _fsReadCollection('eraPreviewQueue'),
      _db.collection('claimLogs').get(),
      _db.collection('claimEOB').get(),
      _db.collection('appdata').doc('settings').get(),
    ]);

    const claimLogs = {};
    claimLogsSnap.docs.forEach(function(d){ claimLogs[d.id] = d.data().entries||[]; });
    const claimEOB = {};
    claimEOBSnap.docs.forEach(function(d){ claimEOB[d.id] = d.data().entries||[]; });

    // Parse settings from Firestore single doc
    var fsSettings = settingsSnap.exists ? settingsSnap.data() : {};
    // Merge with existing local settings (don't overwrite local if Firestore is empty)
    var mergedSettings = Object.assign({}, fsSettings, _localDB.settings||{});
    // Firestore wins for cursor keys (lastERAID_*)
    Object.keys(fsSettings).forEach(function(k){ mergedSettings[k] = fsSettings[k]; });

    Object.assign(_localDB, {
      facilities, rendering, referring, services, serviceGroups,
      appointments, notes, claimLogs, claimEOB,
      invoicingIssuers, invoicingClients, invoices, insurances,
      intakeClients, intakeForms, intakeSubmissions, evaluations,
      eobBatches, eobUnmatched, eraPreviewQueue,
      settings: mergedSettings,
    });

    _saveCache(_localDB);
    console.log('All data loaded from Firestore');
    // Refresh dashboard with complete data
    try { renderDashboard(); updateBadges(); } catch(e) {}

  } catch(err) {
    console.warn('Secondary Firestore load failed:', err.message);
  }
}

// Ensure all keys exist in a db object
function _mergeEmpty(db) {
const empty = {
providers:[], facilities:[], rendering:[], referring:[],
patients:[], claims:[], services:[], serviceGroups:[],
appointments:[], notes:[], claimLogs:{}, claimEOB:{},
invoicingIssuers:[], invoicingClients:[], invoices:[], insurances:[],
intakeClients:[], intakeForms:[], intakeSubmissions:[], evaluations:[],
eobBatches:[], eobUnmatched:[], eraPreviewQueue:[],
settings:{},
cm: null  // CM data stored as a sub-object; null means not yet loaded
};
const merged = Object.assign(empty, db || {});
// Ensure cm sub-keys exist if cm is present
if (merged.cm) merged.cm = Object.assign({
  clients:[], workers:[], plans:[], notes:[], billing:[],
  referrals:[], eligibility:[], assessments:[], tasks:[],
  authorizations:[], communityReferrals:[], encounters:[],
  discharges:[], cmSettings:{ billingRate:12.50, defaultCode:'T1017' }
}, merged.cm);
return merged;
}

// ?? setDB: mutate state and sync changed collection to Firestore ?????????????
// Instead of writing everything, detect which collection changed and write only that
// ????????????????????????????????????????????????????????????????????????????
// FIRESTORE PERSISTENCE LAYER v2
// Architecture: individual documents in typed collections (not one monolithic doc)
//
// Collections:
// providers/{id} — billing providers
// patients/{id} — patients (each own doc)
// claims/{id} — claims (each own doc)
// facilities/{id} — facilities
// rendering/{id} — rendering providers
// referring/{id} — referring providers
// services/{id} — CPT services
// serviceGroups/{id} — service groups
// appointments/{id} — appointments
// notes/{id} — encounter notes
// claimLogs/{claimId} — claim log entries
// claimEOB/{claimId} — EOB records
// invoicingIssuers/{id} — billing entities
// invoicingClients/{id} — clients
// invoices/{id} — invoices
// meta/config — app config (apiKey, etc.)
// meta/users — users list
//
// All writes go to Firestore first. localStorage is a read-time cache only.
// ????????????????????????????????????????????????????????????????????????????

// ?? Constants ???????????????????????????????????????????????????????????????
// USERS_KEY already defined in auth section

// ?? Helpers ??????????????????????????????????????????????????????????????????

// Write an array of objects to a Firestore collection using batched writes
function setDB(fn) {
const before = JSON.parse(JSON.stringify(getDB()));
const db = getDB();
fn(db);
_localDB = db;
_saveCache(_localDB);

if (!_fbReady || !_db) return;

// Detect which collections changed and sync only those
var _syncColls = [
'providers','facilities','rendering','referring',
'patients','claims','services','serviceGroups',
'appointments','notes','invoicingIssuers','invoicingClients','invoices','insurances',
'intakeClients','intakeForms','intakeSubmissions','evaluations',
'eobBatches','eobUnmatched','eraPreviewQueue','settings'
];

for (var _ci = 0; _ci < _syncColls.length; _ci++) {
var coll = _syncColls[_ci];
const prev = before[coll] || [];
const next = db[coll] || [];
if (JSON.stringify(prev) !== JSON.stringify(next)) {
window._pendingFirestoreSyncs = (window._pendingFirestoreSyncs||0) + 1;
_fsSyncCollection(coll, next)
  .catch(e => { console.warn(`Firestore ${coll} sync failed:`, e.message); window._lastSyncError = coll+': '+e.message; })
  .finally(() => { window._pendingFirestoreSyncs = Math.max(0, (window._pendingFirestoreSyncs||1) - 1); });
}
}

// Sync claimLogs and claimEOB
const objColls = [['claimLogs','claimLogs'],['claimEOB','claimEOB']];
for (const [key, coll] of objColls) {
if (JSON.stringify(before[key]) !== JSON.stringify(db[key])) {
const obj = db[key] || {};
const batch = _db.batch();
Object.entries(obj).forEach(([id, entries]) => {
batch.set(_db.collection(coll).doc(String(id)), { entries: entries || [] });
});
batch.commit().catch(e => console.warn(`${coll} sync failed:`, e.message));
}
}
// Sync settings object as single Firestore document
if (JSON.stringify(before.settings) !== JSON.stringify(db.settings)) {
  _db.collection('appdata').doc('settings').set(db.settings||{})
    .catch(function(e){ console.warn('settings sync failed:', e.message); });
}
}

